  ui_story_5037_50370101_131_dialog_content = "나, 난...",
  ui_story_5037_50370101_132_dialog_content = "컷!",
  ui_story_5037_50370101_133_dialog_content = "PlayerName, 카메라 앞에서 조금만 편하게 얘기해 줄 수 있을까?",
  ui_story_5037_50370101_134_dialog_content = "우리가 지금 찍고 있는 건 리얼리티 프로그램이니까 카메라를 의식할 필요는 없어~",
  ui_story_5037_50370101_135_dialog_content = "미안! 사무실 문을 열자마자 녹화 시작인 줄은 몰랐거든.",
  ui_story_5037_50370101_136_dialog_content = "내가 리얼리티 프로그램 분야에서 이름을 날릴 수 있을지는\n전부 이 작품에 달려 있어!",
  ui_story_5037_50370101_137_dialog_content = "PlayerName, 그럼 지금부터 난 없는 사람이고 내 카메라도 없는 거야.",
  ui_story_5037_50370101_138_dialog_content = "평소처럼 네 진실된 모습을 보여주면 돼, 알겠지?",
  ui_story_5037_50370101_139_dialog_content = "응...",
  ui_story_5037_50370101_140_dialog_content = "그럼 다시 갈게!",
  ui_story_5037_50370101_141_dialog_content = "PlayerName 프로듀서, 오느라 수고했어.",
  ui_story_5037_50370101_142_dialog_content = "......",
  ui_story_5037_50370101_143_dialog_content = "프로듀서?",
  ui_story_5037_50370101_144_dialog_content = "골디...",
  ui_story_5037_50370101_145_dialog_content = "방금 나 엄청 심각한 문제를 깨달았어!",
  ui_story_5037_50370101_146_dialog_content = "샤엘 씨가 사무실에 오면 내 경쟁자가 있을 거랬는데...",
  ui_story_5037_50370101_147_dialog_content = "그게 넌 아니지?!",
  ui_story_5037_50370101_148_dialog_content = "경쟁자?",
  ui_story_5037_50370101_149_dialog_content = "키아로, 빨리!",
  ui_story_5037_50370101_150_dialog_content = "루!",
  ui_story_5037_50370101_151_dialog_content = "사부가 여기서 도망 못 가게 잘 보고 있어!",
  ui_story_5037_50370101_152_dialog_content = "피아~ 그렇게 긴장할 필요까진 없잖아~",
  ui_story_5037_50370101_153_dialog_content = "그냥 잠깐 나가서 케이크 조그만 거 하나만 먹고 금방 돌아온다니까~",
  ui_story_5037_50370101_154_dialog_content = "트레이닝 기간에는 고열량 음식을 마음대로 먹으면 안 돼.",
  ui_story_5037_50370101_155_dialog_content = "피아가 가서 배가 배부르면서도 저칼로리인 음식들을 찾아와 줄 테니까,\n사부는 트레이닝하고 있어.",
  ui_story_5037_50370101_156_dialog_content = "...정말 고맙다, 내 제자야.",
  ui_story_5037_50370101_157_dialog_content = "아무래도 우리 경쟁자는 이미 트레이닝을 시작한 것 같아.",
  ui_story_5037_50370101_158_dialog_content = "어? PlayerName 아니야? 샤엘 사장님이 말한 경쟁자가 너였어?",
  ui_story_5037_50370101_159_dialog_content = "흥! 상대가 아무리 너라도 피아는 안 봐 줄 거야.",
  ui_story_5037_50370101_160_dialog_content = "사부가 너희 둘을 쓰러트리게 만들어서 상금을 가져갈 테니까!",
  ui_story_5037_50370101_161_dialog_content = "참! 내가 없을 때 우리가 트레이닝하는 거 훔쳐볼 생각도 하지 마!",
  ui_story_5037_50370101_162_dialog_content = "우리 경쟁자는 바로 저 두 사람인가 봐.",
  ui_story_5037_50370101_163_dialog_content = "맨날 환상동물 연구만 하는 사람들이 아이돌 리얼리티 프로는 갑자기 왜?",
  ui_story_5037_50370101_164_dialog_content = "앗, 잠깐, 방금 「우리 경쟁자」라고 했어?",
  ui_story_5037_50370101_165_dialog_content = "내가 맡을 아이돌이 골디 너란 말이야?!",
  ui_story_5037_50370101_166_dialog_content = "샤엘 사장님이 얘기 안 해 주셨어?",
  ui_story_5037_50370101_167_dialog_content = "맞아. 이제부터 잘 부탁해, 프로듀서~",
  ui_story_5037_50370101_168_dialog_content = "골디는 이미 대단한데, 내가 더 할 게 있을까?",
  ui_story_5037_50370101_169_dialog_content = "후훗, 내가 좀 유명한 아이돌인 건 맞지만, 그것도 옛날얘기야.",
  ui_story_5037_50370101_170_dialog_content = "지금의 난 이제 막 스타 엔터테인먼트에 들어온 거라, 내 실력을 증명해야 해.",
  ui_story_5037_50370101_171_dialog_content = "그래서 PlayerName 씨한테 부탁해야 할 게 아주 많다구~",
  ui_story_5037_50370101_172_dialog_content = "거기다...",
  ui_story_5037_50370101_173_dialog_content = "샤엘 사장님이 이번에 경쟁자까지 붙여 줄 줄은 몰랐어.",
  ui_story_5037_50370101_174_dialog_content = "이런 일은 나도 처음이라 조금 긴장되네... 에헷~",
  ui_story_5037_50370101_175_dialog_content = "내가 제대로 못 하면 골디의 커리어에도 영향을 미치는 거 아니야?",
  ui_story_5037_50370101_176_dialog_content = "갑자기 부담이 너무 큰데...",
  ui_story_5037_50370101_177_dialog_content = "프로듀서, 벌써부터 한참 나중의 일을 걱정할 필요는 없지 않을까?",
  ui_story_5037_50370101_178_dialog_content = "지금은 지금의 일부터 해내는 게 중요해.",
  ui_story_5037_50370101_179_dialog_content = "그래야 나중에 결과가 어떻든 후회하지 않는다구~",
  ui_story_5037_50370101_180_dialog_content = "마, 맞는 말이야!",
  ui_story_5037_50370101_181_dialog_content = "근데 용기를 북돋는 그런 멘트는 원래 프로듀서가 아이돌한테 하는 거 아닌가?",
  ui_story_5037_50370101_182_dialog_content = "어째서 반대로 내가 위로를 받은 거지?",
  ui_story_5037_50370101_183_dialog_content = "정신 차리자! 골디의 발전을 위해 나부터 힘내야 해!",
  ui_story_5037_50370101_184_dialog_content = "나 한 사람만을 위한 일이 아니야~",
  ui_story_5037_50370101_185_dialog_content = "응?",
  ui_story_5037_50370101_186_dialog_content = "우리 두 사람의 발전을 위해서지!",
  ui_story_5037_50370101_187_dialog_content = "아... 그렇지, 우리 두 사람을 위해서!",
  ui_story_5037_50370101_188_dialog_content = "근데 우리 목표가 뭔지 아직도 모르겠는데, 난 대체 뭘 해야 하는 거야?",
  ui_story_5037_50370101_189_dialog_content = "우리 목표는 정해진 기간 안에 세 번의 콘서트를 성공적으로 개최하는 거야.",
  ui_story_5037_50370101_190_dialog_content = "그리고 PlayerName 씨가 해야 할 일은 많아!",
  ui_story_5037_50370101_191_dialog_content = "날 위해 연습 일정을 잡는다든지, 나랑 맞는 홍보 일정을 잡는다든지,\n곡을 만들어준다든지 등등등.",
  ui_story_5037_50370101_192_dialog_content = "...내가 전혀 모르는 영역이잖아.",
  ui_story_5037_50370101_193_dialog_content = "프로듀서라면 금방 감을 잡을 거라고 믿어!",
  ui_story_5037_50370101_194_dialog_content = "나 전에 골디의 프로듀서는 누구였어? 선배님한테 자문을 구해보는 건 어떨까?",
  ui_story_5037_50370101_195_dialog_content = "후후, 전 프로듀서는 바로 나였어~",
  ui_story_5037_50370101_196_dialog_content = "어? 그럼 혼자서 다 하느라 힘들진 않았어?",
  ui_story_5037_50370101_197_dialog_content = "힘들긴 했지만, 다 지난 일이니까.",
  ui_story_5037_50370101_198_dialog_content = "지금은 담당 프로듀서도 있는 아이돌인걸~",
  ui_story_5037_50370101_199_dialog_content = "하하...",
  ui_story_5037_50370101_200_dialog_content = "시간이 없으니까, 일단 나랑 다니면서 프로듀서가 해야 할 일을 익혀볼까?",
  ui_story_5037_50370101_201_dialog_content = "좋아!",
  ui_story_5037_50370201_1_dialog_content = "콘서트가 곧 시작인데...",
  ui_story_5037_50370201_2_dialog_content = "특별히 골디를 위해 준비한 목캔디를 백스테이지에 가져오는 걸 깜박했어!",
  ui_story_5037_50370201_3_dialog_content = "<color=#828282>촤르륵──</color>",
  ui_story_5037_50370201_4_dialog_content = "휴우~ 내가 참고서 안에다 뒀었구나...",
  ui_story_5037_50370201_5_dialog_content = "찾아서 다행이야. 얼른 골디한테 갖다줘야지!",
  ui_story_5037_50370201_6_dialog_content = "사부! 빨리!",
  ui_story_5037_50370201_7_dialog_content = "어, 피아 목소린데?",
  ui_story_5037_50370201_8_dialog_content = "아직 백스테이지에 안 간 건가?",
  ui_story_5037_50370201_9_dialog_content = "곧 있으면 콘서트가 시작되는데, 왜 여기 숨어서 쿨쿨 잠이나 자고 있는 건데?",
  ui_story_5037_50370201_10_dialog_content = "한참 찾았잖아!",
  ui_story_5037_50370201_11_dialog_content = "잠을 푹 자두지 않으면 올라가서 공연할 힘이 없어~",
  ui_story_5037_50370201_12_dialog_content = "금방 갈 테니까 조금만 더 쉬게 해 주라.",
  ui_story_5037_50370201_13_dialog_content = "<size=45>사──부──!</size>",
  ui_story_5037_50370201_14_dialog_content = "공연이 코앞인데 사부는 긴장도 안 돼?",
  ui_story_5037_50370201_15_dialog_content = "그거 알아? 골디랑 PlayerName 쪽은 리허설을 벌써 몇 번이나 했다구!",
  ui_story_5037_50370201_16_dialog_content = "그 둘이 했으니까 우린 관두자~",
  ui_story_5037_50370201_17_dialog_content = "굳이 똑같은 일에 시간이랑 에너지를 낭비할 필요는 없잖아.",
  ui_story_5037_50370201_18_dialog_content = "하아~ 허접 사부의 허접 발언... 또 시작이야?",
  ui_story_5037_50370201_19_dialog_content = "트레이닝은 그렇다 쳐! 근데 지금은 정신 차리고 열심히 맞서야 할 거 아냐!",
  ui_story_5037_50370201_20_dialog_content = "PlayerName 걔네한테 지면 기본 급여만 밭고 땡이라구! 상금은 날아가는 거야!",
  ui_story_5037_50370201_21_dialog_content = "좋은 생각이 있어! 지금이라도 나 대신 시라가 나가는 건 어떨까?",
  ui_story_5037_50370201_22_dialog_content = "안! 돼!",
  ui_story_5037_50370201_23_dialog_content = "피아는 왜 다 늙은 이 사부를 괴롭히려고 하는 걸까? 난 도무지 이해가 안 돼~",
  ui_story_5037_50370201_24_dialog_content = "나한테 예전에 아이돌로 데뷔할 뻔했었다면서 허풍을 늘어놨던 게\n어디 사는 누구였더라?",
  ui_story_5037_50370201_25_dialog_content = "피아, 난 허풍 떤 적 없어. 그거 다 진짜야.",
  ui_story_5037_50370201_26_dialog_content = "그럼 잘 된 거 아냐?",
  ui_story_5037_50370201_27_dialog_content = "오늘이면 정식으로 데뷔하게 되는 건데, 안 기뻐?",
  ui_story_5037_50370201_28_dialog_content = "그냥 설렁설렁 대충대충 하는 시늉만 하면 돼~\n내가 진짜 아이돌이 되려는 것도 아니잖아.",
  ui_story_5037_50370201_29_dialog_content = "아이돌이 될 거면 환상동물 트레이너들의 아이돌이 되는 게 맞지!",
  ui_story_5037_50370201_30_dialog_content = "그럼 더 열심히 돈을 벌어서 사부가 집에서 기르는 환상동물들을 더 잘 돌봐야지!",
  ui_story_5037_50370201_31_dialog_content = "출연료만 가지고는 사부 혼자 입에 풀칠밖에 못 해.",
  ui_story_5037_50370201_32_dialog_content = "PlayerName하고 골디를 이겨서 추가로 상금을 받아야지 환상동물들의\n삶의 질을 높여줄 수 있다구!",
  ui_story_5037_50370201_33_dialog_content = "그래서 나도 의뢰를 받아서 열심히 일했었잖아...",
  ui_story_5037_50370201_34_dialog_content = "사부가 10년 동안 번 게 이번 출연료보다도 적거든?",
  ui_story_5037_50370201_35_dialog_content = "이 상태로 10년 뒤면, 사부 때문에 불쌍한 환상동물들이 다 굶어 죽어 버릴지도 몰라!",
  ui_story_5037_50370201_36_dialog_content = "그니까 이번엔 사부를 제대로 지켜봐 주겠어!\n마지막에 상금을 가져가는 건 우리가 될 거야!",
  ui_story_5037_50370201_37_dialog_content = "(피아랑 비크 씨가 뭐라는지 잘 안 들렸지만...)",
  ui_story_5037_50370201_38_dialog_content = "(피아의 저 당찬 기세에 비하면 난...)",
  ui_story_5037_50370201_39_dialog_content = "우와~ 목캔디 덕에 입 안이 시원해졌어.",
  ui_story_5037_50370201_40_dialog_content = "이런 것까지 준비하다니, 프로듀서는 정말 세심하네!",
  ui_story_5037_50370201_41_dialog_content = "......",
  ui_story_5037_50370201_42_dialog_content = "프로듀서, 왜 그래?",
  ui_story_5037_50370201_43_dialog_content = "아냐, 마음에 든다니 정말 기뻐.",
  ui_story_5037_50370201_44_dialog_content = "앞으로 다른 맛도 준비해 볼게. 맛있고 목에도 좋은 걸로!",
  ui_story_5037_50370201_45_dialog_content = "흐음, 이제 준비는 거의 다 끝난 것 같네?",
  ui_story_5037_50370201_46_dialog_content = "네! 반드시 샤엘 사장님이 만족할 만한 결과물을 낼게요~",
  ui_story_5037_50370201_47_dialog_content = "그런 자신감 아주 마음에 들어. 그럼 기대할게.",
  ui_story_5037_50370201_48_dialog_content = "저기... 샤엘 씨!",
  ui_story_5037_50370201_49_dialog_content = "응? 프로듀서, 무슨 일이야?",
  ui_story_5037_50370201_50_dialog_content = "이따가 비크 씨가 골디랑 같이 무대에 서는 건가요?",
  ui_story_5037_50370201_51_dialog_content = "무슨 걱정이라도 있어?",
  ui_story_5037_50370201_52_dialog_content = "아, 그, 그냥 공연 순서를 확인하고 싶어서요!",
  ui_story_5037_50370201_53_dialog_content = "공연 순서는 네가 계획한 대로 진행하면 돼.",
  ui_story_5037_50370201_54_dialog_content = "비크의 콘서트 장소는 여기가 아니라 옆 무대거든.",
  ui_story_5037_50370201_55_dialog_content = "곧 있으면 골디와 비크의 콘서트가 동시에 시작될 거야.",
  ui_story_5037_50370201_56_dialog_content = "옆 무대요?! 어쩐지 백스테이지에서 비크 씨가 안 보인다 했네요.",
  ui_story_5037_50370201_57_dialog_content = "샤엘 사장님은 오늘을 염두에 두고 이 무대를 지은 거였군요?",
  ui_story_5037_50370201_58_dialog_content = "그래서 극장에 똑같은 쌍둥이 무대 두 개를 만든 거였네요.",
  ui_story_5037_50370201_59_dialog_content = "어? 똑같은 쌍둥이 무대?",
  ui_story_5037_50370201_60_dialog_content = "달링, 깜짝 놀라는 건 당연해. 이건 내가 야심 차게 준비한 작품이거든.",
  ui_story_5037_50370201_61_dialog_content = "두 무대는 복도 하나를 사이에 두고 있어.",
  ui_story_5037_50370201_62_dialog_content = "공연이 시작되면 관객은 취향에 따라 두 무대 사이를 자유롭게 다닐 수 있어.",
  ui_story_5037_50370201_63_dialog_content = "그리고 마지막에 더 많은 관객의 발길을 붙잡은 쪽이 승리야.",
  ui_story_5037_50370201_64_dialog_content = "관객한테는 새로운 경험이고, 우리 리얼리티 프로그램의 관람 포인트이기도 해~",
  ui_story_5037_50370201_65_dialog_content = "리리카, 방송용 버전에는 방금 내가 했던 말 편집해 줘~",
  ui_story_5037_50370201_66_dialog_content = "얼마든지요~!",
  ui_story_5037_50370201_67_dialog_content = "(이제 카메라에 익숙해져서, 리리카가 옆에 있었단 것도 잊고 있었네.)",
  ui_story_5037_50370201_68_dialog_content = "그럼, 달링들, 건투를 빌게~",
  ui_story_5037_50370201_69_dialog_content = "으으, 왜 이런 일을 미리 말 안 해준 거지?",
  ui_story_5037_50370201_70_dialog_content = "우리가 공연할 곡을 다시 봐야겠어. 관객의 이목을 집중시킬 포인트가 있어야 해!",
  ui_story_5037_50370201_71_dialog_content = "아! 조명이랑 음향도 아직 확인 못 했는데...",
  ui_story_5037_50370201_72_dialog_content = "프로듀서, 아까 확인했었어.",
  ui_story_5037_50370201_73_dialog_content = "아, 그, 그런가?",
  ui_story_5037_50370201_74_dialog_content = "하하... 내가 왜 이러지? 방금까지 뭘 했는지 갑자기 기억이 안 나는 느낌이야.",
  ui_story_5037_50370201_75_dialog_content = "프로듀서, 긴장한 거야?",
  ui_story_5037_50370201_76_dialog_content = "괜찮아. 준비하는 동안 충분히 노력했잖아!",
  ui_story_5037_50370201_77_dialog_content = "오늘만큼은 결과에 연연하지 말고...",
  ui_story_5037_50370201_78_dialog_content = "지금까지 준비한 공연 내용들을 관객한테 즐거운 마음으로 전달한다면\n그걸로 이긴 셈 치자~",
  ui_story_5037_50370201_79_dialog_content = "그, 그래, 골디 네 말이 맞아.",
  ui_story_5037_50370201_80_dialog_content = "평소 실력대로 보여주면 돼!",
  ui_story_5037_50370201_81_dialog_content = "공연까지 <color=#793f76>5분</color> 남았습니다!",
  ui_story_5037_50370201_82_dialog_content = "으아아아아!",
  ui_story_5037_50370201_83_dialog_content = "이대론 안 돼! 아직 못 끝낸 일이 남은 것 같은데!",
  ui_story_5037_50370201_84_dialog_content = "후훗, 마음 편히 가져. 지금은 침착하게 공연 시작을 기다리는 게 최선이야~",
  ui_story_5037_50370201_85_dialog_content = "그, 그래?",
  ui_story_5037_50370201_86_dialog_content = "미안해. 내가 너무 긴장해서 골디의 감정선에도 영향이 가면 어떡하지?",
  ui_story_5037_50370201_87_dialog_content = "역시 난 프로다운 프로듀서가 될 수 없나 봐...",
  ui_story_5037_50370201_88_dialog_content = "그렇지 않아!",
  ui_story_5037_50370201_89_dialog_content = "누구나 처음은 다 있는 거잖아.",
  ui_story_5037_50370201_90_dialog_content = "내가 처음 무대에 섰을 때보다 프로듀서가 만 배는 더 잘하고 있다구.",
  ui_story_5037_50370201_91_dialog_content = "골디의 첫 무대?",
  ui_story_5037_50370201_92_dialog_content = "응! 그 무렵엔 아무도 나한테 기회를 안 줬거든.",
  ui_story_5037_50370201_93_dialog_content = "그러다 겨우겨우 무대에 한 번 서게 됐었어.",
  ui_story_5037_50370201_94_dialog_content = "다음은 즐거운 노래를 여러분께 불러 드릴 골디를 박수로 맞이해 주십시오!",
  ui_story_5037_50370201_95_dialog_content = "자, 잘 부탁드려요!",
  ui_story_5037_50370201_96_dialog_content = "저건 또 누구야?",
  ui_story_5037_50370201_97_dialog_content = "몰라, 오늘 처음 보는데.",
  ui_story_5037_50370201_98_dialog_content = "아, 됐어. 그냥 화장실이나 다녀와야겠다.",
  ui_story_5037_50370201_99_dialog_content = "아...",
  ui_story_5037_50370201_100_dialog_content = "(어째서, 어째서 다들 가 버리는 거지?)",
  ui_story_5037_50370201_101_dialog_content = "(남은 관객들은 날 뚫어져라 보고 있어.)",
  ui_story_5037_50370201_102_dialog_content = "(그러고 보니, 내가 왜 여기 서 있는 거지?)",
  ui_story_5037_50370201_103_dialog_content = "(내가 여기서 뭘 하고 있는 걸까...?)",
  ui_story_5037_50370201_104_dialog_content = "무대에 멀뚱히 서서 뭐 하는 거야?",
  ui_story_5037_50370201_105_dialog_content = "노래 안 할 거면 내려가!",
  ui_story_5037_50370201_106_dialog_content = "저, 전...",
  ui_story_5037_50370201_107_dialog_content = "관객들이 무대에서 널 쫓아냈다고?",
  ui_story_5037_50370201_108_dialog_content = "미안, 내가 안 좋은 기억을 끄집어낸 거 아니야?",
  ui_story_5037_50370201_109_dialog_content = "괜찮아, 이제 전혀 슬프지 않거든~",
  ui_story_5037_50370201_110_dialog_content = "응?",
  ui_story_5037_50370201_111_dialog_content = "뭐든지 시작은 어렵기 마련이잖아. 그래서 그 무렵의 난 항상 이렇게 생각했어...",
  ui_story_5037_50370201_112_dialog_content = "실수는 해도 좋지만, 같은 실수는 두 번 다시 반복하지 않을 거라고 말이야!",
  ui_story_5037_50370201_113_dialog_content = "그래서 두 번째, 세 번째 무대부터는 가사를 잊을 정도로 긴장하진 않았어.",
  ui_story_5037_50370201_114_dialog_content = "만약 그 첫 무대 때의 두려움을 극복하지 못하고 계속 슬퍼했다면...",
  ui_story_5037_50370201_115_dialog_content = "오늘의 나도 없었을 거야.",
  ui_story_5037_50370201_116_dialog_content = "정말 대단해!",
  ui_story_5037_50370201_117_dialog_content = "사실 지금도 조금은 긴장돼, 후훗~",
  ui_story_5037_50370201_118_dialog_content = "하지만 적당한 긴장은 집중력을 높여줘서 실력을 더 잘 발휘할 수 있게 해 줘.",
  ui_story_5037_50370201_119_dialog_content = "긴장하는 티가 하나도 안 나는데?!",
  ui_story_5037_50370201_120_dialog_content = "아, 그건 프로듀서가 너무 긴장해서, 그에 비해 내가 편해 보이는 거 아닐까?",
  ui_story_5037_50370201_121_dialog_content = "후후, 그러니까 내가 하고 싶은 말은...",
  ui_story_5037_50370201_122_dialog_content = "날 믿어 봐~",
  ui_story_5037_50370201_123_dialog_content = "난 경험이 많은 프로 아이돌이라구.",
  ui_story_5037_50370201_124_dialog_content = "더구나 이번엔 훌륭한 프로듀서가 내 옆에서 최고의 노래, 의상, 소품을 준비해줬는걸.",
  ui_story_5037_50370201_125_dialog_content = "참, 그리고 방금 제일 맛있는 목캔디도 먹었어!",
  ui_story_5037_50370201_126_dialog_content = "그러니까 절대 실망하게 하지 않을게!",
  ui_story_5037_50370201_127_dialog_content = "골디...",
  ui_story_5037_50370201_128_dialog_content = "응! 그럼 나도 골디를 실망하게 할 수야 없지.",
  ui_story_5037_50370201_129_dialog_content = "콘서트 시작까지 10초 카운트다운 시작합니다!",
  ui_story_5037_50370201_130_dialog_content = "10... 9... 8... 7...",
  ui_story_5037_50370201_131_dialog_content = "프로듀서, 이제 가야 할 시간이야!",
  ui_story_5037_50370201_132_dialog_content = "골디, 힘내!",
  ui_story_5037_50370201_133_dialog_content = "파이팅!",
  ui_story_5037_50370301_1_dialog_content = "우리 골디 하고 싶은 거 다 해! 골디락스가 영원히 함께할게!",
  ui_story_5037_50370301_2_dialog_content = "골디! 골디! 골디! 골디!",
  ui_story_5037_50370301_3_dialog_content = "관객들 반응이 뜨거워!",
  ui_story_5037_50370301_4_dialog_content = "공연이 끝났는데도 무대 밑에선 골디의 이름을 외치고 있어.",
  ui_story_5037_50370301_5_dialog_content = "PlayerName 프로듀서, 나 왔어~",
  ui_story_5037_50370301_6_dialog_content = "골디, 수고했어!",
  ui_story_5037_50370301_7_dialog_content = "어머? 프로듀서, 왜 그래? 왜 울 것 같은 얼굴이야?",
  ui_story_5037_50370301_8_dialog_content = "해냈어... 우리가 해냈어!",
  ui_story_5037_50370301_9_dialog_content = "공연이 너무 대단해서, 모든 관객의 감정이 골디의 노래를 따라 움직였어.",
  ui_story_5037_50370301_10_dialog_content = "응, 무대에 있을 때도 내가 마치 무대와 하나 된 것 같았어!",
  ui_story_5037_50370301_11_dialog_content = "골디가 느린 곡을 부를 땐 사람들이 노래에 감동해서 눈물을 흘렸고.",
  ui_story_5037_50370301_12_dialog_content = "빠른 곡을 부를 땐 사람들도 리듬에 맞춰 몸을 흔들었어.",
  ui_story_5037_50370301_13_dialog_content = "골디, 오늘 정말 완벽한 무대였어!",
  ui_story_5037_50370301_14_dialog_content = "헤헤, 다 프로듀서 덕분이야.",
  ui_story_5037_50370301_15_dialog_content = "예전엔 내가 이런 노래들을 소화할 수 있단 사실조차 몰랐어!",
  ui_story_5037_50370301_16_dialog_content = "오늘 조명과 무대 효과가 어우러져서 이런 엄청난 효과가 난 거야.",
  ui_story_5037_50370301_17_dialog_content = "이번 공연은 관객이 아니라 내가 즐겼다니까.",
  ui_story_5037_50370301_18_dialog_content = "PlayerName 씨는 오늘 전혀 초보 프로듀서 같지 않았어.",
  ui_story_5037_50370301_19_dialog_content = "완전 일당백 만능 아이돌 프로듀서였다니까!",
  ui_story_5037_50370301_20_dialog_content = "헤헷, 과찬이야. 제대로 못 한 부분도 많았는걸.",
  ui_story_5037_50370301_21_dialog_content = "오프닝 전에 내 실수로 어떤 소품을 못 가져올 뻔했잖아.",
  ui_story_5037_50370301_22_dialog_content = "그래도 골디가 경험이 많아서 문제를 해결할 수 있었어.",
  ui_story_5037_50370301_23_dialog_content = "내 프로듀서라면 다음부턴 같은 실수 안 할 거야, 그렇지?",
  ui_story_5037_50370301_24_dialog_content = "앗... 응!",
  ui_story_5037_50370301_25_dialog_content = "아하하~",
  ui_story_5037_50370301_26_dialog_content = "참, 샤엘 씨가 공연이 끝나면 사무소에서 결과를 발표한다고 했어.",
  ui_story_5037_50370301_27_dialog_content = "응, 얼른 가보자.",
  ui_story_5037_50370301_28_dialog_content = "사부, 내가 진짜 못 살아. 아까 무대 위에서 전혀 열심히 하질 않았잖아!",
  ui_story_5037_50370301_29_dialog_content = "근데 관객들이 오히려 그 게으른 모습을 좋아할 줄은 진짜 몰랐네.",
  ui_story_5037_50370301_30_dialog_content = "심지어 그게 다 연출인 줄 알았나 보더라고, 킥킥.",
  ui_story_5037_50370301_31_dialog_content = "이렇게 보면 사부한테 진짜 아이돌 재능이 그래도 조금은 있긴 한 모양이네.",
  ui_story_5037_50370301_32_dialog_content = "내가 진작에 말했잖아. 나 옛날에 데뷔할 뻔했었다니까?",
  ui_story_5037_50370301_33_dialog_content = "근데 이번엔 데뷔에 성공했지만, 그땐 왜 실패했던 거야?",
  ui_story_5037_50370301_34_dialog_content = "응? 왜 그럴까나~",
  ui_story_5037_50370301_35_dialog_content = "이번엔 피아가 곁에서 사부가 열심히 트레이닝 하는지 안 하는지\n잘 감시해 줘서 그런 거야!",
  ui_story_5037_50370301_36_dialog_content = "비크 씨랑 피아가 즐겁게 대화하고 있네.",
  ui_story_5037_50370301_37_dialog_content = "두 사람도 공연을 잘 마친 모양이야.",
  ui_story_5037_50370301_38_dialog_content = "......",
  ui_story_5037_50370301_39_dialog_content = "그렇게 풀 죽지 마. 나나 비크 씨 모두 스타 엔터테인먼트 소속 아이돌인걸.",
  ui_story_5037_50370301_40_dialog_content = "모두의 데뷔 콘서트가 성공했으니, 정말 좋은 소식인 거잖아!",
  ui_story_5037_50370301_41_dialog_content = "응, 골디 말이 맞아!",
  ui_story_5037_50370301_42_dialog_content = "응? 모두 모였구나?",
  ui_story_5037_50370301_43_dialog_content = "다들 수고했어, 그럼 바로 본론으로 들어갈게.",
  ui_story_5037_50370301_44_dialog_content = "이번 콘서트 대결의 결과는...",
  ui_story_5037_50370301_45_dialog_content = "......",
  ui_story_5037_50370301_46_dialog_content = "결과는...?",
  ui_story_5037_50370301_47_dialog_content = "무승부야!",
  ui_story_5037_50370301_48_dialog_content = "네?",
  ui_story_5037_50370301_49_dialog_content = "갓 데뷔한 신인 아이돌이 베테랑 아이돌과 무승부를 내다니.",
  ui_story_5037_50370301_50_dialog_content = "우리 리얼리티 프로는 정말 긴장과 반전으로 가득하구나.",
  ui_story_5037_50370301_51_dialog_content = "이제 시청률 걱정은 안 해도 되겠네. 후후훗.",
  ui_story_5037_50370301_52_dialog_content = "달링들, 내가 몇 마디만 더 할게.",
  ui_story_5037_50370301_53_dialog_content = "비록 이번 공연은 두 무대의 관객 수가 비슷했지만.",
  ui_story_5037_50370301_54_dialog_content = "앞으로 <color=#793f76>두 번</color>의 콘서트가 더 남았어.",
  ui_story_5037_50370301_55_dialog_content = "결과는 세 번의 콘서트가 끝난 다음, <color=#793f76>합산된 응원자 수</color>로 결정될 거야.",
  ui_story_5037_50370301_56_dialog_content = "그러니 이번 결과에 상관없이...",
  ui_story_5037_50370301_57_dialog_content = "다음 심사 콘서트를 잘 준비하길 바랄게.",
  ui_story_5037_50370301_58_dialog_content = "골디 씨랑 무승부를 낼 정도라니, 역시 난 대단하다니까!",
  ui_story_5037_50370301_59_dialog_content = "하지만 계속 이런 트레이닝을 하면 이 노인네는 못 버텨.\n그러니까 이제 슬슬 집에 돌아...",
  ui_story_5037_50370301_60_dialog_content = "흥! 이 결과가 뭘 의미하는지 알아?",
  ui_story_5037_50370301_61_dialog_content = "사부가 실력을 100% 발휘했다면 우리가 PlayerName하고 골디 언니를\n이길 수 있었다는 거잖아!",
  ui_story_5037_50370301_62_dialog_content = "이제 다시 처음부터 시작이야!",
  ui_story_5037_50370301_63_dialog_content = "다음에 있을 심사 콘서트 땐 게으름 피우는 건 꿈도 꾸지 마!",
  ui_story_5037_50370301_64_dialog_content = "어? 피아, 어디 가?",
  ui_story_5037_50370301_65_dialog_content = "연습실! 계속 트레이닝해야지!",
  ui_story_5037_50370301_66_dialog_content = "우리 착한 피아야, 대체 언제쯤 이 사부를 쉬게 해 줄 거니?",
  ui_story_5037_50370301_67_dialog_content = "키아로! 사부를 끌고 가!",
  ui_story_5037_50370301_68_dialog_content = "루!",
  ui_story_5037_50370301_69_dialog_content = "키아로, 살살해, 살살...",
  ui_story_5037_50370301_70_dialog_content = "비크 씨가 저렇게 대단했단 말이야?",
  ui_story_5037_50370301_71_dialog_content = "음~ 내가 신인을 제대로 봤네. 첫 콘서트인데 저렇게 많은 사랑을 받다니.",
  ui_story_5037_50370301_72_dialog_content = "피아도 비크 씨의 프로듀서로서 많이 노력했고 말이야.",
  ui_story_5037_50370301_73_dialog_content = "듣기론 피아가 매일 밤늦게까지 비크 씨 연습을 지켜봤다고 하더라고.",
  ui_story_5037_50370301_74_dialog_content = "실은 나도 몇 번 봤어.",
  ui_story_5037_50370301_75_dialog_content = "비크 씨가 게으름을 피우려고 할 때마다, 피아가 키아로한테 비크 씨 발뒤꿈치를\n물라고 했다니까!",
  ui_story_5037_50370301_76_dialog_content = "저 키아로라는 환상동물한테 그런 힘이 있어?",
  ui_story_5037_50370301_77_dialog_content = "나도 키아로처럼 내가 게을러질 때 날 혼내줄 환상동물이 있어야 하나...",
  ui_story_5037_50370301_78_dialog_content = "구, 굳이 안 그래도 될 것 같아.",
  ui_story_5037_50370301_79_dialog_content = "골디는 누군가의 관리 없이도 충분히 노력하고 있잖아!",
  ui_story_5037_50370301_80_dialog_content = "오히려 키아로한테 혼나야 할 사람은 나야.",
  ui_story_5037_50370301_81_dialog_content = "내 노력이 부족해서 뛰어난 아이돌인데도 신인한테 관객 수를 따라 잡히게\n만들어 버렸잖아.",
  ui_story_5037_50370301_82_dialog_content = "PlayerName 씨, 그렇게 생각하면 안 돼.",
  ui_story_5037_50370301_83_dialog_content = "아이돌의 인기는 말로는 설명할 수 없이 오묘할 때도 있어.",
  ui_story_5037_50370301_84_dialog_content = "적어도 내가 오늘 무대를 즐겼고 후회도 없으니까 그걸로 충분한 거야!",
  ui_story_5037_50370301_85_dialog_content = "...고마워.",
  ui_story_5037_50370301_86_dialog_content = "골디가 날 위로해 주는 건 괜찮아.\n하지만 난 그걸 핑계 삼아서 내가 못한 걸 합리화할 순 없어!",
  ui_story_5037_50370301_87_dialog_content = "응?",
  ui_story_5037_50370301_88_dialog_content = "앞으로 더 힘내서 프로듀서가 갖춰야 할 기량을 갈고닦을 거야.",
  ui_story_5037_50370301_89_dialog_content = "그래서 골디한테 더 좋은 스케줄과 트레이닝 계획을 잡아줄 거고.",
  ui_story_5037_50370301_90_dialog_content = "다음번엔 골디랑 같이 더 대단한 콘서트를 열 거야!",
  ui_story_5037_50370301_91_dialog_content = "...PlayerName 씨.",
  ui_story_5037_50370301_92_dialog_content = "다음 한 번으론 부족해. 이제 두 번의 콘서트가 남았고...\n앞으로는 더더더 많을 테니까!",
  ui_story_5037_50370301_93_dialog_content = "그래, 맞아! 그럼 정정할게!",
  ui_story_5037_50370301_94_dialog_content = "골디랑 같이 남은 콘서트를 더 멋지게 열 거야!",
  ui_story_5037_50370301_95_dialog_content = "응!",
  ui_story_5037_50370301_96_dialog_content = "그럼 앞으로도 잘 부탁해~",
  ui_story_5037_50370301_97_dialog_content = "데뷔 콘서트 지인 평가단 후속 인터뷰, 레디...",
  ui_story_5037_50370301_98_dialog_content = "액션!",
  ui_story_5037_50370301_99_dialog_content = "이번 콘서트는 10점 만점에 몇 점을 주고 싶나요?",
  ui_story_5037_50370301_100_dialog_content = "당연히 10점 만점이죠~",
  ui_story_5037_50370301_101_dialog_content = "음, 8점 정도야. 아직 개선의 여지가 있어.",
  ui_story_5037_50370301_102_dialog_content = "저 둘이 뭉쳐서 꿍꿍이를 부려 봤자 뭘 할 수 있겠어?",
  ui_story_5037_50370301_103_dialog_content = "응? 맞아, 오늘 콘서트 보러 안 갔어.",
  ui_story_5037_50370301_104_dialog_content = "뭐라고? 관객들한테 반응이 좋았다고?",
  ui_story_5037_50370301_105_dialog_content = "상대 팀의 콘서트에는 몇 점을 주고 싶나요?",
  ui_story_5037_50370301_106_dialog_content = "음... 10점? 피아랑 비크 씨도 노력한 게 보이더라고요.",
  ui_story_5037_50370301_107_dialog_content = "마찬가지로 8점, 아직 개선의 여지가 있어.",
  ui_story_5037_50370301_108_dialog_content = "이거 꼭 대답해야 해?",
  ui_story_5037_50370301_109_dialog_content = "친구에게 최근 생긴 변화가 있나요?",
  ui_story_5037_50370301_110_dialog_content = "PlayerName의 생활이 규칙적으로 변했어요. 아침에 늦잠도 안 자고요.",
  ui_story_5037_50370301_111_dialog_content = "내 생각보다 이해력이 좋았어. 프로듀서가 뭘 해야 하는지 금방 익숙해지더라고.",
  ui_story_5037_50370301_112_dialog_content = "달라진 게 하나도 없던데?",
  ui_story_5037_50370301_113_dialog_content = "데뷔 콘서트 지인 평가단 후속 인터뷰 녹화 끝!",
  ui_story_5037_50370301_114_dialog_content = "뭐? PlayerName하고 골디가 벌써 트레이닝을 시작했단 말이야?",
  ui_story_5037_50370301_115_dialog_content = "으앗! 그럼 빨리 찍으러 가야지!",
  ui_story_5037_50370401_1_dialog_content = "프로듀서님, 이 소품은 크키가 좀 큰데 어디다 둘까요?",
  ui_story_5037_50370401_2_dialog_content = "무대 중간에 놔 주세요. 딱 정중앙이요.",
  ui_story_5037_50370401_3_dialog_content = "프로듀서님, 조명 밝기 괜찮으세요?",
  ui_story_5037_50370401_4_dialog_content = "너무 눈이 부시니까, 살짝만 낮춰주세요.",
  ui_story_5037_50370401_5_dialog_content = "프로듀서님! 여기 오셔서 확인 좀 부탁드려요!",
  ui_story_5037_50370401_6_dialog_content = "프로듀서님, 이 문제는 어떡할까요?",
  ui_story_5037_50370401_7_dialog_content = "프로듀서님! 프로듀서님!",
  ui_story_5037_50370401_8_dialog_content = "한 명씩, 질문은 한 명씩...",
  ui_story_5037_50370401_9_dialog_content = "<color=#828282>얼마 후</color>",
  ui_story_5037_50370401_10_dialog_content = "후, 겨우 끝났네.",
  ui_story_5037_50370401_11_dialog_content = "고생했어.",
  ui_story_5037_50370401_12_dialog_content = "앗, 골디, 벌써 준비 다 된 거야?",
  ui_story_5037_50370401_13_dialog_content = "다 준비됐어~",
  ui_story_5037_50370401_14_dialog_content = "평소처럼?",
  ui_story_5037_50370401_15_dialog_content = "응!",
  ui_story_5037_50370401_16_dialog_content = "여기.",
  ui_story_5037_50370401_17_dialog_content = "고마워.",
  ui_story_5037_50370401_18_dialog_content = "에에에? 「평소처럼」이라니? 대화가 너무 간단하잖아?",
  ui_story_5037_50370401_19_dialog_content = "방금 PlayerName 너 골디한테 뭘 준 거야? 카메라에 안 찍혔단 말이야...",
  ui_story_5037_50370401_20_dialog_content = "아, 이건 말하지 않아도 통하는 우리 둘만의 암호 같은 거야.",
  ui_story_5037_50370401_21_dialog_content = "내가 목 관리를 위해 박하맛 사탕을 먹는 걸 알아서, 프로듀서가 매번 챙겨주고 있어.",
  ui_story_5037_50370401_22_dialog_content = "방금도 그냥 사탕을 받은 것뿐이야.",
  ui_story_5037_50370401_23_dialog_content = "언제부터 그렇게 눈빛만 봐도 다 아는 사이가 된 거야?",
  ui_story_5037_50370401_24_dialog_content = "음, 며칠 안 됐을걸.",
  ui_story_5037_50370401_25_dialog_content = "근데 함께 연습한 시간이 길어지니까 눈빛만 봐도 무슨 의미인지 알 수 있게 됐어.",
  ui_story_5037_50370401_26_dialog_content = "대단하네...",
  ui_story_5037_50370401_27_dialog_content = "잠깐만!",
  ui_story_5037_50370401_28_dialog_content = "둘이 말을 안 하면, 난 촬영할 게 없잖아?",
  ui_story_5037_50370401_29_dialog_content = "그럼 내가 프로듀서한테 가서 대화라도 좀 나눠 볼까?",
  ui_story_5037_50370401_30_dialog_content = "그건 너무 인위적이라구.",
  ui_story_5037_50370401_31_dialog_content = "아, 맞다.",
  ui_story_5037_50370401_32_dialog_content = "지인 인터뷰 때처럼 두 사람 인터뷰도 추가해야겠어!",
  ui_story_5037_50370401_33_dialog_content = "에헤헤, 역시 난 천재라니까!",
  ui_story_5037_50370401_34_dialog_content = "지인 인터뷰? 그런 것도 했어?",
  ui_story_5037_50370401_35_dialog_content = "헤헤, 방영되면 알게 될 거야~",
  ui_story_5037_50370401_36_dialog_content = "일단 지금 해야 할 건... 그래! 콘서트 사전 인터뷰를 하자!",
  ui_story_5037_50370401_37_dialog_content = "PlayerName 팀의 심사 콘서트 사전 인터뷰, 레디...",
  ui_story_5037_50370401_38_dialog_content = "액션!",
  ui_story_5037_50370401_39_dialog_content = "심사 콘서트와 데뷔 콘서트는 뭐가 다른가요?",
  ui_story_5037_50370401_40_dialog_content = "데뷔 콘서트는 제가 스타 엔터테인먼트의 아이돌로서 활동을 시작한다는 의미예요.",
  ui_story_5037_50370401_41_dialog_content = "비유를 하자면, 데뷔 콘서트는 저한테 놀이공원 입장권 같은 거죠.",
  ui_story_5037_50370401_42_dialog_content = "그런 놀이공원에서 전 뭘 할까요?",
  ui_story_5037_50370401_43_dialog_content = "바로 좋은 작품으로 자신을 증명하는 거죠~",
  ui_story_5037_50370401_44_dialog_content = "그리고 심사 콘서트는 회사에서 우리가 일정 기간 동안 얼마나 성장했는지\n성과를 보는 게 목적이야.",
  ui_story_5037_50370401_45_dialog_content = "하지만 우리한테 있어서는 「골디락스」가 우릴 시험하는 의미가 더 커.",
  ui_story_5037_50370401_46_dialog_content = "맞아요. 전 모두에게 증명하고 싶어요...",
  ui_story_5037_50370401_47_dialog_content = "제가 어디에 있든 초심을 잃지 않았다는 걸 말이에요~",
  ui_story_5037_50370401_48_dialog_content = "콘서트를 준비하면서 스트레스를 받지는 않나요?",
  ui_story_5037_50370401_49_dialog_content = "스트레스는 전혀 없어요~",
  ui_story_5037_50370401_50_dialog_content = "농담이에요. 사실 스트레스를 받는 건 아주 정상적인 일이니까요.",
  ui_story_5037_50370401_51_dialog_content = "하지만 정말 고마운 건, 프로듀서가 항상 제 옆에서 많은 일을 해주고 있거든요.",
  ui_story_5037_50370401_52_dialog_content = "덕분에 전 연습에만 집중할 수 있어서 오히려 더 편해졌어요.",
  ui_story_5037_50370401_53_dialog_content = "연습 결과는... 이따 콘서트에서 확인할 수 있을 거예요~",
  ui_story_5037_50370401_54_dialog_content = "프로듀서 일은 많이 힘든가요?",
  ui_story_5037_50370401_55_dialog_content = "솔직히 데뷔 콘서트 전까진 힘든 시간을 보낸 건 맞아.",
  ui_story_5037_50370401_56_dialog_content = "지난 콘서트를 준비하면서 실수를 많이 했거든.",
  ui_story_5037_50370401_57_dialog_content = "처음엔 많이 낯설었지만, 그래도 요즘은 프로듀서 일이 익숙해졌어.",
  ui_story_5037_50370401_58_dialog_content = "그러니까 절대로 같은 실수를 반복하지 않을 거야.",
  ui_story_5037_50370401_59_dialog_content = "네, 그건 제가 장담할 수 있어요~",
  ui_story_5037_50370401_60_dialog_content = "PlayerName 씨는 이제 베테랑 프로듀서가 다 됐어요.",
  ui_story_5037_50370401_61_dialog_content = "게다가 요즘은 눈붙일 시간도 거의 없을 만큼 매일 바쁘게 일했거든요.",
  ui_story_5037_50370401_62_dialog_content = "이번 콘서트를 위해서 프로듀서가 정말 고생을 많이 했어요!",
  ui_story_5037_50370401_63_dialog_content = "아니야, 다 내가 당연히 해야 할 일이었는걸.",
  ui_story_5037_50370401_64_dialog_content = "골디가 최고의 무대를 만들고, 「골디락스」한테 가장 멋진 공연을 선보이는 데\n도움이 된다면 난 그만한 가치가 있다고 생각해.",
  ui_story_5037_50370401_65_dialog_content = "그래서 전혀 고생이라 생각하지 않아!",
  ui_story_5037_50370401_66_dialog_content = "이번엔 어떤 무대를 준비했는지 살짝 알려 주실 수 있나요?",
  ui_story_5037_50370401_67_dialog_content = "아직은 비밀이에요.",
  ui_story_5037_50370401_68_dialog_content = "하지만 모두가 지금까지 보지 못했던 무대일 거라고 확신해요~",
  ui_story_5037_50370401_69_dialog_content = "사실 공연 콘셉트는 미리 말해줄 수 있어.",
  ui_story_5037_50370401_70_dialog_content = "아, 맞아요.",
  ui_story_5037_50370401_71_dialog_content = "프로듀서가 세 번의 콘서트마다 콘셉트를 다 다르게 정해줬거든요.",
  ui_story_5037_50370401_72_dialog_content = "데뷔 콘서트의 콘셉트는 「자라나는 새싹」이었는데요.\n관객분들이 그걸 느껴 주셨을지 모르겠네요.",
  ui_story_5037_50370401_73_dialog_content = "그리고 이번 콘셉트는 <color=#793f76>「피어나는 꽃」</color>이에요!",
  ui_story_5037_50370401_74_dialog_content = "이 콘셉트에 맞춰 프로듀서의 도움을 받아 저번 공연과는 차별화된\n새로운 내용을 준비했어요.",
  ui_story_5037_50370401_75_dialog_content = "티켓을 사서 콘서트에 오는 관객분들께 똑같은 공연만 계속 보여 줄 순 없잖아요~",
  ui_story_5037_50370401_76_dialog_content = "정정해 줘. 난 보조 업무만 했을 뿐이고, 중요한 건 골디가 했거든.",
  ui_story_5037_50370401_77_dialog_content = "원래는 기존 곡을 리메이크하면 어떨까 했어.",
  ui_story_5037_50370401_78_dialog_content = "근데 골디가 이번 콘서트를 위해 곡을 많이 썼더라고.",
  ui_story_5037_50370401_79_dialog_content = "왜냐면 연습할 때 순간순간 많은 감정이 올라오거든요.",
  ui_story_5037_50370401_80_dialog_content = "전 아이돌을 하기로 결심했을 때부터 모든 걸 쭉 혼자서 해 왔어요.",
  ui_story_5037_50370401_81_dialog_content = "하지만 이제는 프로듀서도 제 곁에 있고...",
  ui_story_5037_50370401_82_dialog_content = "같은 목표를 가진 경쟁자도 있어요.",
  ui_story_5037_50370401_83_dialog_content = "아니지! 비크 씨는 사실 경쟁자라기보다는 함께 아이돌이란 길을 걷는\n동료라고 생각해요.",
  ui_story_5037_50370401_84_dialog_content = "그리고 이런 새로운 감정들 덕분에 더 많은 신곡을 쓸 수 있었거든요.",
  ui_story_5037_50370401_85_dialog_content = "연습할 때 그 곡들을 여러 번 듣긴 했는데, 들을 때마다 정말...",
  ui_story_5037_50370401_86_dialog_content = "너무 감동적이었다니까.",
  ui_story_5037_50370401_87_dialog_content = "아무튼 이렇게 최선을 다해 준비한 무대니까 다들 분명히 만족할 거라 생각해!",
  ui_story_5037_50370401_88_dialog_content = "프로듀서가 골디의 인기를 위해 매일 밖에서 전단지를 돌린다면서요?",
  ui_story_5037_50370401_89_dialog_content = "네? 진짜요?",
  ui_story_5037_50370401_90_dialog_content = "전 처음 들었어요... 프로듀서는 저한테 한 번도 그런 말 한 적 없었는걸요!",
  ui_story_5037_50370401_91_dialog_content = "다 내가 당연히 해야 할 일인걸. 아무것도 아니야.",
  ui_story_5037_50370401_92_dialog_content = "기억났어!",
  ui_story_5037_50370401_93_dialog_content = "밥 먹으러 간다거나, 간식 사러 간다고 했던 적이 몇 번 있었는데...",
  ui_story_5037_50370401_94_dialog_content = "그때 전단지 돌리러 갔던 거야?",
  ui_story_5037_50370401_95_dialog_content = "응. 미안. 골디가 신경 쓸 게 뻔해서 따로 얘기 안 했어.",
  ui_story_5037_50370401_96_dialog_content = "골디는 항상 결과는 중요하지 않다고, 과정에서 최선을 다해서 후회하지 않으면\n된다고 하지만...",
  ui_story_5037_50370401_97_dialog_content = "난 골디가 더 많은 관심과 사랑을 받았으면 좋겠어.",
  ui_story_5037_50370401_98_dialog_content = "그래야 후회가 남지 않을 것 같거든.",
  ui_story_5037_50370401_99_dialog_content = "프로듀서...",
  ui_story_5037_50370401_100_dialog_content = "다음엔 나도 같이 가! 거리 공연도 하면 사람들의 관심도 더 많이 끌 수 있잖아~",
  ui_story_5037_50370401_101_dialog_content = "우린 한 팀이란 걸 잊으면 안 돼!",
  ui_story_5037_50370401_102_dialog_content = "한 팀... 그래, 우린 한 팀이야!",
  ui_story_5037_50370401_103_dialog_content = "이번 콘서트에 자신 있나요?",
  ui_story_5037_50370401_104_dialog_content = "프로듀서, 나 믿어?",
  ui_story_5037_50370401_105_dialog_content = "골디의 연습 과정을 다 봤는데, 정말 흠잡을 데 없이 완벽했어.",
  ui_story_5037_50370401_106_dialog_content = "지금까지 해오던 걸 그저 장소만 바꿔서 하는 거잖아. 난 골디를 믿어!",
  ui_story_5037_50370401_107_dialog_content = "나도야. 나도 프로듀서를 믿고 있어~",
  ui_story_5037_50370401_108_dialog_content = "평소처럼?",
  ui_story_5037_50370401_109_dialog_content = "응!",
  ui_story_5037_50370401_110_dialog_content = "아자! 아자! 파이팅!",
  ui_story_5037_50370401_111_dialog_content = "프로듀서님, 이 소품은 어디 둘까요?",
  ui_story_5037_50370401_112_dialog_content = "프로듀서님 어디 계세요?",
  ui_story_5037_50370401_113_dialog_content = "프로듀서님! 프로듀서님!",
  ui_story_5037_50370401_114_dialog_content = "아... 나, 난 가서 일 좀 처리하고 올게!",
  ui_story_5037_50370401_115_dialog_content = "휴우~",
  ui_story_5037_50370401_116_dialog_content = "이번 콘서트는 PlayerName 씨 없이는 정말 안 되겠네.",
  ui_story_5037_50370401_117_dialog_content = "나도 무대 오르기 전까지 마음의 준비를 잘 해야겠는걸~",
  ui_story_5037_50370501_1_dialog_content = "그럼 이번 심사 콘서트의 대결 결과를 발표할게.",
  ui_story_5037_50370501_2_dialog_content = "이번 결과는 정말 내 상상 이상이었어.",
  ui_story_5037_50370501_3_dialog_content = "(샤엘 씨한테 상상 이상의 결과라니, 뭐지?)",
  ui_story_5037_50370501_4_dialog_content = "(설마... 비크 씨가 이겼나?)",
  ui_story_5037_50370501_5_dialog_content = "대결에서 이긴 팀은 데뷔 콘서트의 부담감을 이겨내고,\n더 많은 관객의 눈길을 끄는 데 성공했어.",
  ui_story_5037_50370501_6_dialog_content = "아이돌 본인의 피나는 연습이 있었겠지.",
  ui_story_5037_50370501_7_dialog_content = "물론 프로듀서의 마음도 빼놓을 수 없고 말이야.",
  ui_story_5037_50370501_8_dialog_content = "(호오~ 연습과 마음? 저건 딱 사부랑 내 얘기잖아?)",
  ui_story_5037_50370501_9_dialog_content = "(노력은 배신하지 않는다더니, 사부가 드디어 골디 언니를 이겼나?!)",
  ui_story_5037_50370501_10_dialog_content = "대결 결과는...",
  ui_story_5037_50370501_11_dialog_content = "......",
  ui_story_5037_50370501_12_dialog_content = "헤헤~",
  ui_story_5037_50370501_13_dialog_content = "<size=45>골디와 PlayerName 팀의 승리야!</size>",
  ui_story_5037_50370501_14_dialog_content = "프로듀서, 들었어? 우리가 이겼대!",
  ui_story_5037_50370501_15_dialog_content = "이, 이겼다고?",
  ui_story_5037_50370501_16_dialog_content = "에에에엥?! 어떻게 이럴 수 있지?",
  ui_story_5037_50370501_17_dialog_content = "드디어 곧 집에 갈 수 있겠네~",
  ui_story_5037_50370501_18_dialog_content = "잔혹한 사실이지만, 결과적으로 골디의 관객이 비크의 관객보다 더 많았어.",
  ui_story_5037_50370501_19_dialog_content = "하지만 사부의 이번 콘서트는 저번보다 분명히 훨씬 더 성공적이었는걸!\n근데 왜 골디 언니가 이긴 거야?",
  ui_story_5037_50370501_20_dialog_content = "음, 그리 이해하기 어려운 결과는 아니야.\n이번 공연에서 골디의 감정 전달은 정말 좋았거든.",
  ui_story_5037_50370501_21_dialog_content = "노래에 안무를 더한 건 물론, 조명과 무대 미술에도 공을 들였어.",
  ui_story_5037_50370501_22_dialog_content = "더 중요한 건, 골디는 이번 현장에서 많은 관객을 팬으로 만들어 버렸단 거야.",
  ui_story_5037_50370501_23_dialog_content = "모두가 공중상회로 몰려들어 판매 중인 골디의 굿즈들을 싹 쓸어갔어.",
  ui_story_5037_50370501_24_dialog_content = "심지언 골디랑 아무 상관도 없는 상품까지도 동이 나버렸고.",
  ui_story_5037_50370501_25_dialog_content = "「골디락스」가 입소문을 내준 덕분에...",
  ui_story_5037_50370501_26_dialog_content = "「골디 콘서트 관람」이 「움브라톤 버킷 리스트 10선」 중 하나가 됐을 정도야.",
  ui_story_5037_50370501_27_dialog_content = "모두가 스타 엔터테인먼트의 다음 콘서트를 기대하고 있어.",
  ui_story_5037_50370501_28_dialog_content = "다들 상상이 가? 벌써 졸업 콘서트 티켓 구하기가 하늘의 별 따기라니까.",
  ui_story_5037_50370501_29_dialog_content = "이제 드디어 티켓 좀 사 달라고 부탁하러 다니지 않아도 되는 건가?!",
  ui_story_5037_50370501_30_dialog_content = "리얼리티 프로그램 방영이 시작되기도 전에 투자금을 회수할 수 있을 줄은 몰랐네.",
  ui_story_5037_50370501_31_dialog_content = "이제부턴 팬을 모으기 위해 따로 홍보할 필요가 없어졌어.",
  ui_story_5037_50370501_32_dialog_content = "너흰 최고의 기획과 컨디션으로 마지막 졸업 콘서트를 준비하면 돼!",
  ui_story_5037_50370501_33_dialog_content = "샤엘 사장님, 고마워요.",
  ui_story_5037_50370501_34_dialog_content = "더 열심히 해서, 더 좋은 공연으로 샤엘 씨와 팬들의 마음에 보답할게요!",
  ui_story_5037_50370501_35_dialog_content = "비크, 당신 대답은 아직 못 들은 것 같은데?",
  ui_story_5037_50370501_36_dialog_content = "그럼 난 이제 여기서 그만하는 게 어떨까?",
  ui_story_5037_50370501_37_dialog_content = "어차피 졌으니까 그냥 좀 일찍 집에 보내주라~",
  ui_story_5037_50370501_38_dialog_content = "난 못 믿겠어. 믿을 수 없다구.",
  ui_story_5037_50370501_39_dialog_content = "이거... 사실은 모두가 피아랑 사부를 괴롭히려고 짜고 친 걸 수도 있어.",
  ui_story_5037_50370501_40_dialog_content = "샤엘 사장님, 말해 봐!",
  ui_story_5037_50370501_41_dialog_content = "이거 다 리얼리티 프로그램 각본인 거지?",
  ui_story_5037_50370501_42_dialog_content = "리얼리티 프로그램의 각본?",
  ui_story_5037_50370501_43_dialog_content = "피아, 넌 정말 천재구나.",
  ui_story_5037_50370501_44_dialog_content = "피아는 당연히 천재지! 후후.",
  ui_story_5037_50370501_45_dialog_content = "...잠깐만, 갑자기 그게 무슨 소리야?",
  ui_story_5037_50370501_46_dialog_content = "왜 난 처음부터 각본을 쓰면 된다는 생각을 못 했을까?",
  ui_story_5037_50370501_47_dialog_content = "그러면 원금을 더 빨리 회수했을지도 모르는데.",
  ui_story_5037_50370501_48_dialog_content = "하지만 피아 프로듀서, 이번 대결의 결과는 명확했어.",
  ui_story_5037_50370501_49_dialog_content = "그래도 마음에 걸린다면 촬영본을 다시 보는 것도 좋아.",
  ui_story_5037_50370501_50_dialog_content = "보고 난 다음에도 문제가 있다면 언제든 다시 얘기해.",
  ui_story_5037_50370501_51_dialog_content = "<color=#828282>얼마 후</color>",
  ui_story_5037_50370501_52_dialog_content = "저거 다 어떻게 한 거지? 저 엄청난 무대 효과는 대체 어떻게 한 거냐구?!",
  ui_story_5037_50370501_53_dialog_content = "골디 언니가 1초 만에 의상을 갈아입었잖아?!",
  ui_story_5037_50370501_54_dialog_content = "그리고 갑자기 관객석에 나타나서 무대로 날아가는데?!",
  ui_story_5037_50370501_55_dialog_content = "골디 언니 콘서트랑 비교하면, 사부 콘서트는 저거 반의반도 안 되잖아!",
  ui_story_5037_50370501_56_dialog_content = "이래서 사부가 데뷔를 못 했던 거구나.",
  ui_story_5037_50370501_57_dialog_content = "윽... 크, 크흠.",
  ui_story_5037_50370501_58_dialog_content = "아무튼 이젠 알겠지? 이 사부한테 아무리 재능이 있다고 해도, 프로 아이돌 앞에선 새 발의 피라는 걸 말이야.",
  ui_story_5037_50370501_59_dialog_content = "이제라도 현실을 깨달았으니까 아직 안 늦었어. 난 지금 당장 짐 싸러 갈게!",
  ui_story_5037_50370501_60_dialog_content = "잠깐!",
  ui_story_5037_50370501_61_dialog_content = "사실 사부가 말 안 해도 피아는 다 알아.",
  ui_story_5037_50370501_62_dialog_content = "이번 콘서트의 연출이 별로였던 건 사부 잘못이 아니라는 거.",
  ui_story_5037_50370501_63_dialog_content = "피아는 프로듀서면서 사부 트레이닝에만 신경 쓰고,\n콘서트 구성이랑 무대 연출엔 소홀했어.",
  ui_story_5037_50370501_64_dialog_content = "난 지금까지 계속 콘서트가 성공하려면 사부가 잘하는 게 제일 중요하다고 생각했는데...",
  ui_story_5037_50370501_65_dialog_content = "골디 언니의 공연을 보고 나서야 깨달았어. 콘서트도 저렇게 구성할 수 있단 걸!",
  ui_story_5037_50370501_66_dialog_content = "아까 사부는 정말 잘했어.",
  ui_story_5037_50370501_67_dialog_content = "문제는 피아가 사부한테 완벽한 무대를 만들어 주지 못했던 거야!",
  ui_story_5037_50370501_68_dialog_content = "콘서트가 순조롭게 마무리된 것만으로도 완벽한 무대였다고 할 수 있는 거니까, 너무 마음에 담아 두지 말고 우리 그냥 빨리 돌아가는 게...",
  ui_story_5037_50370501_69_dialog_content = "아니! 피아는 아직 돌아갈 수 없어!",
  ui_story_5037_50370501_70_dialog_content = "우리한텐 아직 마지막 콘서트가 남았으니까, 만회할 기회가 있어.",
  ui_story_5037_50370501_71_dialog_content = "이번엔 피아가 꼭 아이돌을 향한 사부의 꿈에 아쉬움이 없게 해 줄게!",
  ui_story_5037_50370501_72_dialog_content = "아...?",
  ui_story_5037_50370501_73_dialog_content = "나도 방금 비크 씨 콘서트를 봤어.",
  ui_story_5037_50370501_74_dialog_content = "비크 씨 공연은 이미 프로 아이돌의 수준이었어.",
  ui_story_5037_50370501_75_dialog_content = "몇몇 곡의 안무가 비크 씨의 매력을 제대로 살리지 못했을 뿐이야.",
  ui_story_5037_50370501_76_dialog_content = "어? 정말? 진짜야? 어떤 곡들이 그랬는데?",
  ui_story_5037_50370501_77_dialog_content = "응, 이따가 내가 정리해둔 감상평을 피아한테 보여줄게.",
  ui_story_5037_50370501_78_dialog_content = "참, 내가 이번에 발라드곡 하나를 새로 써 봤는데, 왠지 비크 씨한테 딱 맞을 것 같아.",
  ui_story_5037_50370501_79_dialog_content = "자료를 정리하고 나면 같이 전해줄게~",
  ui_story_5037_50370501_80_dialog_content = "우와!",
  ui_story_5037_50370501_81_dialog_content = "그, 근데 진짜 그래도 되는 거야?",
  ui_story_5037_50370501_82_dialog_content = "우린 경쟁자잖아? 근데 왜 도와주려고 하는 거야?",
  ui_story_5037_50370501_83_dialog_content = "아이돌은 사람들한테 희망과 따스함을 주는 직업이야.",
  ui_story_5037_50370501_84_dialog_content = "그래 놓고 정작 주변 사람도 챙기지 못하면 아이돌이라고 할 수 있겠어?",
  ui_story_5037_50370501_85_dialog_content = "나도 사전 인터뷰에서 골디가 했던 말이 기억나...",
  ui_story_5037_50370501_86_dialog_content = "비크 씨는 사실 경쟁자라기보다는 함께 아이돌이란 길을 걷는 동료라고 생각해요.",
  ui_story_5037_50370501_87_dialog_content = "우와아... 눈부셔...",
  ui_story_5037_50370501_88_dialog_content = "완전 빛 그 자체잖아!",
  ui_story_5037_50370501_89_dialog_content = "이게 바로 진짜 아이돌의 위엄이란 건가?",
  ui_story_5037_50370501_90_dialog_content = "자...잠깐만!",
  ui_story_5037_50370501_91_dialog_content = "골디 언니가 그렇게 말했으면... 나랑 사부가 사전 인터뷰에 한 얘기들은\n웃음거리만 되게 생겼잖아?",
  ui_story_5037_50370501_92_dialog_content = "(인터뷰 때 무슨 말을 했길래 그래?)",
  ui_story_5037_50370501_93_dialog_content = "저기, 우리가 했던 사전 인터뷰 말인데, 그거 삭제하고 다시 찍으면 안 될까?",
  ui_story_5037_50370501_94_dialog_content = "그건 곤란해~",
  ui_story_5037_50370501_95_dialog_content = "이건 리얼리티 프로그램이라구!",
  ui_story_5037_50370501_96_dialog_content = "키아로! 잠깐 여기로 좀 와 봐~",
  ui_story_5037_50370501_97_dialog_content = "루!",
  ui_story_5037_50370501_98_dialog_content = "뭐, 뭐 하려는 거야?",
  ui_story_5037_50370501_99_dialog_content = "키아로한테 날 물라고 해도 다시 촬영하는 일은 없을 거야!",
  ui_story_5037_50370501_100_dialog_content = "에잇! 도망가지 마!",
  ui_story_5037_50370501_101_dialog_content = "다시 찍어 주면 키아로랑 놀 수 있게 해 줄 테니까!",
  ui_story_5037_50370501_102_dialog_content = "흐음? 피아가 다른 데 정신이 팔려 있잖아?",
  ui_story_5037_50370501_103_dialog_content = "드디어 잠 좀 잘 수 있겠네.",
  ui_story_5037_50370501_104_dialog_content = "그럼 다들 나중에 봐~",
  ui_story_5037_50370501_105_dialog_content = "휴우~ 프로듀서, 심사 콘서트가 무사히 끝났어.",
  ui_story_5037_50370501_106_dialog_content = "골디, 그동안 수고 많았어!",
  ui_story_5037_50370501_107_dialog_content = "오늘 공연 너무 좋았어. 이 정도면 역대 최고의 콘서트라고 할 만하지 않을까?",
  ui_story_5037_50370501_108_dialog_content = "프로듀서, 아직 그렇게 결론짓긴 너무 일러~",
  ui_story_5037_50370501_109_dialog_content = "아직 졸업 콘서트도 남았는걸?",
  ui_story_5037_50370501_110_dialog_content = "그건 그래. 언제나 이번보다 이다음 콘서트가 가장 멋진 법이니까!",
  ui_story_5037_50370501_111_dialog_content = "후후후, 방금 프로듀서가 아주 멋진 한마디를 해 줬네.",
  ui_story_5037_50370501_112_dialog_content = "벌써 우리 프로듀서님이 벌써 마지막 콘서트의 콘셉트를 생각해 두신 걸까나?",
  ui_story_5037_50370501_113_dialog_content = "아! 맞다, 그러고 보니까 난 빨리 가서 졸업 콘서트를 기획해야 돼.",
  ui_story_5037_50370501_114_dialog_content = "난 신경 쓰지 말고, 골디 넌 가서 푹 쉬어!",
  ui_story_5037_50370501_115_dialog_content = "알겠어~ 프로듀서도 일찍 쉬어.",
  ui_story_5037_50370501_116_dialog_content = "마시멜로.",
  ui_story_5037_50370501_117_dialog_content = "멍!",
  ui_story_5037_50370501_118_dialog_content = "아까 콘서트에서 왠지 물건을 훔치는 도둑이 있는 것 같았어.",
  ui_story_5037_50370501_119_dialog_content = "너도 봤니?",
  ui_story_5037_50370501_120_dialog_content = "멍멍!",
  ui_story_5037_50370501_121_dialog_content = "감히 내 콘서트에서 그런 파렴치한 짓을...",
  ui_story_5037_50370501_122_dialog_content = "마시멜로, 준비됐어?",
  ui_story_5037_50370501_123_dialog_content = "오늘도 속전속결로 정의를 구현하자!",
  ui_story_5037_50370501_124_dialog_content = "멍멍!",
  ui_story_5037_50370501_125_dialog_content = "심사 콘서트 지인 평가단 후속 인터뷰, 레디...",
  ui_story_5037_50370501_126_dialog_content = "액션!",
  ui_story_5037_50370501_127_dialog_content = "이번 콘서트는 10점 만점에 몇 점을 주고 싶나요?",
  ui_story_5037_50370501_128_dialog_content = "음! 12점이요!",
  ui_story_5037_50370501_129_dialog_content = "10점에 거의 근접했어.",
  ui_story_5037_50370501_130_dialog_content = "쯧쯧, 그 녀석이 무대에서 춤추고 노래하는 꼴을 보게 되다니...",
  ui_story_5037_50370501_131_dialog_content = "근데 점수는 주기 싫어.",
  ui_story_5037_50370501_132_dialog_content = "응? 왜냐고? 두 녀석이 우쭐해질까 봐 그러지.",
  ui_story_5037_50370501_133_dialog_content = "상대 팀의 콘서트에는 몇 점을 주고 싶나요?",
  ui_story_5037_50370501_134_dialog_content = "10점!",
  ui_story_5037_50370501_135_dialog_content = "완벽했어요. 하지만 골디 씨의 콘서트 분위기가 확실히 더 좋았다고 생각해요.",
  ui_story_5037_50370501_136_dialog_content = "9점.",
  ui_story_5037_50370501_137_dialog_content = "안 봤어. 어차피 피아 얘들이랑 별 차이도 없을 거잖아.",
  ui_story_5037_50370501_138_dialog_content = "친구에게 해주고 싶은 말이 있나요?",
  ui_story_5037_50370501_139_dialog_content = "우리 PlayerName 하고 싶은 거 다 해! 테르테르가 영원히 함께할게!",
  ui_story_5037_50370501_140_dialog_content = "노력은 거짓말을 하지 않는 법이야.",
  ui_story_5037_50370501_141_dialog_content = "상금이 걸려 있다면서?",
  ui_story_5037_50370501_142_dialog_content = "상금 꼭 가져 와!",
  ui_story_5037_50370501_143_dialog_content = "안 그러면... 후후후...",
  ui_story_5037_50370501_144_dialog_content = "평가단 친구분! 촉수로 카메라 휘감지 말아 주세요!",
  ui_story_5037_50370601_1_dialog_content = "PlayerName 팀의 졸업 콘서트 사전 인터뷰, 레디...",
  ui_story_5037_50370601_2_dialog_content = "액션!",
  ui_story_5037_50370601_3_dialog_content = "졸업 콘서트의 콘셉트는 무엇인가요?",
  ui_story_5037_50370601_4_dialog_content = "이번 졸업 콘서트 콘셉트는 「활짝 핀 젊음」이에요.",
  ui_story_5037_50370601_5_dialog_content = "그리고 여러분이 걱정하실까 봐 미리 말씀드릴게요~",
  ui_story_5037_50370601_6_dialog_content = "졸업 콘서트라곤 해도, 제가 진짜로 스타 엔터테인먼트를 「졸업」하는 건 아니에요.",
  ui_story_5037_50370601_7_dialog_content = "맞아. 「자라나는 새싹」, 「피어나는 꽃」부터 「활짝 핀 젊음」까지...",
  ui_story_5037_50370601_8_dialog_content = "세 번의 콘서트는 사실 리얼리티 프로를 통해 아이돌의 삶을 함축적으로\n보여주는 거거든.",
  ui_story_5037_50370601_9_dialog_content = "그러니까 골디는 방송 이후에도 아이돌로서 활약할 거야.",
  ui_story_5037_50370601_10_dialog_content = "네, 앞으로도 더 좋은 작품과 무대로 여러분을 찾아뵐 거예요!",
  ui_story_5037_50370601_11_dialog_content = "아쉽지만 그때가 되면 전 골디의 프로듀서가 아니겠지만.",
  ui_story_5037_50370601_12_dialog_content = "......",
  ui_story_5037_50370601_13_dialog_content = "하핫~ 그러게요. 스타 엔터테인먼트의 프로듀서가 되는 건 쉽지 않은 일이니까요.",
  ui_story_5037_50370601_14_dialog_content = "먼저 스타 엔터테인먼트에 이력서를 내고, 샤엘 씨의 여러 심사를 거쳐야 해요.",
  ui_story_5037_50370601_15_dialog_content = "PlayerName 씨처럼 뛰어난 인재라도 자신이 없을 수도 있겠네요.",
  ui_story_5037_50370601_16_dialog_content = "이 리얼리티 프로그램 촬영이 아니었다면, 난 실력자들이 잔뜩 있는 움브라톤에서\n프로듀서가 될 기회조차 없었을 거야.",
  ui_story_5037_50370601_17_dialog_content = "난 다른 사람들보다 더 특출난 것도 없으니까, 이 프로그램이 끝나고 나면\n진짜 프로듀서는 될 수 없겠지.",
  ui_story_5037_50370601_18_dialog_content = "그래도 난 골디와 함께 이 프로그램을 하면서 이만큼 성장했어.\n그걸로 충분히 만족해!",
  ui_story_5037_50370601_19_dialog_content = "PlayerName 씨...",
  ui_story_5037_50370601_20_dialog_content = "아직 감동 주기엔 이르다구!",
  ui_story_5037_50370601_21_dialog_content = "이번 콘서트를 위해 새로운 곡을 만들었나요?",
  ui_story_5037_50370601_22_dialog_content = "당연하죠.",
  ui_story_5037_50370601_23_dialog_content = "PlayerName 씨한테 이번 졸업 콘서트 콘셉트가 「활짝 핀 젊음」이라는 걸 듣고...",
  ui_story_5037_50370601_24_dialog_content = "젊음이란... 청춘이란 무엇인지 저 자신에게 묻지 않을 수 없었어요.",
  ui_story_5037_50370601_25_dialog_content = "그러자 머릿속에 많은 생각이 떠올랐죠.",
  ui_story_5037_50370601_26_dialog_content = "걱정 없이 움브라톤의 거리를 소란스럽게 다니는 거?",
  ui_story_5037_50370601_27_dialog_content = "졸린 눈으로 교실에 앉아 교수님의 강의를 듣는 거?",
  ui_story_5037_50370601_28_dialog_content = "아니면 일찍부터 삶의 무게를 지고 직장에서 땀 흘리는 거?",
  ui_story_5037_50370601_29_dialog_content = "그리고 전 그렇게 생각했어요. 청춘에 꼭 정해진 모습이 있는 건 아니라고 말이죠.",
  ui_story_5037_50370601_30_dialog_content = "모든 청춘은 자신의 꽃을 피워낼 가치가 있는 거예요~",
  ui_story_5037_50370601_31_dialog_content = "그래서 이런 생각들을 토대로 이번 콘서트에서 들려드릴 곡을 써 봤어요.",
  ui_story_5037_50370601_32_dialog_content = "프로듀서는 골디의 이번 자작곡을 어떻게 생각하시나요?",
  ui_story_5037_50370601_33_dialog_content = "골디가 쓴 노래는 언제나 옳아!",
  ui_story_5037_50370601_34_dialog_content = "이번 「활짝 핀 젊음」 졸업 콘서트를 위해 쓴 노래는 꼭 들어 봐야 해.",
  ui_story_5037_50370601_35_dialog_content = "특히 그중에서 「이별」을 다룬 노래가 있는데...",
  ui_story_5037_50370601_36_dialog_content = "샤엘 씨가 이번 리얼리티 프로의 엔딩곡으로도 쓰겠다고 하더라고.",
  ui_story_5037_50370601_37_dialog_content = "이별이 없는 인생이란 없지만...",
  ui_story_5037_50370601_38_dialog_content = "그래도 항상 여러분 앞에서 활동하며 함께 성장해 가도록 노력할 거예요.",
  ui_story_5037_50370601_39_dialog_content = "그러니까 여러분도 제 성장을 지켜봐 주셔야 해요~",
  ui_story_5037_50370601_40_dialog_content = "골디가 프로듀서에게 하고픈 말이 있나요?",
  ui_story_5037_50370601_41_dialog_content = "뭐? 콘서트 시작도 전에 그런 질문이야?",
  ui_story_5037_50370601_42_dialog_content = "괜찮아.",
  ui_story_5037_50370601_43_dialog_content = "콘서트가 끝나면 말이 안 나올 것 같거든. 후훗~",
  ui_story_5037_50370601_44_dialog_content = "응?",
  ui_story_5037_50370601_45_dialog_content = "흠흠, 프로듀서한테 하고픈 말이라면...",
  ui_story_5037_50370601_46_dialog_content = "그동안 언제나 내 곁에 있어 줘서 고마워.",
  ui_story_5037_50370601_47_dialog_content = "솔직히 말하면 난 늘 혼자 다녀서, 옆에 프로듀서가 있는 게 익숙하지가 않았어.",
  ui_story_5037_50370601_48_dialog_content = "처음엔 프로그램이 이슈가 됐으면 해서 당신이 내 프로듀서가 되는 데 동의했어.",
  ui_story_5037_50370601_49_dialog_content = "근데 당신은 정말 아무것도 모르는 풋내기에서 이제는 프로다운 프로듀서가 돼 줬어.",
  ui_story_5037_50370601_50_dialog_content = "날 위해 스케줄을 짜고, 파파라치 대처는 물론, 콘서트의 디테일까지 설계해 줬어...",
  ui_story_5037_50370601_51_dialog_content = "덕분에 난 작곡과 리허설에만 집중할 수 있었어.",
  ui_story_5037_50370601_52_dialog_content = "그리고 이젠 알게 됐어. 난 점차 프로듀서 없이는 안 되게 돼버린 거야.",
  ui_story_5037_50370601_53_dialog_content = "앞으로 PlayerName 씨가 프로듀서 일을 더는 하지 않을지도 모르지만,\n그래도 당신은...",
  ui_story_5037_50370601_54_dialog_content = "내 마음속 최고의 프로듀서였다고 말하고 싶어!",
  ui_story_5037_50370601_55_dialog_content = ".지금까지 내가 만났던 프로듀서들 중에서 말이야.",
  ui_story_5037_50370601_56_dialog_content = "골디가 지금까지 만난 프로듀서는 나 하나 아니었어?",
  ui_story_5037_50370601_57_dialog_content = "내 말 아직 안 끝났어~ 당신이 앞으로 어디서 뭘 하든지!",
  ui_story_5037_50370601_58_dialog_content = "어떤 분야에서든지 잘할 거라고 난 믿어.",
  ui_story_5037_50370601_59_dialog_content = "그때의 나도...",
  ui_story_5037_50370601_60_dialog_content = "......",
  ui_story_5037_50370601_61_dialog_content = "골디?",
  ui_story_5037_50370601_62_dialog_content = "크흠...",
  ui_story_5037_50370601_63_dialog_content = "<size=30>리리카, 방금 건 편집해줘~ 다시 할게!</size>",
  ui_story_5037_50370601_64_dialog_content = "당신이 앞으로 어디서 뭘 하든지!",
  ui_story_5037_50370601_65_dialog_content = "어떤 분야에서든지 잘할 거라고 난 믿어.",
  ui_story_5037_50370601_66_dialog_content = "그때도 난 열심히 내 길을 가고 있을게.\nPlayerName 씨의 기대를 저버릴 수 없으니까~",
  ui_story_5037_50370601_67_dialog_content = "프로듀서가 골디한테 하고픈 말이 있나요?",
  ui_story_5037_50370601_68_dialog_content = "나도 골디한테 고맙다고 말하고 싶어.",
  ui_story_5037_50370601_69_dialog_content = "네 격려 덕분에 난 감히 상상도 못 했던 많은 일을 해낼 수 있었어.",
  ui_story_5037_50370601_70_dialog_content = "골디와 내가 지금까지 이 프로그램에서 함께 여기까지 올 수 있었던 건,\n골디는 혼자서도 충분히 빛나기 때문이야!",
  ui_story_5037_50370601_71_dialog_content = "그동안 내게 어떤 발전과 성장이 있었다면...",
  ui_story_5037_50370601_72_dialog_content = "그건 모두 골디한테서 받은 빛이 반사된 것뿐이야!",
  ui_story_5037_50370601_73_dialog_content = "PlayerName 씨, 당신은 이미 눈부신걸.",
  ui_story_5037_50370601_74_dialog_content = "골디, 이제 네 곁에 내가 없어도...",
  ui_story_5037_50370601_75_dialog_content = "넌 영원히 반짝반짝 빛나는 아이돌일 거야.",
  ui_story_5037_50370601_76_dialog_content = "넌 최고의 아이돌이 될 거고, 아스트라 대륙의 전설이 될 거야!",
  ui_story_5037_50370601_77_dialog_content = "그리고 난 골디 널 영원히 응원할게.",
  ui_story_5037_50370601_78_dialog_content = "PlayerName 팀의 졸업 콘서트 사전 인터뷰...",
  ui_story_5037_50370601_79_dialog_content = "촬영 종료!",
  ui_story_5037_50370601_80_dialog_content = "......",
  ui_story_5037_50370601_81_dialog_content = "......",
  ui_story_5037_50370601_82_dialog_content = "응? 분위기가 왜 이렇게 가라앉았지?",
  ui_story_5037_50370601_83_dialog_content = "내가 물어보면 안 될 걸 물어본 거야?",
  ui_story_5037_50370601_84_dialog_content = "이런 인터뷰가 리얼리티 프로그램 출연자의 감정에도 영향을 주는 걸까?",
  ui_story_5037_50370601_85_dialog_content = "앗, 인터뷰 때문에 이따 골디가 공연하는 데 지장이 생기면 안 되는데?!",
  ui_story_5037_50370601_86_dialog_content = "안심해, 리리카.",
  ui_story_5037_50370601_87_dialog_content = "봐~ 난 아무 문제 없어!",
  ui_story_5037_50370601_88_dialog_content = "다행이야! 골디의 미소가 돌아왔어!",
  ui_story_5037_50370601_89_dialog_content = "프로듀서~",
  ui_story_5037_50370601_90_dialog_content = "응, 여기.",
  ui_story_5037_50370601_91_dialog_content = "고마워~",
  ui_story_5037_50370601_92_dialog_content = "어라라? 내가 또 뭘 놓친 거야?",
  ui_story_5037_50370601_93_dialog_content = "하~ 아~",
  ui_story_5037_50370601_94_dialog_content = "박하맛 목캔디는 역시 마음을 진정시켜 준다니까.",
  ui_story_5037_50370601_95_dialog_content = "저기, 골디 콘서트장은 여기서 어디로 가야 합니까?",
  ui_story_5037_50370601_96_dialog_content = "어라? 관객이 어떻게 백스테이지까지 온 거야?",
  ui_story_5037_50370601_97_dialog_content = "이쪽으로 쭉 가시다가 왼쪽으로 꺾으시면 돼요~",
  ui_story_5037_50370601_98_dialog_content = "와! 대박! 혹시 골디 씨 아닌가요?",
  ui_story_5037_50370601_99_dialog_content = "뭐야, 진짜네? 골디 씨! 제 옷에 사인 좀 해 주실 수 있습니까?!",
  ui_story_5037_50370601_100_dialog_content = "전 북방에서부터 여기까지 달려왔습니다!",
  ui_story_5037_50370601_101_dialog_content = "전 레디젤 렌치에서 왔어요!",
  ui_story_5037_50370601_102_dialog_content = "지는 운도에서 왔심더!",
  ui_story_5037_50370601_103_dialog_content = "전 유포리아에서 왔어요!",
  ui_story_5037_50370601_104_dialog_content = "자자, 여러분.",
  ui_story_5037_50370601_105_dialog_content = "콘서트가 끝나면 골디가 직접 사인도 해드릴 거고 포토타임도 있어요.",
  ui_story_5037_50370601_106_dialog_content = "콘서트가 곧 시작할 테니까, 일단 현장에 가서 기다려 주세요.",
  ui_story_5037_50370601_107_dialog_content = "사인에다 포토타임까지?!",
  ui_story_5037_50370601_108_dialog_content = "그럼 제일 먼저 가야지!",
  ui_story_5037_50370601_109_dialog_content = "빨리 가자, 빨리 가야 골디랑 사진 찍을 수 있어!",
  ui_story_5037_50370601_110_dialog_content = "서두를 거 없어요! 기회는 모두에게 드릴 거니까요!",
  ui_story_5037_50370601_111_dialog_content = "휴~ 다들 달리기가 엄청 빠르네. 아무도 내 말을 못 들은 것 같아.",
  ui_story_5037_50370601_112_dialog_content = "근데 이번엔 관객들이 진짜 많이 왔어. 게다가 다들 다른 지역에서 온 것 같고.",
  ui_story_5037_50370601_113_dialog_content = "골디의 아스트라 대륙 순회 콘서트도 희망이 보이는걸!",
  ui_story_5037_50370601_114_dialog_content = "응? 골디, 왜 그래?",
  ui_story_5037_50370601_115_dialog_content = "프로듀서, 나 너무 긴장돼.",
  ui_story_5037_50370601_116_dialog_content = "왠지 뭔가 첫 무대로 돌아간 것만 같은 느낌이야...",
  ui_story_5037_50370601_117_dialog_content = "골디, 무대 아래 관객들 좀 봐.",
  ui_story_5037_50370601_118_dialog_content = "저 사람들은 다 네가 좋아서 여기 온 거야!",
  ui_story_5037_50370601_119_dialog_content = "그리고 골디 넌 모두의 사랑을 받을 자격이 있는 아이돌이고.",
  ui_story_5037_50370601_120_dialog_content = "프로듀서...",
  ui_story_5037_50370601_121_dialog_content = "응, 당신 말이 맞아!",
  ui_story_5037_50370601_122_dialog_content = "난 이제 더는 과거의 내가 아냐.",
  ui_story_5037_50370601_123_dialog_content = "프로듀서, 똑똑히 지켜봐 줘.",
  ui_story_5037_50370601_124_dialog_content = "최고의 컨디션으로...",
  ui_story_5037_50370601_125_dialog_content = "이번 졸업 콘서트를 끝낼 테니까!",
  ui_story_5037_50370701_1_dialog_content = "졸업 콘서트도 무사히 마쳤네.",
  ui_story_5037_50370701_2_dialog_content = "소품이나 조명 실수도 없었고, 골디의 퍼포먼스는 당연히 말할 것도 없고.",
  ui_story_5037_50370701_3_dialog_content = "우리가 보여주고 싶은 모든 디테일도 완벽하게 표현했어.",
  ui_story_5037_50370701_4_dialog_content = "관객들은 골디의 이름을 부르며 자리를 떠나지 못하고.",
  ui_story_5037_50370701_5_dialog_content = "무대 위아래 모두 감격과 흥분으로 가득해.",
  ui_story_5037_50370701_6_dialog_content = "근데 왜...",
  ui_story_5037_50370701_7_dialog_content = "기분이 갑자기 이렇게 축 처지는 걸까?",
  ui_story_5037_50370701_8_dialog_content = "앗!",
  ui_story_5037_50370701_9_dialog_content = "까먹을 뻔했네! 샤엘 씨가 이 시간에 최종 결과를 발표하기로 했는데!",
  ui_story_5037_50370701_10_dialog_content = "이러다 늦겠는데?",
  ui_story_5037_50370701_11_dialog_content = "허억... 헉... 헉...",
  ui_story_5037_50370701_12_dialog_content = "늦어서 미안해요!",
  ui_story_5037_50370701_13_dialog_content = "조금만 더 늦었으면 두 사람이 대결을 포기한 걸로 알았을 거야.",
  ui_story_5037_50370701_14_dialog_content = "근데 골디는? 왜 혼자 왔어?",
  ui_story_5037_50370701_15_dialog_content = "골디는 팬들이랑 소통하느라 자리를 비울 수가 없어서요.",
  ui_story_5037_50370701_16_dialog_content = "흥! 그게 뭐 그렇게 대단하다구!\n사부도 팬들한테 무수한 사진 촬영 요청을 받았거든!",
  ui_story_5037_50370701_17_dialog_content = "우리 아이돌들 인기가 정말 대단하네.",
  ui_story_5037_50370701_18_dialog_content = "좋아, 아주 좋은 일이야~",
  ui_story_5037_50370701_19_dialog_content = "우리 두 아이돌이 좀 한가해졌을 때 직접 축하한다는 말을 전해 주고 싶었거든.",
  ui_story_5037_50370701_20_dialog_content = "그런데 이따 영화 제작사 사장님과 미팅을 하기로 해서 그건 좀 어렵게 됐지 뭐야.",
  ui_story_5037_50370701_21_dialog_content = "샤엘 씨는 역시 우리보다 훨씬 바쁘네요.",
  ui_story_5037_50370701_22_dialog_content = "그런 건 괜찮으니까 빨리 결과를 알려 줘, 샤엘 사장님!",
  ui_story_5037_50370701_23_dialog_content = "피아 프로듀서는 성격이 참 급하다니까.",
  ui_story_5037_50370701_24_dialog_content = "그렇지만 성격이 급한 게 나쁜 것만은 아니었어. 비크의 졸업 콘서트를 보면...",
  ui_story_5037_50370701_25_dialog_content = "피아가 짧은 시간에 콘서트 기획이란 무엇인지 깨우친 것 같았거든.",
  ui_story_5037_50370701_26_dialog_content = "심사 콘서트랑 비교해서 졸업 콘서트는 무대 효과나 기획에서 눈에 띄게 발전했어.",
  ui_story_5037_50370701_27_dialog_content = "당연하지! 피아가 진짜 열심히 노력했다구!",
  ui_story_5037_50370701_28_dialog_content = "반면에 골디는 이미 두 번은 없을 심사 콘서트를 해냈지.",
  ui_story_5037_50370701_29_dialog_content = "그렇지만 프로듀서의 이번 무대 기획 역시 놀라웠어.",
  ui_story_5037_50370701_30_dialog_content = "거기에 골디의 자작 신곡까지 해서 관객한테 감동을 전했고 말이야.",
  ui_story_5037_50370701_31_dialog_content = "에이, 뭐야... 피아만 칭찬받는 줄 알았는데...",
  ui_story_5037_50370701_32_dialog_content = "이번 대결 결과는 피아 팀이...",
  ui_story_5037_50370701_33_dialog_content = "뭐? 피아 팀이 어쨌는데? 응? 빨리 말해 줘!",
  ui_story_5037_50370701_34_dialog_content = "피아가 이긴 거야?!",
  ui_story_5037_50370701_35_dialog_content = "달링, 말은 끝까지 들어야지.",
  ui_story_5037_50370701_36_dialog_content = "아쉽지만 아주 근소한 차이로 피아 팀이 PlayerName 팀한테 졌어.",
  ui_story_5037_50370701_37_dialog_content = "두 팀 표 차이가 한 자릿수 정도밖에 안 날 거야~",
  ui_story_5037_50370701_38_dialog_content = "에에에에에엥?!",
  ui_story_5037_50370701_39_dialog_content = "세 번의 콘서트 성적을 종합해서 최종 우승 상금을 가져갈 사람은...",
  ui_story_5037_50370701_40_dialog_content = "<size=45>골디와 PlayerName 두 사람이야!</size>",
  ui_story_5037_50370701_41_dialog_content = "......",
  ui_story_5037_50370701_42_dialog_content = "흐아아앙...!",
  ui_story_5037_50370701_43_dialog_content = "피아가 얼마나, 얼마나 노력했는데...",
  ui_story_5037_50370701_44_dialog_content = "답도 없는 사부를 감시하면서 밤에 잠도 안 자고 콘서트 기획 공부도 했다구...",
  ui_story_5037_50370701_45_dialog_content = "피아 프로듀서, 자꾸 그러면 지금부터 발표할 상은 못 듣게 될걸?",
  ui_story_5037_50370701_46_dialog_content = "어? 상이 또 있어?",
  ui_story_5037_50370701_47_dialog_content = "피아와 비크 두 사람도 그동안의 노력으로 많은 팬을 모아\n공중상회의 매출 상승에 기여했어.",
  ui_story_5037_50370701_48_dialog_content = "그런 두 사람의 성과를 감안해서...",
  ui_story_5037_50370701_49_dialog_content = "보너스 상금을 주기로 했어~",
  ui_story_5037_50370701_50_dialog_content = "보너스...",
  ui_story_5037_50370701_51_dialog_content = "상그으으으음?!",
  ui_story_5037_50370701_52_dialog_content = "역시 피아랑 사부의 노력은 쓸데없는 짓이 아니었어!\n열심히 하면 다 보답을 받는 거구나! 우에에엥!",
  ui_story_5037_50370701_53_dialog_content = "크흠, 아직 하나 더 남았어~",
  ui_story_5037_50370701_54_dialog_content = "이번 리얼리티 프로그램을 촬영하면서 「최고의 노력상」을 받을 사람은...",
  ui_story_5037_50370701_55_dialog_content = "비크야!",
  ui_story_5037_50370701_56_dialog_content = "사부? 우리 사부한테 상을 주는 거야?",
  ui_story_5037_50370701_57_dialog_content = "그것도 「최고의 노력상」이라구?",
  ui_story_5037_50370701_58_dialog_content = "사부가 골디 언니를 이기고 사람들한테 인정을 받다니!",
  ui_story_5037_50370701_59_dialog_content = "역시 우리 사부도 썩 나쁘지 않다니까.",
  ui_story_5037_50370701_60_dialog_content = "헤헤, 이것도 피아랑 키아로가 열심히 일한 게 인정받은 거라구~",
  ui_story_5037_50370701_61_dialog_content = "루~",
  ui_story_5037_50370701_62_dialog_content = "이 상은 우리가 가져갈게! 미안하게 됐어, PlayerName! 헤헤헷.",
  ui_story_5037_50370701_63_dialog_content = "비크 씨가 노력한 만큼 당연하다고 생각해.",
  ui_story_5037_50370701_64_dialog_content = "다음으로 「최고의 프로듀서상」 수상자는...",
  ui_story_5037_50370701_65_dialog_content = "<size=45>PlayerName 프로듀서야!</size>",
  ui_story_5037_50370701_66_dialog_content = "네에에?",
  ui_story_5037_50370701_67_dialog_content = "제가요? 최고의 프로듀서요?",
  ui_story_5037_50370701_68_dialog_content = "...!!!",
  ui_story_5037_50370701_69_dialog_content = "흥, 그래! 좋아.",
  ui_story_5037_50370701_70_dialog_content = "PlayerName 네가 피아보다 프로듀서로서 기량이 더 빠르게 좋아지고,\n더 우수했단 건 피아도 인정해.",
  ui_story_5037_50370701_71_dialog_content = "근데 그거 다 PlayerName 네가 피아보다 나이가 좀 많아서 그런 거거든!",
  ui_story_5037_50370701_72_dialog_content = "피아도 PlayerName 너랑 똑같은 나이가 되면, PlayerName 너보다 훨씬 더\n대단해질 거야!",
  ui_story_5037_50370701_73_dialog_content = "피아?",
  ui_story_5037_50370701_74_dialog_content = "뭐야, 할 말만 하고 가버리는 거야?",
  ui_story_5037_50370701_75_dialog_content = "괜찮아. 비크를 찾으러 가는 것 같으니까.",
  ui_story_5037_50370701_76_dialog_content = "말은 좀 험하게 하긴 해도, 사실 마음은 상냥한 아이인걸.",
  ui_story_5037_50370701_77_dialog_content = "샤엘 씨는 피아에 대해 어떻게 그렇게 잘 아세요?",
  ui_story_5037_50370701_78_dialog_content = "난 아이테르가 아니라서 감응 능력은 없지만...",
  ui_story_5037_50370701_79_dialog_content = "사람의 마음을 이해하는 건 PlayerName 너보다 더 잘할지도 몰라.",
  ui_story_5037_50370701_80_dialog_content = "그렇지 않았다면 내가 어떻게 빈손으로 시작해서 공중상회를 이만큼 키웠겠어?",
  ui_story_5037_50370701_81_dialog_content = "......",
  ui_story_5037_50370701_82_dialog_content = "리리카.",
  ui_story_5037_50370701_83_dialog_content = "네, 샤엘 사장님, 저 여기 있어요~",
  ui_story_5037_50370701_84_dialog_content = "그동안 찍었던 소재들 모두 좋았어, 아주 만족스러워.",
  ui_story_5037_50370701_85_dialog_content = "잘 편집하면 정말 매력적인 리얼리티 프로그램이 될 거야.",
  ui_story_5037_50370701_86_dialog_content = "그때가 되면 감독이 돼 달라고 널 찾는 사람도 많아지겠지.",
  ui_story_5037_50370701_87_dialog_content = "리리카가 완벽하게 편집할게요!",
  ui_story_5037_50370701_88_dialog_content = "나중에도 필요한 일이 있으면 리리카를 또 불러주세요~",
  ui_story_5037_50370701_89_dialog_content = "응, 콘서트도 끝났으니 이제부터는 재밌는 일들이 많을 거야.",
  ui_story_5037_50370701_90_dialog_content = "마지막까지 소재를 놓치지 않도록 잘 지켜봐 줬으면 좋겠어.",
  ui_story_5037_50370701_91_dialog_content = "네! 샤엘 사장님!",
  ui_story_5037_50370701_92_dialog_content = "이 리리카한테 맡겨만 주세요~",
  ui_story_5037_50370701_93_dialog_content = "PlayerName, 네가 계속 프로듀서로 남고 싶다면, 난 환영이야.",
  ui_story_5037_50370701_94_dialog_content = "하지만 그땐 내 사무실로 이력서를 보내 줘야 해. 잊지 마.",
  ui_story_5037_50370701_95_dialog_content = "아, 알겠어요!",
  ui_story_5037_50370701_96_dialog_content = "아, 시간이 다 됐네. 난 비즈니스 미팅이 있어서 먼저 실례해야 할 것 같아.",
  ui_story_5037_50370701_97_dialog_content = "그럼 모두의 좋은 소식 기대할게~",
  ui_story_5037_50370701_98_dialog_content = "안녕히 가세요, 샤엘 씨!",
  ui_story_5037_50370701_99_dialog_content = "휴~ 내 프로듀서의 길도 이렇게 끝인 건가?",
  ui_story_5037_50370701_100_dialog_content = "......",
  ui_story_5037_50370701_101_dialog_content = "어? 리리카, 왜 카메라로 내 얼굴을 잡는 거야?",
  ui_story_5037_50370701_102_dialog_content = "리얼리티 프로그램은 아직 끝나지 않았다구.",
  ui_story_5037_50370701_103_dialog_content = "그러니까 난 아직도 일을 계속 해야 돼.",
  ui_story_5037_50370701_104_dialog_content = "근데 콘서트도 끝나서 난 이제 할 일이 없는데...",
  ui_story_5037_50370701_105_dialog_content = "뭘 더 찍으려고?",
  ui_story_5037_50370701_106_dialog_content = "그야 당연히 널 찍지.",
  ui_story_5037_50370701_107_dialog_content = "최고의 프로듀서~",
  ui_story_5037_50370701_108_dialog_content = "...그, 그럼 내가 뭘 하면 되는데?",
  ui_story_5037_50370701_109_dialog_content = "그건 스스로한테 물어봐야 하지 않을까?",
  ui_story_5037_50370701_110_dialog_content = "스스로한테 물어보라고?",
  ui_story_5037_50370701_111_dialog_content = "응, 예를 들면... 지금 가장 만나러 가고 싶은 사람이 있어?",
  ui_story_5037_50370701_112_dialog_content = "만나러 가고 싶은 사람?",
  ui_story_5037_50370701_113_dialog_content = "그렇구나. 오늘 하루는 아직 안 끝났잖아!",
  ui_story_5037_50370701_114_dialog_content = "내가 만나러 가고 싶은 사람은...",
  ui_story_5037_50370701_115_option_content = "(골디)",
  ui_story_5037_50370701_116_dialog_content = "빨리 가서 우리가 우승했다는 소식을 알려야지!",
  ui_story_5037_50370701_117_option_content = "(비크와 피아)",
  ui_story_5037_50370701_118_dialog_content = "비크 씨한테 축하한다고 해야겠어!",
  ui_story_5037_50370701_119_option_content = "(바이스와 카렌)",
  ui_story_5037_50370701_120_dialog_content = "두 사람한테 고맙다고 해야겠어....",
  ui_story_5037_50370701_121_dialog_content = "우리가 우승했다는 소식을 얼른 골디한테 말해줘야지!",
  ui_story_5037_50370701_122_dialog_content = "그리고 골디한테 하고 싶은 말도 있고...",
  ui_story_5037_50370701_123_dialog_content = "잠깐만!",
  ui_story_5037_50370701_124_dialog_content = "이런 건 사전 인터뷰 때 벌써 다 말한 것 같은데?!",
  ui_story_5037_50370701_125_dialog_content = "그, 그럼 상금에 대해 얘기해야 하나?",
  ui_story_5037_50370701_126_dialog_content = "「골디, 이 돈으로 의상을 더 살 수 있어!」",
  ui_story_5037_50370701_127_dialog_content = "으, 그것도 이상한데...",
  ui_story_5037_50370701_128_dialog_content = "「골디, 우리가 상금 탄 건 전부 네 덕이야!」",
  ui_story_5037_50370701_129_dialog_content = "안 돼, 그러면 너무 비즈니스 관계 같잖아.",
  ui_story_5037_50370701_130_dialog_content = "「골디, 수고했어!」",
  ui_story_5037_50370701_131_dialog_content = "이건 또 너무 가볍고...",
  ui_story_5037_50370701_132_dialog_content = "골디! 골디! 골디! 골디!",
  ui_story_5037_50370701_133_dialog_content = "여러분, 응원해 주셔서 고마워요~",
  ui_story_5037_50370701_134_dialog_content = "넘어지면 다치니까 한 분씩 차례대로 부탁해요!",
  ui_story_5037_50370701_135_dialog_content = "콘서트 끝난 지가 언젠데, 아직도 이렇게 많은 팬이 골디 곁에 있잖아?",
  ui_story_5037_50370701_136_dialog_content = "골디가 팬들이랑 즐겁게 대화하고 있으니까 난 없어도 될 것 같네.",
  ui_story_5037_50370701_137_dialog_content = "역시 방해하지 않는 게 좋겠어.",
  ui_story_5037_50370701_138_dialog_content = "응, 이참에 골디한테 무슨 말을 할지나 생각해 봐야겠네!",
  ui_story_5037_50370701_139_dialog_content = "<size=45>프로듀서!</size>",
  ui_story_5037_50370701_140_dialog_content = "어? 방금 골디가 날 부른 건가?",
  ui_story_5037_50370701_141_dialog_content = "<size=50>PlayerName 씨, 얼른 이리 와!</size>",
  ui_story_5037_50370701_142_dialog_content = "나도 팬들이랑 얘기 좀 나누라는 건가?",
  ui_story_5037_50370701_143_dialog_content = "아니, 됐어. 다 골디 팬이니까 나한텐 관심도 없을 거잖아.",
  ui_story_5037_50370701_144_dialog_content = "여러분 잠시만요, 금방 다녀올게요~",
  ui_story_5037_50370701_145_dialog_content = "우리 골디 하고 싶은 거 다 해! 골디락스가 영원히 함께할게!",
  ui_story_5037_50370701_146_dialog_content = "어라?",
  ui_story_5037_50370701_147_dialog_content = "골디가 왜 내 쪽으로 오고 있지?",
  ui_story_5037_50370701_148_dialog_content = "프로듀서, 여기 서서 뭐 하고 있어?",
  ui_story_5037_50370701_149_dialog_content = "너, 너한테 말해줄 게 있어서...",
  ui_story_5037_50370701_150_dialog_content = "우리가 이겼어!",
  ui_story_5037_50370701_151_dialog_content = "프로듀서, 그걸 이제야 안 거야? 너무 늦은 거 아니야?",
  ui_story_5037_50370701_152_dialog_content = "골디는 벌써 알고 있었어?",
  ui_story_5037_50370701_153_dialog_content = "후후, 마지막 곡을 다 부를 때부터 알았지.",
  ui_story_5037_50370701_154_dialog_content = "우린 세 번의 콘서트 모두 후회 없이 끝냈으니까.",
  ui_story_5037_50370701_155_dialog_content = "그건 우리 자신을 이긴 거고, 우린 모든 과정의 승리자인 셈이라구.",
  ui_story_5037_50370701_156_dialog_content = "골디는 그렇게 생각하고 있었구나.",
  ui_story_5037_50370701_157_dialog_content = "다들 세 번의 콘서트 모두 기획이 너무 멋졌다고 하던데, 가서 인사하지 않을래?",
  ui_story_5037_50370701_158_dialog_content = "으음, 난...",
  ui_story_5037_50370701_159_dialog_content = "팬들을 오래 기다리게 하는 건 아이돌과 프로듀서가 할 일이 아닌데~",
  ui_story_5037_50370701_160_dialog_content = "사랑하는 골디락스 여러분, 오래 기다렸죠?",
  ui_story_5037_50370701_161_dialog_content = "여러분한테 소개할 사람이 있어요.",
  ui_story_5037_50370701_162_dialog_content = "짜자잔~!",
  ui_story_5037_50370701_163_dialog_content = "고, 골디락스 여러분, 안녕!",
  ui_story_5037_50370701_164_dialog_content = "맞아요! 여기 이렇게 부끄러워하는 이 사람이 바로 그 유명한\n아이테르 PlayerName 씨랍니다~",
  ui_story_5037_50370701_165_dialog_content = "그리고 그동안 제 옆을 지켜준 프로듀서이기도 해요!",
  ui_story_5037_50370701_166_dialog_content = "PlayerName 씨 덕분에 전 여러분께 이렇게 멋진 공연을 보여드릴 수 있었어요.",
  ui_story_5037_50370701_167_dialog_content = "난 그렇게 대단한 사람이 아니야. 사, 사실 이 직업을 접한 지도 얼마 안 됐어.",
  ui_story_5037_50370701_168_dialog_content = "저 비실비실해 보이는 사람이 골디의 프로듀서였군, 전혀 몰랐는데.",
  ui_story_5037_50370701_169_dialog_content = "그래서 사람은 겉으로 판단하면 안 된다니까. 정말 대단하네!",
  ui_story_5037_50370701_170_dialog_content = "난 골디의 오랜 팬으로서 지금까지 골디를 지켜봐 왔지.",
  ui_story_5037_50370701_171_dialog_content = "골디는 예전부터 이미 여러모로 뛰어났지만, 이렇게 프로듀서가 생기니까...",
  ui_story_5037_50370701_172_dialog_content = "더 많이 성장한 것 같아. 그리고 자기만의 색깔을 찾은 것 같아!",
  ui_story_5037_50370701_173_dialog_content = "난 그런 건 잘 모르겠고.",
  ui_story_5037_50370701_174_dialog_content = "내 평생 이렇게 멋진 콘서트는 처음이라는 건 확실히 알겠어!",
  ui_story_5037_50370701_175_dialog_content = "그게 다 PlayerName 프로듀서 덕분이었구나!",
  ui_story_5037_50370701_176_dialog_content = "PlayerName! 프로듀서! PlayerName! 프로듀서! PlayerName! 프로듀서!",
  ui_story_5037_50370701_177_dialog_content = "......",
  ui_story_5037_50370701_178_dialog_content = "(갑자기 많은 사람이 이름을 불러주니까... 되게 부끄럽네.)",
  ui_story_5037_50370701_179_dialog_content = "(난 무대 뒤에서 내가 할 수 있는 일을 했을 뿐인데, 이런 대접을 받아도 되나?)",
  ui_story_5037_50370701_180_dialog_content = "프로듀서...",
  ui_story_5037_50370701_181_dialog_content = "당신은 모두의 사랑을 받을 가치가 충분히 있는 멋진 사람이야.",
  ui_story_5037_50370701_182_dialog_content = "그동안 정말 수고 많았어!",
  ui_story_5037_50370701_183_dialog_content = "(앗, 내 생각을 어떻게 읽었지?)",
  ui_story_5037_50370701_184_dialog_content = "(게다가 내가 하려던 말도 골디가 먼저 해 버렸잖아!)",
  ui_story_5037_50370701_185_dialog_content = "프로듀서, 다들 당신한테 하고 싶은 말이 있는 것 같아~",
  ui_story_5037_50370701_186_dialog_content = "응?",
  ui_story_5037_50370701_187_dialog_content = "프로듀서님! 사인 좀 해주세요!",
  ui_story_5037_50370701_188_dialog_content = "전 「테르테르」는 아니지만, 프로듀서님 사인은 갖고 싶어요!",
  ui_story_5037_50370701_189_dialog_content = "저도요!",
  ui_story_5037_50370701_190_dialog_content = "저도!",
  ui_story_5037_50370701_191_dialog_content = "어... 어라?!",
  ui_story_5037_50370701_192_dialog_content = "이럴 줄 알았으면 사인 연습 좀 해 둘걸...",
  ui_story_5037_50370701_193_dialog_content = "우와!",
  ui_story_5037_50370701_194_dialog_content = "이렇게 많은 나이티움을 세 보는 건 처음이야!",
  ui_story_5037_50370701_195_dialog_content = "손이 저릴 때까지 돈을 센다는 게 이런 느낌이었구나?",
  ui_story_5037_50370701_196_dialog_content = "샤엘 사장님은 진짜 통이 크다니까!",
  ui_story_5037_50370701_197_dialog_content = "피아, 누구랑 얘기하는 거야?",
  ui_story_5037_50370701_198_dialog_content = "옆에 아무도 없는 것 같은데.",
  ui_story_5037_50370701_199_dialog_content = "누구긴 누구겠어? 당연히 허접 사부랑 얘기하던 거지!",
  ui_story_5037_50370701_200_dialog_content = "사부?",
  ui_story_5037_50370701_201_dialog_content = "어? PlayerName 네가 아니었으면 모를 뻔했네...",
  ui_story_5037_50370701_202_dialog_content = "허접 사부가 또 책상 밑에 누워서 자고 있었잖아!",
  ui_story_5037_50370701_203_dialog_content = "키아로! 빨리 사부를 끌어내!",
  ui_story_5037_50370701_204_dialog_content = "루!",
  ui_story_5037_50370701_205_dialog_content = "어라?",
  ui_story_5037_50370701_206_dialog_content = "그건 그렇고 PlayerName 넌 갑자기 어디서 나타난 거야?",
  ui_story_5037_50370701_207_dialog_content = "문이 열려 있길래 들어온 건데...",
  ui_story_5037_50370701_208_dialog_content = "뭐어?! 이 피아가 문도 안 닫고 돈을 셌다구?!",
  ui_story_5037_50370701_209_dialog_content = "걱정하지 마. 내가 들어오면서 닫았어.",
  ui_story_5037_50370701_210_dialog_content = "그 전에 도둑이 들어왔을 수도 있는 거 아냐?",
  ui_story_5037_50370701_211_dialog_content = "안 되겠어! 다시 세야지!",
  ui_story_5037_50370701_212_dialog_content = "루루!",
  ui_story_5037_50370701_213_dialog_content = "트레이닝은 이제 싫어...",
  ui_story_5037_50370701_214_dialog_content = "비크 씨?",
  ui_story_5037_50370701_215_dialog_content = "타래! 우리 빨리 도망가자!",
  ui_story_5037_50370701_216_dialog_content = "지금 이건... 잠꼬대하는 건가?",
  ui_story_5037_50370701_217_dialog_content = "83개, 84개, 85개...",
  ui_story_5037_50370701_218_dialog_content = "피아, 몇 번을 세도 나이티움 개수는 똑같을걸.",
  ui_story_5037_50370701_219_dialog_content = "그보다 너네 사부 좀 보라니까?",
  ui_story_5037_50370701_220_dialog_content = "키아로가 책상 밑에서 꺼냈는데 아무런 반응이 없어!",
  ui_story_5037_50370701_221_dialog_content = "잠깐만, 백 개까지만 세고...",
  ui_story_5037_50370701_222_dialog_content = "98개, 99개, 100개!",
  ui_story_5037_50370701_223_dialog_content = "방금 뭐라구?",
  ui_story_5037_50370701_224_dialog_content = "음, 빨리 비크 씨 좀 봐 봐!",
  ui_story_5037_50370701_225_dialog_content = "아무 반응이 없어.",
  ui_story_5037_50370701_226_dialog_content = "아, 숙면 중이라 그래.",
  ui_story_5037_50370701_227_dialog_content = "며칠 동안 피로가 쌓였을 거야...",
  ui_story_5037_50370701_228_dialog_content = "사부는 노동이란 걸 해본 적이 없는 사람이거든!",
  ui_story_5037_50370701_229_dialog_content = "빨리 도망쳐어어어!",
  ui_story_5037_50370701_230_dialog_content = "비크 씨, 깼어?",
  ui_story_5037_50370701_231_dialog_content = "PlayerName? 네가 왜 여기 있어?",
  ui_story_5037_50370701_232_dialog_content = "어, 얼른 도망쳐! 키아로가 제정신이 아니야! 나한테 계속 연습하래!",
  ui_story_5037_50370701_233_dialog_content = "글쎄, 방금 꿈꾼 거 아냐?",
  ui_story_5037_50370701_234_dialog_content = "응? 피아도 여기 있었네...?",
  ui_story_5037_50370701_235_dialog_content = "피아 앞에 나이티움이 왜 저렇게 쌓여있지?",
  ui_story_5037_50370701_236_dialog_content = "이거야말로 꿈인가?!",
  ui_story_5037_50370701_237_dialog_content = "하지만 아까 꾼 꿈보단 훨씬 낫네.",
  ui_story_5037_50370701_238_dialog_content = "으, 어떻게 말해야 비크 씨가 지금 이게 꿈이 아니랄 걸 알아챌까?",
  ui_story_5037_50370701_239_dialog_content = "후후, 아무래도 키아로가 한 번 나서 줘야겠는데!",
  ui_story_5037_50370701_240_dialog_content = "!!!",
  ui_story_5037_50370701_241_dialog_content = "우리 착한 제자 피아야, 이 사부는 지금 정신이 아주 멀쩡해!",
  ui_story_5037_50370701_242_dialog_content = "비크 씨도 좀 안됐네. 키아로 공포증이 생겨 버린 건가...",
  ui_story_5037_50370701_243_dialog_content = "어, 이거 다 진짜 나이티움이네?",
  ui_story_5037_50370701_244_dialog_content = "샤엘 사장님은 진짜 통이 엄청 크다니까!",
  ui_story_5037_50370701_245_dialog_content = "나랑 사부는 고작 며칠 동안만 리얼리티 프로그램에 참여했을 뿐인데,\n보너스 상금을 이렇게나 많이 줬어...",
  ui_story_5037_50370701_246_dialog_content = "진짜 아이돌이었다면 이거보다 더 많이 벌었겠지?",
  ui_story_5037_50370701_247_dialog_content = "피아, 다른 사람이 얼마를 버는지 신경 쓸 필요는 없지 않을까?\n우린 우리 생활을 잘 살아가면 되잖아.",
  ui_story_5037_50370701_248_dialog_content = "어? 좀 일리가 있는 것 같네?",
  ui_story_5037_50370701_249_dialog_content = "사부가 웬일로 제대로 된 의견을...",
  ui_story_5037_50370701_250_dialog_content = "이 돈이면 드디어 움브라톤에 새로 오픈했다는 고급 레스토랑에서\n제대로 식사를 할 수 있겠어~",
  ui_story_5037_50370701_251_dialog_content = "...그건 안 돼!",
  ui_story_5037_50370701_252_dialog_content = "왜 안 된다는 거야?",
  ui_story_5037_50370701_253_dialog_content = "며칠 동안 계속 피아가 하자는 대로 해 줬잖아~",
  ui_story_5037_50370701_254_dialog_content = "트레이닝이니 식단 관리니 해서 제대로 된 음식을 먹은 지가 언젠지 모르겠어.",
  ui_story_5037_50370701_255_dialog_content = "그걸 다 견뎌서 어렵사리 이렇게 두둑이 보너스를 받은 거니까,\n당연히 스스로를 좀 아껴 줘야 하지 않아?",
  ui_story_5037_50370701_256_dialog_content = "사부, 아직 우리 상황이 얼마나 심각한지 모르는구나?",
  ui_story_5037_50370701_257_dialog_content = "상금만 떼 놓고 보면 엄청 많아 보이겠지.",
  ui_story_5037_50370701_258_dialog_content = "근데 사부가 지금까지 질질 끌고 안 낸 드라코리온 식비랑 평상시 우리 식비,\n집 수리비, 피아 인건비 등등을 빼면...",
  ui_story_5037_50370701_259_dialog_content = "반도 안 남을걸.",
  ui_story_5037_50370701_260_dialog_content = "사부는 평소에도 영 못 미더운 사람이니까, 앞으로의 수입도 불확실하고...",
  ui_story_5037_50370701_261_dialog_content = "남은 상금으로 얼마나 버틸 수 있겠냐고!",
  ui_story_5037_50370701_262_dialog_content = "앞으로의 수입?",
  ui_story_5037_50370701_263_dialog_content = "비크 씨한텐 아이돌로 성공할 만한 잠재력이 있잖아.\n그럼 아이돌을 계속하면 되는 거 아냐?",
  ui_story_5037_50370701_264_dialog_content = "PlayerName, 나 좀 살려 주라.",
  ui_story_5037_50370701_265_dialog_content = "이만큼 버틴 것도 나한텐 기적인데, 이걸 매일 하라고?",
  ui_story_5037_50370701_266_dialog_content = "상상만 해도 지옥같아.",
  ui_story_5037_50370701_267_dialog_content = "...PlayerName 말이 맞아!",
  ui_story_5037_50370701_268_dialog_content = "어차피 사부는 집에 있으면서 환상동물을 제대로 못 돌보고,\n일을 해서 돈을 벌어 오는 것도 아니니까...",
  ui_story_5037_50370701_269_dialog_content = "이참에 아이돌이나 제대로 하는 게 낫겠어!",
  ui_story_5037_50370701_270_dialog_content = "리얼리티 프로그램이 방영되면 더 많은 팬이 사부를 좋아하게 되겠지!",
  ui_story_5037_50370701_271_dialog_content = "저기 피아야... 착하지...",
  ui_story_5037_50370701_272_dialog_content = "제발 나 좀 봐주라 진짜!",
  ui_story_5037_50370701_273_dialog_content = "오케이! 그럼 사부의 정식 아이돌 데뷔는 이렇게 깔끔하게 결정이네!",
  ui_story_5037_50370701_274_dialog_content = "뭐?!",
  ui_story_5037_50370701_275_dialog_content = "사부, 그럼 아직 시간 남았으니까 계속 트레이닝하자!",
  ui_story_5037_50370701_276_dialog_content = "나 진짜 힘이 하나도 없어...",
  ui_story_5037_50370701_277_dialog_content = "키아로, 우리 둘이 사부가 트레이닝하는 거 도와주자~",
  ui_story_5037_50370701_278_dialog_content = "싫어어어어어어어!",
  ui_story_5037_50370701_279_dialog_content = "어! 사부! 뛰는 게 왜 그렇게 빨라?",
  ui_story_5037_50370701_280_dialog_content = "힘 없는 거 아니었잖아! 그럴 힘 있으면 트레이닝이나 하라구!",
  ui_story_5037_50370701_281_dialog_content = "비크 씨...",
  ui_story_5037_50370701_282_dialog_content = "파이팅!",
  ui_story_5037_50370701_283_dialog_content = "최고의 프로듀서라...",
  ui_story_5037_50370701_284_dialog_content = "헤헤, 샤엘 씨가 나한테 이런 상을 주다니 믿기질 않네.",
  ui_story_5037_50370701_285_dialog_content = "스타 엔터테인먼트에 처음 왔을 땐 아무것도 몰라서 골디 발목만 잡는 거\n아닌가 걱정했었는데.",
  ui_story_5037_50370701_286_dialog_content = "이렇게 골디랑 함께 세 번의 콘서트를 마치고, 샤엘 씨한테 인정도 받게 될 줄이야!",
  ui_story_5037_50370701_287_dialog_content = "그래! 이 깜짝 소식을 바이스랑 카렌한테 알려야겠어.",
  ui_story_5037_50370701_288_dialog_content = "두 사람이면 이 근처에 있을 텐데.",
  ui_story_5037_50370701_289_dialog_content = "이 방에 있으려나?",
  ui_story_5037_50370701_290_dialog_content = "<color=#828282>똑똑똑!</color>",
  ui_story_5037_50370701_291_dialog_content = "들어갈게~",
  ui_story_5037_50370701_292_dialog_content = "어라, 이 방은 항상 불이 켜져 있었는데, 오늘은 왜 이렇게 어둡지?",
  ui_story_5037_50370701_293_dialog_content = "바이스? 카렌? 이상하네? 여기도 아닌가?",
  ui_story_5037_50370701_294_dialog_content = "<color=#828282>탁!</color>",
  ui_story_5037_50370701_295_dialog_content = "앗?!",
  ui_story_5037_50370701_296_dialog_content = "서프라이즈──!",
  ui_story_5037_50370701_297_dialog_content = "졸업 콘서트가 완벽하게 마무리됐네~",
  ui_story_5037_50370701_298_dialog_content = "축하해, PlayerName. 모든 임무를 다 해냈구나.",
  ui_story_5037_50370701_299_dialog_content = "이, 이게 다...",
  ui_story_5037_50370701_300_dialog_content = "새로 오픈한 고급 레스토랑에 부탁해서 준비한 맛있는 요리와 주스야.",
  ui_story_5037_50370701_301_dialog_content = "대왕 생크림 케이크도 있어~!",
  ui_story_5037_50370701_302_dialog_content = "PlayerName 네가 프로듀서 공부를 시작한 뒤로는 밥도 잘 안 먹은 것 같아서.",
  ui_story_5037_50370701_303_dialog_content = "우리가 깜짝 선물을 준비했어. 다 PlayerName 네가 좋아하는 음식들이야.",
  ui_story_5037_50370701_304_dialog_content = "바이스, 카렌...",
  ui_story_5037_50370701_305_dialog_content = "이걸 다 언제 준비한 거야?",
  ui_story_5037_50370701_306_dialog_content = "난 전혀 몰랐는데!",
  ui_story_5037_50370701_307_dialog_content = "헤헷, 한참 전부터 계획했지~",
  ui_story_5037_50370701_308_dialog_content = "PlayerName 넌 오늘 하루 무대 뒤에서 공연 준비로 바빴으니까,\n덕분에 우리도 「준비할 타이밍」을 가질 수 있었어.",
  ui_story_5037_50370701_309_dialog_content = "그렇다는 건... 오늘 결과도 알고 있어?",
  ui_story_5037_50370701_310_dialog_content = "그건 아직 몰라~",
  ui_story_5037_50370701_311_dialog_content = "음, 하지만 내가 졌다면 축하가 무슨 소용이겠어?",
  ui_story_5037_50370701_312_dialog_content = "나도, 바이스도, 오늘 결과가 어떤지는 상관없어...",
  ui_story_5037_50370701_313_dialog_content = "넌 노력으로 자신의 한계를 뛰어넘었으니까.",
  ui_story_5037_50370701_314_dialog_content = "PlayerName, 뭔가를 꾸준히 공부해서 끝까지 해내는 것만으로도 대단한 일이야~",
  ui_story_5037_50370701_315_dialog_content = "그러니까 충분히 축하할 의미가 있어!",
  ui_story_5037_50370701_316_dialog_content = "너희도 참... 무슨 말을 그렇게 감동적으로 해.",
  ui_story_5037_50370701_317_dialog_content = "눈에 먼지가 들어갔잖아!",
  ui_story_5037_50370701_318_dialog_content = "그래서 결과는 어땠어?",
  ui_story_5037_50370701_319_dialog_content = "결과는 상관없다면서?!",
  ui_story_5037_50370701_320_dialog_content = "아하하, 그야 우린 PlayerName 널 믿으니까~",
  ui_story_5037_50370701_321_dialog_content = "아까 문밖에서 「바이스랑 카렌한테 깜짝 소식을 알려야겠다」고 한 건 뭔데?",
  ui_story_5037_50370701_322_dialog_content = "헤헤, 나랑 골디가 대결에서 이겼어!",
  ui_story_5037_50370701_323_dialog_content = "거기다 난 「최고의 프로듀서」상까지 받았고!",
  ui_story_5037_50370701_324_dialog_content = "우와! 그런 상도 있었어?",
  ui_story_5037_50370701_325_dialog_content = "샤엘 씨는 역시 혜안이 있구나. PlayerName의 성장을 알아본 게 분명해.",
  ui_story_5037_50370701_326_dialog_content = "그래서 보너스 상금도 있어?!",
  ui_story_5037_50370701_327_dialog_content = "그건... 없는 것 같은데.",
  ui_story_5037_50370701_328_dialog_content = "아하하, 그래. 명예라는 건 원래 돈으로 환산할 수 없는 거니까~",
  ui_story_5037_50370701_329_dialog_content = "그 상을 받아서 앞으로 PlayerName의 일이 더 잘 풀릴지도 모르잖아.",
  ui_story_5037_50370701_330_dialog_content = "맞아. 지금도 이미 베테랑 프로듀서랑 능력이 비슷하잖아.",
  ui_story_5037_50370701_331_dialog_content = "너희가 옆에서 도와주지 않았다면 이런 자신감을 가지진 못했을 거야.",
  ui_story_5037_50370701_332_dialog_content = "바이스, 카렌. 며칠 동안 내 옆에서 아무 조건 없이 도와주고 가르쳐 줘서 고마워.",
  ui_story_5037_50370701_333_dialog_content = "음, 방금 그 말엔 잘못된 부분이 하나 있어.",
  ui_story_5037_50370701_334_dialog_content = "어?",
  ui_story_5037_50370701_335_dialog_content = "우리가 요 며칠 동안만 네 옆에 있던 건 아니잖아~",
  ui_story_5037_50370701_336_dialog_content = "맞아. 우린 항상 네 곁에 있었는걸.",
  ui_story_5037_50370701_337_dialog_content = "아, 그렇네!",
  ui_story_5037_50370701_338_dialog_content = "그럼 다시 말할게!",
  ui_story_5037_50370701_339_dialog_content = "됐어 됐어, 우리 사이에 그런 게 뭐가 필요하겠어.",
  ui_story_5037_50370701_340_dialog_content = "그리고 그거 알아?",
  ui_story_5037_50370701_341_dialog_content = "이번에 일루미나에 자료를 좀 찾으러 갔는데, 일루미나도 아이돌에 관심이 많더라고.",
  ui_story_5037_50370701_342_dialog_content = "비비안 님도 무슨 이벤트를 준비하시던데?\n일루미나를 대표할 아이돌을 선발하려는 것 같아!",
  ui_story_5037_50370701_343_dialog_content = "뭐?! 일루미나를 대표할 아이돌?",
  ui_story_5037_50370701_344_dialog_content = "울부짖어라. 이 공연의 생동감을 위하여!",
  ui_story_5037_50370701_345_dialog_content = "응? 왜 아무 소리가 없지?",
  ui_story_5037_50370701_346_dialog_content = "나의 노랫소리에 압도돼 박수도 환호도 잊어버렸나?",
  ui_story_5037_50370701_347_dialog_content = "하하하하하하하하하하하!",
  ui_story_5037_50370701_348_dialog_content = "으으으....",
  ui_story_5037_50370701_349_dialog_content = "어라? PlayerName, 무슨 생각 하길래 식은땀을 그렇게 흘려?",
  ui_story_5037_50370701_350_dialog_content = "아무것도 아니야!",
  ui_story_5037_50370701_351_dialog_content = "그냥 일루미나의 아이돌 이벤트가 재밌을 것 같아서!",
  ui_story_5037_50370701_352_dialog_content = "나도 아버님께 백야성에도 아이돌 오디션을 열자는 건의를 드려 볼까 해.",
  ui_story_5037_50370701_353_dialog_content = "뭐? 백야성의 대귀족들이 동의할까?",
  ui_story_5037_50370701_354_dialog_content = "어렵겠지.",
  ui_story_5037_50370701_355_dialog_content = "하지만 난 정말 이번 경험을 통해 많은 걸 배웠어.",
  ui_story_5037_50370701_356_dialog_content = "정정당당하게 자신의 매력을 보여주는 게 나쁜 일은 아니란 걸 느꼈고.",
  ui_story_5037_50370701_357_dialog_content = "그리고 오랫동안 날 괴롭혔던 것들이 갑자기 연기처럼 사라졌어.",
  ui_story_5037_50370701_358_dialog_content = "아~ 알겠어!",
  ui_story_5037_50370701_359_dialog_content = "카렌이 추구하는 「왕도」에 더 가까워진 거구나~?",
  ui_story_5037_50370701_360_dialog_content = "그게 「왕도」랑 상관이 있는 거야?",
  ui_story_5037_50370701_361_dialog_content = "잘 생각해 보면 전혀 다른 얘기는 아니야.",
  ui_story_5037_50370701_362_dialog_content = "그런가?",
  ui_story_5037_50370701_363_dialog_content = "아무튼! 음식 식으면 맛없어. 얼른 먹자!",
  ui_story_5037_50370701_364_dialog_content = "그건 그래. 일단 축배부터 들자.",
  ui_story_5037_50370701_365_dialog_content = "「최고의 프로듀서」상 받은 거 축하해! PlayerName!",
  ui_story_5037_50370701_366_dialog_content = "건배!",
  ui_story_5037_50370701_367_option_content = "건배!",
  ui_story_5037_50370801_1_dialog_content = "안무 특훈, 보컬 연습, 기자회견에다 악수회 장소 대관도 알아봐야 하고...",
  ui_story_5037_50370801_2_dialog_content = "?",
  ui_story_5037_50370801_3_dialog_content = "대관 문의하려면 점심 먹고 저녁 전에 해야 하는데, 기자는 또 오후에 온다고 하네...",
  ui_story_5037_50370801_4_dialog_content = "......",
  ui_story_5037_50370801_5_dialog_content = "골디가 쉴 시간이랑, 의상 갈아입고 화장 고칠 시간 내려면 이게 최선이겠는데...",
  ui_story_5037_50370801_6_dialog_content = "......?",
  ui_story_5037_50370801_7_dialog_content = "그럼 결국 새벽부터 종일 바쁜 거잖아?!",
  ui_story_5037_50370801_8_dialog_content = "PlayerName 씨?",
  ui_story_5037_50370801_9_dialog_content = "으앗?!",
  ui_story_5037_50370801_10_dialog_content = "골디였구나! 깜짝 놀랐네.",
  ui_story_5037_50370801_11_dialog_content = "뭘 그렇게 중얼거리고 있어?",
  ui_story_5037_50370801_12_dialog_content = "보니까 정신이 하나도 없는 것 같은데, 나랑 같이 안무 연습하러 갈래?",
  ui_story_5037_50370801_13_dialog_content = "몸을 움직이면 몸매랑 건강 유지에도 도움이 되거든!",
  ui_story_5037_50370801_14_dialog_content = "프로듀서의 건강은 아이돌 활동과 콘서트 효과에 직결되는 문제야!",
  ui_story_5037_50370801_15_dialog_content = "아, 지금 스케줄 짜고 있었어...",
  ui_story_5037_50370801_16_dialog_content = "매일 일정이 많아서 하나 끝내면 바로 다음 일정을 처리해야 돼...",
  ui_story_5037_50370801_17_dialog_content = "쉴 시간을 조금이라도 만들어 내기가 너무 힘들어!",
  ui_story_5037_50370801_18_dialog_content = "역시 내가 초보 프로듀서라서 그런 걸까...",
  ui_story_5037_50370801_19_dialog_content = "PlayerName 씨는 이미 대단해!",
  ui_story_5037_50370801_20_dialog_content = "프로듀서 일을 잠깐 했는데도 일상 업무는 이제 능숙하잖아.\n그건 아무나 할 수 있는 게 아니야!",
  ui_story_5037_50370801_21_dialog_content = "그러니까 슬퍼하지 말고 마시멜로라도 좀 만질래?",
  ui_story_5037_50370801_22_dialog_content = "부드러운 털을 만지면 마음이 편안해질 거야.",
  ui_story_5037_50370801_23_dialog_content = "멍멍!",
  ui_story_5037_50370801_24_dialog_content = "고마워, 그럼 조금만...",
  ui_story_5037_50370801_25_dialog_content = "잠깐!",
  ui_story_5037_50370801_26_dialog_content = "왜 그래?",
  ui_story_5037_50370801_27_dialog_content = "내일 취재 올 신문사에 연락해서 인터뷰 시간 잡는 걸 깜빡했어!",
  ui_story_5037_50370801_28_dialog_content = "미안, 나 먼저 갈게!",
  ui_story_5037_50370801_29_dialog_content = "......",
  ui_story_5037_50370801_30_dialog_content = "<color=#828282>얼마 후</color>",
  ui_story_5037_50370801_31_dialog_content = "휴... 아슬아슬했네.",
  ui_story_5037_50370801_32_dialog_content = "대형 신문사라서 실수로 바람이라도 맞혔다면 골디의 평판에 안 좋았을 거야.",
  ui_story_5037_50370801_33_dialog_content = "PlayerName 씨, 왔어?",
  ui_story_5037_50370801_34_dialog_content = "아, 골디! 미안해, 아까 너무 급하게 가느라 인사도 제대로 못 했어...",
  ui_story_5037_50370801_35_dialog_content = "아니야, 일 때문에 그러는 거 다 아는데 뭘.",
  ui_story_5037_50370801_36_dialog_content = "프로듀서 일은 정말 쉽지 않네. 그나마 요즘은 익숙해져 가고 있지만...",
  ui_story_5037_50370801_37_dialog_content = "하지만 이 업무는 아직도 적응하기 어려워!",
  ui_story_5037_50370801_38_dialog_content = "단순히 시간 잡는 일은 그리 어렵지 않아.",
  ui_story_5037_50370801_39_dialog_content = "하지만 저 파파라치들을 상대하면서 꼬투리 안 잡히는 건...",
  ui_story_5037_50370801_40_dialog_content = "너무 어려워...",
  ui_story_5037_50370801_41_dialog_content = "정말 고생이구나.",
  ui_story_5037_50370801_42_dialog_content = "힘들긴 하겠지만, 프로듀서는 지금 프로듀서가 해야 할 일을 아주 잘 해내고 있어!",
  ui_story_5037_50370801_43_dialog_content = "그것만으로 이미 대단한 거야!",
  ui_story_5037_50370801_44_dialog_content = "고마워! 칭찬을 받으면 피로가 없어지는 것 같아!",
  ui_story_5037_50370801_45_dialog_content = "맞아. 그러니까 누구든 칭찬이 필요한 거야!",
  ui_story_5037_50370801_46_dialog_content = "그러고 보면, 예전엔 계속 골디 혼자 노력해 왔었잖아?",
  ui_story_5037_50370801_47_dialog_content = "아이돌 일도 하면서 프로듀서 역할도 하고...",
  ui_story_5037_50370801_48_dialog_content = "연습도 해야 되고, 일정 관리에 파파라치 대응까지...",
  ui_story_5037_50370801_49_option_content = "생각만 해도 대단해!",
  ui_story_5037_50370801_50_dialog_content = "아하하... 그렇게 대단한 것까진 아니야~",
  ui_story_5037_50370801_51_option_content = "상상만 해도 어려운데...",
  ui_story_5037_50370801_52_dialog_content = "하지만 난 지금까지 잘 버텨왔어.",
  ui_story_5037_50370801_53_dialog_content = "아무리 나라도 두 가지 일을 혼자 짊어지기란 쉬운 일은 아니었어.",
  ui_story_5037_50370801_54_dialog_content = "예전엔 나도 여러 번 포기하고 싶을 정도로 많은 어려움을 겪었어.",
  ui_story_5037_50370801_55_dialog_content = "골디도 포기하고 싶을 때가 있었어? 전혀 몰랐어...",
  ui_story_5037_50370801_56_dialog_content = "일급비밀이야! 아무한테도 말하면 안 돼!",
  ui_story_5037_50370801_57_dialog_content = "절대 안 해. 누가 뭐래도 난 골디의 프로듀서니까 절대로 골디 이야기를\n함부로 하지 않을 거야!",
  ui_story_5037_50370801_58_dialog_content = "좋아, 그거면 됐어!",
  ui_story_5037_50370801_59_dialog_content = "예전의 난 데뷔하기 전까진 쭉 모든 걸 다 나 혼자 열심히 해 왔어.",
  ui_story_5037_50370801_60_dialog_content = "트레이닝도, 일정 분배도... 중요하지 않은 일이 하나도 없었지.\n신출귀몰한 파파라치들을 피하기 위해선 더 말할 것도 없었고.",
  ui_story_5037_50370801_61_dialog_content = "그 무렵의 난 하루에 한두 시간밖에 못 자는 날이 많았어!",
  ui_story_5037_50370801_62_dialog_content = "게다가 얼마나 늦게 잠자리에 들든, 아침에 일찍 일어나서 전날 뒤쳐진 양만큼\n트레이닝을 해야 했어.",
  ui_story_5037_50370801_63_dialog_content = "그렇게 고생했단 말이야?!",
  ui_story_5037_50370801_64_dialog_content = "나도 자주 밤을 새우긴 하는데, 1~2시간 잔 날은 이불 밖으로 나오기가 진짜\n죽을 만큼 싫더라고...",
  ui_story_5037_50370801_65_dialog_content = "나도 비슷했어!",
  ui_story_5037_50370801_66_dialog_content = "하루 이틀은 괜찮겠지만, 그게 더 오래... 심지어 몇 년 동안 계속되야 한다면?",
  ui_story_5037_50370801_67_dialog_content = "트레이닝이 끝나고 녹초가 될 때마다 나도 모르게 그런 생각이 들더라구...",
  ui_story_5037_50370801_68_dialog_content = "그치만 골디는 결국 그 모든 어려움을 이겨 내고, 지금 같은 유명 아이돌이 된 거잖아?",
  ui_story_5037_50370801_69_dialog_content = "응!",
  ui_story_5037_50370801_70_dialog_content = "매번 포기하고 싶어질 때면, 난 행운의 총알을 던졌어.\n그리고 탄두 부분이 아래로 떨어지면 곧 좋은 일이 일어날 거라고 믿었지!",
  ui_story_5037_50370801_71_dialog_content = "그리고 탄두는 매번 아래쪽을 향해 줬어. 그래서 난 계속 마음을 굳게 먹을 수 있었고,\n결국에는 지금의 내가 될 수 있었던 거야!",
  ui_story_5037_50370801_72_dialog_content = "정말 불굴의 의지네...",
  ui_story_5037_50370801_73_dialog_content = "후훗.",
  ui_story_5037_50370801_74_dialog_content = "하지만 지금은 그때랑은 달라.",
  ui_story_5037_50370801_75_dialog_content = "지금은 PlayerName 씨라는 믿음직한 프로듀서가 날 도와주고 있으니까.",
  ui_story_5037_50370801_76_dialog_content = "이제 난 다른 일엔 신경 쓰지 않고 트레이닝에 온전히 집중할 수 있어!",
  ui_story_5037_50370801_77_dialog_content = "실력이 향상되는 속도도 훨씬 빨라지고 있구!",
  ui_story_5037_50370801_78_dialog_content = "진짜... 내가 도움이 되고 있어?",
  ui_story_5037_50370801_79_dialog_content = "두말하면 잔소리지!",
  ui_story_5037_50370801_80_dialog_content = "그렇다면 다행이야!",
  ui_story_5037_50370801_81_dialog_content = "전에는 계속 내가 아무것도 못 하는 초짜라서 골디를 번거롭게만 만든다고 느꼈는데.",
  ui_story_5037_50370801_82_dialog_content = "그렇게 얘기해 주니까 다시 자신감이 생겼어.",
  ui_story_5037_50370801_83_dialog_content = "앞으로도 좋은 프로듀서가 되기 위해서 계속 노력할게. 잘 부탁해, 골디!",
  ui_story_5037_50370801_84_dialog_content = "응! 그러자!",
  ui_story_5037_50370901_1_dialog_content = "<color=#828282>오전, 트레이닝을 마친 후</color>",
  ui_story_5037_50370901_2_dialog_content = "수고했어, PlayerName 씨!",
  ui_story_5037_50370901_3_dialog_content = "오전 트레이닝은 다 끝났으니까, 점심엔 푹 쉬자.",
  ui_story_5037_50370901_4_dialog_content = "너도 수고 많았어, 골디!",
  ui_story_5037_50370901_5_dialog_content = "<color=#828282>똑똑똑!</color>",
  ui_story_5037_50370901_6_dialog_content = "들어오세요~",
  ui_story_5037_50370901_7_dialog_content = "PlayerName! 그리고 골디~",
  ui_story_5037_50370901_8_dialog_content = "안녕, 그로누 씨!",
  ui_story_5037_50370901_9_dialog_content = "그로누? 여긴 무슨 일이야?",
  ui_story_5037_50370901_10_dialog_content = "재료 사러 왔다가, 네가 움브라톤에서 프로듀서를 하고 있다길래 한 번 들러 봤어~",
  ui_story_5037_50370901_11_dialog_content = "겸사겸사 최신 발매 게임도 하나 가져왔는데, 어때? 패배자~ 나랑 한 번 붙어 볼래?",
  ui_story_5037_50370901_12_dialog_content = "당연히...!",
  ui_story_5037_50370901_13_dialog_content = "으, 역시 그만둘래.",
  ui_story_5037_50370901_14_dialog_content = "어? 웬일이야? 나한테 도전 안 할 거야?",
  ui_story_5037_50370901_15_dialog_content = "오후에도 해야 할 일이 많거든. 게임을 했다간 시간 모르고 놀아 버릴 거야.",
  ui_story_5037_50370901_16_dialog_content = "그렇긴 하네! 그럼 일하는 거 방해 안 해야겠네.",
  ui_story_5037_50370901_17_dialog_content = "둘 다 힘내~ PlayerName, 골디~",
  ui_story_5037_50370901_18_dialog_content = "콘서트 기대할게!",
  ui_story_5037_50370901_19_dialog_content = "응! 많이 기대해 줘!",
  ui_story_5037_50370901_20_dialog_content = "바이바이~",
  ui_story_5037_50370901_21_dialog_content = "안녕~!",
  ui_story_5037_50370901_22_dialog_content = "좋아! 그럼 나도 이제 오후 업무를 시작해야지.",
  ui_story_5037_50370901_23_dialog_content = "잠깐만, 아직 점심시간인걸? 쉴 때는 일 생각하지 말고 제대로 쉬어 줘야 하는 거야.",
  ui_story_5037_50370901_24_dialog_content = "그렇다곤 해도 심사 콘서트가 하루하루 다가오고 있는걸.",
  ui_story_5037_50370901_25_dialog_content = "때가 가까워질수록 해야 할 일도 점점 더 많아지니까, 어떨 땐 쉬는 시간을 어느 정도는 희생할 수밖에 없어...",
  ui_story_5037_50370901_26_dialog_content = "PlayerName 씨, 요즘 계속 점심시간이랑 밤에도 안 쉬고 일하고 있지?",
  ui_story_5037_50370901_27_dialog_content = "음... 그렇다고 할 수 있겠지...",
  ui_story_5037_50370901_28_dialog_content = "그러면 안 돼!",
  ui_story_5037_50370901_29_dialog_content = "충분히 쉬어 주지 않으면 효율이 떨어지고, 그러면 일을 오랫동안 해 나갈 수 없어!",
  ui_story_5037_50370901_30_dialog_content = "지금까지 쉬는 시간에 일했던 걸 보충하는 의미에서, PlayerName 씨 오늘 오후는 휴가야!",
  ui_story_5037_50370901_31_dialog_content = "가서 구경도 좀 하고, 콧바람도 좀 쐬면서 재충전의 시간을 가져 봐!",
  ui_story_5037_50370901_32_dialog_content = "아니야, 나 진짜 괜찮아. 난 그냥...",
  ui_story_5037_50370901_33_dialog_content = "반박은 안 받아! 이건 건강이랑 업무 효율 두 가지를 다 고려해서 내린 결정이니까.",
  ui_story_5037_50370901_34_dialog_content = "하지만 난 골디의 프로듀서잖아. 내가 없으면 골디는 어떡해?",
  ui_story_5037_50370901_35_dialog_content = "안심해~ 예전엔 내가 직접 날 프로듀스했었거든. 그래서 이 정도는 문제없어.",
  ui_story_5037_50370901_36_dialog_content = "빨리 가서 쉬어~ 내일 아침까진 사무소에 안 돌아와도 돼!",
  ui_story_5037_50370901_37_dialog_content = "<color=#828282>탕!</color>",
  ui_story_5037_50370901_38_dialog_content = "(골디한테 강제로 쫓겨나 버렸네...)",
  ui_story_5037_50370901_39_dialog_content = "(이왕 이렇게 됐으니까 산책 잠깐하고 돌아가서 쉬자.)",
  ui_story_5037_50370901_40_dialog_content = "<color=#828282>몇 분 후, 카페 안</color>",
  ui_story_5037_50370901_41_dialog_content = "주문하시겠어요?",
  ui_story_5037_50370901_42_dialog_content = "먼저 메뉴 좀 볼게요...",
  ui_story_5037_50370901_43_dialog_content = "삼색 케이크?",
  ui_story_5037_50370901_44_dialog_content = "우리 목표는 정해진 기간 안에 세 번의 콘서트를 성공적으로 개최하는 거야.",
  ui_story_5037_50370901_45_dialog_content = "앞으로 2번 남았나...",
  ui_story_5037_50370901_46_dialog_content = "자꾸 일 생각하지 말고 빨리 메뉴나 보자!",
  ui_story_5037_50370901_47_dialog_content = "이런 케이크도 있네? 더블... 케이크?",
  ui_story_5037_50370901_48_dialog_content = "공연이 시작되면 관객은 취향에 따라 두 무대 사이를 자유롭게 다닐 수 있어.",
  ui_story_5037_50370901_49_dialog_content = "그리고 마지막에 더 많은 관객의 발길을 붙잡은 쪽이 승리야.",
  ui_story_5037_50370901_50_dialog_content = "휴, 관객들을 사로잡을 수 있는 더 좋은 방법이 없을까...",
  ui_story_5037_50370901_51_dialog_content = "저 키아로라는 환상동물한테 그런 힘이 있어?",
  ui_story_5037_50370901_52_dialog_content = "나도 키아로처럼 내가 게을러질 때 날 혼내줄 환상동물이 있어야 하나...",
  ui_story_5037_50370901_53_dialog_content = "역시 마음 편히 못 쉬겠어!",
  ui_story_5037_50370901_54_dialog_content = "죄송합니다. 조금 더 고민해 봐야 될 것 같아요. 결정하면 그때 주문할게요.",
  ui_story_5037_50370901_55_dialog_content = "네. 필요하신 거 있으시면 불러 주세요.",
  ui_story_5037_50370901_56_dialog_content = "사무소가 아니라 다른 곳에 있어도 머릿속이 온통 곧 다가올 심사 콘서트 생각밖에 안 나...",
  ui_story_5037_50370901_57_dialog_content = "그리고 골디의 내일 일정을 아직 안 정리했다는 생각만 하면 자꾸 마음이 조급해져.",
  ui_story_5037_50370901_58_dialog_content = "으, 고민이 있으니까 커피고 케이크고 입으로 들어가는지 코로 들어가는지 모르겠네.",
  ui_story_5037_50370901_59_dialog_content = "골디는 지금 트레이닝을 잘하고 있으려나...",
  ui_story_5037_50370901_60_dialog_content = "몰래 가서 조금만 확인해 보는 건 괜찮겠지?",
  ui_story_5037_50370901_61_dialog_content = "<color=#828282>아이돌 사무소 밖</color>",
  ui_story_5037_50370901_62_dialog_content = "연습실 입구에 도착했어. 이쪽 창문이라면 안에서 어떤 일들이 일어나고 있는지\n확인할 수 있겠지.",
  ui_story_5037_50370901_63_dialog_content = "어? 저건 골디잖아? 골디 옆에 있는 사람은...",
  ui_story_5037_50370901_64_dialog_content = "인기 아이돌 골디 씨 맞으시죠? 저는 《움브패치》의 기자입니다.",
  ui_story_5037_50370901_65_dialog_content = "조금 전에 골디 씨가 프로듀서를 사무소 문 바깥으로 떠미는 모습을 봤습니다만.",
  ui_story_5037_50370901_66_dialog_content = "소문에 따르면 프로듀서가 더 이상 골디 씨한테 힘을 빌려주지 않겠다고 해서 두 사람 사이에 불화가 생겼다고 하던데, 그게 사실인가요?",
  ui_story_5037_50370901_67_dialog_content = "저랑 PlayerName 씨는 아무런 문제 없이 순조롭게 협력하고 있어요. 언제나 좋은 친구 사이죠.",
  ui_story_5037_50370901_68_dialog_content = "그렇다면 제가 방금 본 그 장면에 대해서는 어떻게 설명하실 건가요?",
  ui_story_5037_50370901_69_dialog_content = "골디 씨의 프로듀서가 골디 씨의 손에 사무실 밖으로 쫓겨나서, 혼자 거리에 쓸쓸히 서 있었습니다. 제가 봐도 너무나도 딱한 모습으로 말이죠!",
  ui_story_5037_50370901_70_dialog_content = "그건...",
  ui_story_5037_50370901_71_dialog_content = "이런, 계속 끈질기게 달라붙던 그 파파라치잖아!",
  ui_story_5037_50370901_72_dialog_content = "골디는 저 기자를 만난 적이 없어서 어떻게 대처해야 좋을지 모를 거야.\n계속 저렇게 놔뒀다간 저 녀석이 또 자기 멋대로 기사를 내보낼 거야!",
  ui_story_5037_50370901_73_dialog_content = "골디를 도우러 가야 해!",
  ui_story_5037_50370901_74_dialog_content = "그렇게 문밖으로 떠밀어 버리다니, 프로듀서가 얼마나 가련한 몰골이었는지 아십니까? 그럴 게 아니라 최소한...",
  ui_story_5037_50370901_75_dialog_content = "지금 무슨 얘기 중이신 건가요?",
  ui_story_5037_50370901_76_dialog_content = "PlayerName 씨?!",
  ui_story_5037_50370901_77_dialog_content = "다, 당신?!",
  ui_story_5037_50370901_78_dialog_content = "아까 골디와 제 사이가 어떤지 물어보셨죠?",
  ui_story_5037_50370901_79_option_content = "(강하게 부정한다)",
  ui_story_5037_50370901_80_dialog_content = "터무니없는 이야기예요. 저랑 골디는 환상의 콤비니까요.",
  ui_story_5037_50370901_81_option_content = "(열심히 해명한다)",
  ui_story_5037_50370901_82_dialog_content = "우린 손발이 척척 맞게 일하고 있고, 사이도 아주 좋아요.",
  ui_story_5037_50370901_83_dialog_content = "윽!",
  ui_story_5037_50370901_84_dialog_content = "그래요!",
  ui_story_5037_50370901_85_dialog_content = "마음대로 소문을 날조한다면, 이쪽에서도 조치를 취할 거예요!",
  ui_story_5037_50370901_86_dialog_content = "아, 알겠습니다!",
  ui_story_5037_50370901_87_dialog_content = "죄송했습니다. 지금 바로 여기서 떠나죠!",
  ui_story_5037_50370901_88_dialog_content = "휴우... PlayerName 씨, 돌아와 줘서 살았어.",
  ui_story_5037_50370901_89_dialog_content = "나 혼자선 어떤 증거들로 저 녀석한테 반박해야 할지 진짜 감도 안 왔거든.",
  ui_story_5037_50370901_90_dialog_content = "나도 요즘 가십 기자들이 이렇게나 「프로 정신」이 투철할 줄은 몰랐어.",
  ui_story_5037_50370901_91_dialog_content = "오래 자리를 비운 것도 아닌데, 그 순간을 노려서 쪼르르 달려와\n루머를 만들려고 하다니 말이야.",
  ui_story_5037_50370901_92_dialog_content = "그러고 보니까 PlayerName 씨, 쉬고 있었어야 하는 거 아니야?",
  ui_story_5037_50370901_93_dialog_content = "왜 사무소로 다시 돌아온 거야?",
  ui_story_5037_50370901_94_dialog_content = "그게... 다시 돌아온 건...",
  ui_story_5037_50370901_95_dialog_content = "으, 골디가 푹 쉬라고 해 줬지만, 아무리 노력을 해도 제대로 푹 쉬는 데\n집중할 수가 없더라고.",
  ui_story_5037_50370901_96_dialog_content = "솔직히 말하면 곧 다가올 심사 콘서트가 너무 걱정돼.",
  ui_story_5037_50370901_97_dialog_content = "그래서 그 생각만 하면 밥도 물도 통 넘어가질 않아. 쉬는 건 말할 것도 없고.",
  ui_story_5037_50370901_98_dialog_content = "그런 거였구나?",
  ui_story_5037_50370901_99_dialog_content = "그래서 말인데, 심사 콘서트에 합격하고 난 다음에 잘 쉬는 게 차라리 낫지 않을까?",
  ui_story_5037_50370901_100_dialog_content = "음...",
  ui_story_5037_50370901_101_dialog_content = "사실 나도 비슷한 느낌을 받았어.",
  ui_story_5037_50370901_102_dialog_content = "전에 나 혼자서 활동할 때는 저런 가십 기자들도 별문제 없이 대처할 수 있었고,\n가짜 뉴스에 곤란할 일도 없었어.",
  ui_story_5037_50370901_103_dialog_content = "근데 PlayerName 씨랑 파트너가 되고 나서부턴, 점점 당신한테 의지해서 이런 일들을\n부탁하는 데 익숙해져 버렸거든.",
  ui_story_5037_50370901_104_dialog_content = "그래서 지금 다시 저런 사람들을 상대하려니까, 오히려 뭔가 낯설었어.",
  ui_story_5037_50370901_105_dialog_content = "내가 골디 널 약하게 만든 거야...?",
  ui_story_5037_50370901_106_dialog_content = "아니야! PlayerName 씨 덕분에 훨씬 강해졌는걸!",
  ui_story_5037_50370901_107_dialog_content = "우리가 파트너가 된 다음부터, 난 트레이닝에 오롯이 집중할 수 있게 됐고,\n그래서 여러 능력도 빠르게 향상됐어!",
  ui_story_5037_50370901_108_dialog_content = "지금의 난 과거의 나랑은 달라! 골디☆메가진화라구!",
  ui_story_5037_50370901_109_dialog_content = "네가 골디를 방해한 게 아니라서 정말 다행이야!",
  ui_story_5037_50370901_110_dialog_content = "PlayerName 씨는 훌륭한 프로듀서야! 방해라니, 당치도 않아!",
  ui_story_5037_50370901_111_dialog_content = "하지만 휴식도 잊지 말아야 하는데...",
  ui_story_5037_50370901_112_dialog_content = "내 걱정은 마. 많이 바쁘긴 하지만, 잠도 제때 자고 운동도 할 거니까\n아무 문제도 없을 거야!",
  ui_story_5037_50370901_113_dialog_content = "그럼 나도 이번엔 프로듀서의 결정에 따를게!",
  ui_story_5037_50370901_114_dialog_content = "당신을 믿어!",
  ui_story_5037_50371001_1_dialog_content = "드디어 심사 콘서트에 합격했어!",
  ui_story_5037_50371001_2_dialog_content = "정말 잘했어! 이제 드디어 가장 큰 시련이 끝났네!",
  ui_story_5037_50371001_3_dialog_content = "긴장이 풀리니까 피로가 갑자기 확 밀려오기 시작했어...",
  ui_story_5037_50371001_4_dialog_content = "그럼 오늘은 푹 쉬어!",
  ui_story_5037_50371001_5_dialog_content = "응! 이젠 좀 제대로 쉬어 줘야겠어.",
  ui_story_5037_50371001_6_dialog_content = "그럼 뭘 해야 좋으려나?",
  ui_story_5037_50371001_7_dialog_content = "그렇지! PlayerName 씨, 내가 노래 불러 줄까?",
  ui_story_5037_50371001_8_dialog_content = "앞으로 있을 「졸업 콘서트」를 위해 신곡을 준비했거든!",
  ui_story_5037_50371001_9_dialog_content = "후렴 부분은 아직 다 못 썼지만, 나머지 부분들은 문제없어.",
  ui_story_5037_50371001_10_dialog_content = "좋지! 골디의 신곡이라면 분명 좋은 노래일 거야.",
  ui_story_5037_50371001_11_dialog_content = "그럼 부를게!",
  ui_story_5037_50371001_12_dialog_content = "♪잠깐의 헤어짐은 괜찮아",
  ui_story_5037_50371001_13_dialog_content = "♪멀리 떨어져 있는 우리 사이를, 같은 별 하나가 빛내주고 있어",
  ui_story_5037_50371001_14_dialog_content = "♪아직은 슬퍼하지 마, 미래가 아직 우릴 기다리고 있어",
  ui_story_5037_50371001_15_dialog_content = "♪안녕은, 작별이 아닌 다시 만나자는 약속이야",
  ui_story_5037_50371001_16_dialog_content = "(정말 좋네...)",
  ui_story_5037_50371001_17_dialog_content = "(그렇지만 가사는 이별을 다루고 있어. 이 선율도 골디가 전에 불렀던 곡들에 비하면 훨씬 부드러운 편이고.)",
  ui_story_5037_50371001_18_dialog_content = "PlayerName 씨, 어땠어?",
  ui_story_5037_50371001_19_option_content = "정말 좋은 노래였어!",
  ui_story_5037_50371001_20_dialog_content = "칭찬해 줘서 고마워!",
  ui_story_5037_50371001_21_option_content = "곡 스타일이 전이랑 좀 달라졌네?",
  ui_story_5037_50371001_22_dialog_content = "어머? 역시 알아차렸구나?",
  ui_story_5037_50371001_23_dialog_content = "「졸업 콘서트」를 위해 준비한 곡이니까, 감격스럽단 느낌을 가득가득 담아 적어야 하니까 그런 거야!",
  ui_story_5037_50371001_24_dialog_content = "하지만 이 노래엔 그 느낌 말고, 다른 느낌도 느껴지는걸?",
  ui_story_5037_50371001_25_dialog_content = "감격스럽다기보단 슬픔이나 아쉬움 같은 그런 느낌? 나도 확실히는 모르겠지만...",
  ui_story_5037_50371001_26_dialog_content = "이건 작별에 관한 노래니까 당연한 거야.",
  ui_story_5037_50371001_27_dialog_content = "작별? 누구와 작별하는 건데?",
  ui_story_5037_50371001_28_dialog_content = "사실 난 지금도 「졸업 콘서트」의 「졸업」은 대체 뭘 얘기하는 건지 잘 모르겠거든.",
  ui_story_5037_50371001_29_dialog_content = "졸업이란 건, 아이돌 사무소에서 나와서 아이돌을 그만하겠단 의미야.",
  ui_story_5037_50371001_30_dialog_content = "그래서 졸업 콘서트는 팬들이랑 작별하는 콘서트인 거지.",
  ui_story_5037_50371001_31_dialog_content = "뭐?!",
  ui_story_5037_50371001_32_dialog_content = "그렇다는 건 결국 골디는 이번 콘서트가 끝나고 나면 아이돌을 그만둔다는 거잖아?",
  ui_story_5037_50371001_33_dialog_content = "그렇게 일찍 그만두진 않을 거야. 내 아이돌 여정은 아직 한참 남았다구!",
  ui_story_5037_50371001_34_dialog_content = "이건 진짜 「졸업 콘서트」가 아니라, 홍보 영상을 찍기 위해 특별히 붙인\n설정일 뿐이야!",
  ui_story_5037_50371001_35_dialog_content = "새내기 프로듀서인 PlayerName 씨한테 한 아이돌의 데뷔부터 졸업까지 함께한다는 게 어떤 느낌인지 체험시켜 주는 거지!",
  ui_story_5037_50371001_36_dialog_content = "난 앞으로도 계속 아이돌을 할 거야!",
  ui_story_5037_50371001_37_dialog_content = "깜짝 놀랐잖아...",
  ui_story_5037_50371001_38_dialog_content = "난 골디 네가 진짜로 더는 아이돌을 안 하려고 하는 줄 알았어.",
  ui_story_5037_50371001_39_dialog_content = "그럴 리가 없잖아!",
  ui_story_5037_50371001_40_dialog_content = "지금의 나한테 졸업 콘서트는 마무리를 짓는다는 의미가 있는 그런 콘서트야.",
  ui_story_5037_50371001_41_dialog_content = "지금까지 PlayerName 씨랑 함께 겪은 일들이랑 실력이 향상된 이번 경험에 마침표를 찍는 느낌인 거지!",
  ui_story_5037_50371001_42_dialog_content = "그랬구나.",
  ui_story_5037_50371001_43_dialog_content = "아이돌이 아닌 골디의 모습은 뭔가 상상이 안 돼...",
  ui_story_5037_50371001_44_dialog_content = "내 마음속의 골디는 이제 완벽히 「아이돌」로 각인돼 버렸거든.",
  ui_story_5037_50371001_45_dialog_content = "PlayerName 씨가 그렇게 얘기해 주니까 정말 기뻐!",
  ui_story_5037_50371001_46_dialog_content = "그건 내가 아이돌이라는 이미지가 당신 마음속에 콕 저장됐다는 거니까!",
  ui_story_5037_50371001_47_dialog_content = "하지만 그래도 「아이돌」이란 신분을 한 꺼풀 벗기면, 나도 그냥 평범한 사람이야.",
  ui_story_5037_50371001_48_dialog_content = "언젠가는 진짜 「졸업 콘서트」를 통해 아이돌 생활과 팬들에게 작별을 고하게 되겠지.",
  ui_story_5037_50371001_49_dialog_content = "그렇게 슬픈 이야기는 그만하자...",
  ui_story_5037_50371001_50_dialog_content = "슬퍼? 난 괜찮은데.",
  ui_story_5037_50371001_51_dialog_content = "뭐?",
  ui_story_5037_50371001_52_dialog_content = "아이돌이라면 누구든 반드시 겪게 되는 일인걸. 지금 생각하지 않는다고 해도,\n결국에는 마주하게 되는 일이야.",
  ui_story_5037_50371001_53_dialog_content = "난 그런 결말에서 도망치기보다는, 어떻게 하면 언젠가는 마주하게 될 진짜\n「졸업 콘서트」를 제대로 치를 수 있을지 열심히 생각해 볼 거야!",
  ui_story_5037_50371001_54_dialog_content = "어떻게 하면 나 자신과 팬들에게 후회가 남지 않을지.",
  ui_story_5037_50371001_55_dialog_content = "어떻게 하면 나 자신이 팬들의 마음속에 영원히 가장 찬란하고,\n마지막까지 함께할 빛으로 남을 수 있는지 말이야.",
  ui_story_5037_50371001_56_dialog_content = "난 데뷔부터 지금까지 쭉 그걸 위해 노력해 왔어!",
  ui_story_5037_50371001_57_dialog_content = "역시 골디야!",
  ui_story_5037_50371001_58_dialog_content = "그럼 골디 넌 나중에 아이돌을 그만두게 되면, 그 뒤엔 뭘 할 거야?",
  ui_story_5037_50371001_59_dialog_content = "음... 그건 아직 생각 중이야!",
  ui_story_5037_50371001_60_dialog_content = "여러 가지 아이디어가 많거든. 근데 가장 하고 싶은 건 역시 애완동물 카페야!",
  ui_story_5037_50371001_61_dialog_content = "거기라면 일하면서도 마시멜로랑 같이 있을 수 있으니까,\n마시멜로도 외로워하지 않을 거구!",
  ui_story_5037_50371001_62_dialog_content = "그거 진짜 좋은 생각이네!",
  ui_story_5037_50371001_63_dialog_content = "작은 동물들이랑 같이 놀면서 커피도 마시면 정말 행복할 거야.",
  ui_story_5037_50371001_64_dialog_content = "나도 그렇게 생각해!",
  ui_story_5037_50371001_65_dialog_content = "매번 피곤해질 때마다 마시멜로의 부드러운 털을 쓰다듬으면 마음이 무척 편안해져.",
  ui_story_5037_50371001_66_dialog_content = "아이돌이 노래랑 춤으로 모두를 즐겁게 만들어 주는 존재라면...",
  ui_story_5037_50371001_67_dialog_content = "애완동물 카페를 여는 건 작은 동물들이랑 같이 모두에게 따스함과 행복을\n선사하는 일인 거지!",
  ui_story_5037_50371001_68_dialog_content = "어느 쪽이든, 난 다 마음에 들어!",
  ui_story_5037_50371101_1_dialog_content = "(오늘 사무소에서 난 비크 씨가 내게 보낸 편지를 하나 발견했다.)",
  ui_story_5037_50371101_2_dialog_content = "(물어볼 게 있으니 댄스 연습실에서 나 혼자 기다리고 있으라고 쓰여 있었다.)",
  ui_story_5037_50371101_3_dialog_content = "역시 왔구나!",
  ui_story_5037_50371101_4_dialog_content = "어? 이 목소리는 피아 목소린데?",
  ui_story_5037_50371101_5_dialog_content = "아야... 아야야야... 피아, 좀 천천히 가. 내 귀 좀 그만 잡아당겨!",
  ui_story_5037_50371101_6_dialog_content = "둘이 지금 뭐 하는 거야?",
  ui_story_5037_50371101_7_dialog_content = "난 피아한테 분명히 하지 말라고 말했어.",
  ui_story_5037_50371101_8_dialog_content = "PlayerName하고 사부가 친구 사이긴 하지만,\n이런 건 확실히 짚고 넘어가야 하는 거야!",
  ui_story_5037_50371101_9_dialog_content = "저기, 그러니까 대체 무슨 일이냐니까?",
  ui_story_5037_50371101_10_dialog_content = "PlayerName, 맨날 여기 오는 가십 기자 말인데, 대체 뭐야?",
  ui_story_5037_50371101_11_dialog_content = "가십 기자?",
  ui_story_5037_50371101_12_dialog_content = "아, 덥수룩한 수염에 딱 봐도 바르고 정직한 사람은 아닐 것 같은\n그 아저씨 말하는 거야?",
  ui_story_5037_50371101_13_dialog_content = "맞아, 역시 알고 있었구나!",
  ui_story_5037_50371101_14_dialog_content = "녀석이 매일 연습실에 드나들면서 허접 사부가 연습하는 걸 방해하고 있어.",
  ui_story_5037_50371101_15_dialog_content = "그리고 녀석이 매번 사부를 꼬드겨서 데리고 가고 나면, 그다음 날엔 꼭 허접 사부를\n깎아내리고 골디를 칭찬하는 기사가 나온다구!",
  ui_story_5037_50371101_16_dialog_content = "네가 그 녀석을 우리 쪽에 보낸 거야?",
  ui_story_5037_50371101_17_dialog_content = "그럴 리가 없잖아...",
  ui_story_5037_50371101_18_dialog_content = "나도 골디랑 맨날 그 녀석 때문에 짜증 나 죽겠는데!",
  ui_story_5037_50371101_19_dialog_content = "그래?",
  ui_story_5037_50371101_20_dialog_content = "휴, 그러니까 내가 아니라고 했잖아.",
  ui_story_5037_50371101_21_dialog_content = "그 신문에는 날 깎아내리는 기사 말고도 골디 씨에 대한 험담도 실려 있었다니까.",
  ui_story_5037_50371101_22_dialog_content = "그, 그래?",
  ui_story_5037_50371101_23_dialog_content = "난 맨날 허접 사부 기사만 제대로 봐서...",
  ui_story_5037_50371101_24_dialog_content = "그러고 보니까 골디를 비방하는 기사 말고, 비크 씨를 비방하는 기사도\n본 적 있는 것 같긴 해.",
  ui_story_5037_50371101_25_dialog_content = "근데 너네가 아니면 대체 누가 그 가십 기자를 보낸 거지?",
  ui_story_5037_50371101_26_dialog_content = "그냥 그 사람 혼자 기삿거리가 있겠다 싶어서 접근한 거겠지.",
  ui_story_5037_50371101_27_dialog_content = "그래서 난 사무소에서 나올 때마다 연습실 문을 제대로 잠가 두는데,\n대체 어디로 어떻게 들어오는 건지 기어코 들어오더라고.",
  ui_story_5037_50371101_28_dialog_content = "진짜 귀찮아 죽겠어!",
  ui_story_5037_50371101_29_dialog_content = "맞아, 맞아! 게다가 우린 녀석 때문에 팬도 잃었다구!",
  ui_story_5037_50371101_30_dialog_content = "아무튼 내가 오해한 거였구나...",
  ui_story_5037_50371101_31_dialog_content = "미안해.",
  ui_story_5037_50371101_32_dialog_content = "괜찮아, 신경 쓰지 마. 그럼 이거 말고 나한테 다른 볼일도 있어?",
  ui_story_5037_50371101_33_dialog_content = "없어. 이제 허접 사부를 데리고 돌아가서 트레이닝시켜야지.",
  ui_story_5037_50371101_34_dialog_content = "너희도 힘내.",
  ui_story_5037_50371101_35_dialog_content = "응! 그럼...",
  ui_story_5037_50371101_36_dialog_content = "<size=45>잠깐만!</size>",
  ui_story_5037_50371101_37_dialog_content = "어? 또 왜 그래?",
  ui_story_5037_50371101_38_dialog_content = "솔직히 말하면, PlayerName한테 물어보고 싶은 게 하나 더 있어.",
  ui_story_5037_50371101_39_dialog_content = "뭐, 뭔데?",
  ui_story_5037_50371101_40_dialog_content = "그 가십 기자를 어떻게 대처하면 좋을지 가르쳐 줘!",
  ui_story_5037_50371101_41_dialog_content = "으앗?! 갑자기 달라붙지 마! 멀리 떨어져!",
  ui_story_5037_50371101_42_dialog_content = "내 머리띠로 눈물 닦지 마!",
  ui_story_5037_50371101_43_dialog_content = "흑흑...",
  ui_story_5037_50371101_44_dialog_content = "그 가십 기자가 매번 내 가짜 뉴스를 내보내는 바람에, 내 팬들이 다 떨어져 나갔어.",
  ui_story_5037_50371101_45_dialog_content = "난 팬을 잃은 만큼 죽어라 열심히 트레이닝하고, 더 열심히 아이돌 활동을\n할 수밖에 없어.",
  ui_story_5037_50371101_46_dialog_content = "게다가 피아가 매번 내가 잘 트레이닝 받고 있는지 감시하면서,\n농땡이 부릴 시간을 조금도 안 줘.",
  ui_story_5037_50371101_47_dialog_content = "저번엔 조금 쉬고 싶어 하니까 키아로한테 내 다리를 물라고 했다니까!",
  ui_story_5037_50371101_48_dialog_content = "키아로가 물어서 다리가 상처투성이가 돼 버렸어.\n흑흑, PlayerName... 나 좀 도와줘...",
  ui_story_5037_50371101_49_dialog_content = "그래, 알겠어. 가르쳐 줄게, 가르쳐 주면 되잖아!",
  ui_story_5037_50371101_50_dialog_content = "역시 PlayerName 너라면 날 그냥 내버려 두지 않을 줄 알았어!",
  ui_story_5037_50371101_51_dialog_content = "어디서부터 시작해야 하려나...",
  ui_story_5037_50371101_52_dialog_content = "일단 이번 《움브패치》에 기사가 뭐라고 실렸는지부터 보자...",
  ui_story_5037_50371101_53_dialog_content = "「비크는 자신이 영원한 18세라고 밝힌 바 있으나,\n실제 나이는 그보다 훨씬 많다」?!",
  ui_story_5037_50371101_54_dialog_content = "윽, 이거 뭔가 비크 씨가 했던 말 같은데.",
  ui_story_5037_50371101_55_dialog_content = "그때 말하는 거지? 아직 기억나! 확실히 그런 얘길 했었지.",
  ui_story_5037_50371101_56_dialog_content = "딱 들어도 뻥 같잖아!",
  ui_story_5037_50371101_57_dialog_content = "내 나이는 비밀이야~",
  ui_story_5037_50371101_58_dialog_content = "그래, 그럼 다음부터는 밝힐 수 없는 비밀이라고만 얘기해 주면 돼.",
  ui_story_5037_50371101_59_dialog_content = "근데 그 기사엔 「비크는 자신이 인기 아이돌 골디보다 더 젊고\n활력 넘친다고 여긴다.」고 적혀 있던데!",
  ui_story_5037_50371101_60_dialog_content = "어? 그건 내가 한 소리 아니야! 그건 그 기자가 나한테 아부할 때 자기가 했던 말이야.",
  ui_story_5037_50371101_61_dialog_content = "그래서 뭐라고 대답했는데?",
  ui_story_5037_50371101_62_dialog_content = "날 띄워 주는 말이니까 당연히 그렇다고 했지!",
  ui_story_5037_50371101_63_dialog_content = "그 기자가 얘기하는 대로 끌려가면 그 녀석한테 기삿거릴 던져주는 거밖에 더 돼?",
  ui_story_5037_50371101_64_dialog_content = "그, 그럼 뭐라고 대답해야 하는데?",
  ui_story_5037_50371101_65_dialog_content = "그건 비크 씨가 잘난척하는 사람이란 기사를 내려고 올가미를 던진 거라고.",
  ui_story_5037_50371101_66_dialog_content = "그러니까 다음에 비슷한 상황이 생기면 겸손하게 답해야 해. 자기보다 다른 사람이 더 훌륭하다고 해야 그 가십 기자가 수작을 부릴 여지가 없는 거라고!",
  ui_story_5037_50371101_67_dialog_content = "오케이, 알겠어. 다음부턴 조심할게!",
  ui_story_5037_50371101_68_dialog_content = "계속 읽어 볼까...",
  ui_story_5037_50371101_69_dialog_content = "「비크의 프로듀서는 위험한 야생동물로 무력한 기자를 협박했다.」?!",
  ui_story_5037_50371101_70_dialog_content = "피아, 이거 너지?",
  ui_story_5037_50371101_71_dialog_content = "왜, 왜 그런 눈으로 보는 거야?",
  ui_story_5037_50371101_72_dialog_content = "그냥 그 녀석이 너무 짜증 나서 키아로한테 물고 가서 길가에 던져 버리라고\n했던 것뿐인데!",
  ui_story_5037_50371101_73_dialog_content = "다음엔 그러면 안 돼.",
  ui_story_5037_50371101_74_dialog_content = "기자가 아무리 짜증 나게 군다고 해도, 그 사람들한테 폭력을 쓰면 안 되는 거야.",
  ui_story_5037_50371101_75_dialog_content = "그렇게 하면 녀석들 좋은 일만 시키는 거야. 그걸 꼬투리 삼아 기사를 쓸 테니까.",
  ui_story_5037_50371101_76_dialog_content = "그럼 녀석들을 어떻게 대처해야 하는데?",
  ui_story_5037_50371101_77_dialog_content = "쫓아내도 안 가, 막아 보려고 해도 자꾸 기어들어 와.\n밖에 있는 모기들보다 짜증 나는 녀석들이라니까!",
  ui_story_5037_50371101_78_dialog_content = "그럴 땐 인터뷰는 받지 않겠다고 예의를 갖춰서 계속 거절해 버리면 그만이야.",
  ui_story_5037_50371101_79_dialog_content = "그렇게 하면 비크 씨를 헐뜯는 기사를 냈다고 하더라도 확실한 증거가 없으니까\n신빙성이 없어 보일 거야.",
  ui_story_5037_50371101_80_dialog_content = "그리고 비크 씨 자신도 실력을 확실히 길러야 해.\n실력이 확실하면 비크 씨한테 흠집을 내려고 해도 어쩔 방법이 없을 테니까.",
  ui_story_5037_50371101_81_dialog_content = "좋아, 알겠어.",
  ui_story_5037_50371101_82_dialog_content = "고마워, PlayerName. 덕분에 살았어.",
  ui_story_5037_50371101_83_dialog_content = "괜찮아. 지금 잠깐은 라이벌이지만, 우린 결국 친구잖아.",
  ui_story_5037_50371101_84_dialog_content = "그러니까 시합이란 작은 일 때문에 내 친구들이 곤경에 빠지도록 두진 않을 거야!",
  ui_story_5037_50371101_85_dialog_content = "흑흑... 넌 역시 사람이 너무 좋아!",
  ui_story_5037_50371101_86_dialog_content = "PlayerName, 이번엔 진짜 고마워...",
  ui_story_5037_50371101_87_dialog_content = "아이돌 겸 환상동물 마스터로서 나도 네가 도와준 보람이 있게 행동할게!",
  ui_story_5037_50371101_88_dialog_content = "이건 피아가 전에 프로듀서가 되는 법을 연구한다고 했을 때 찾아낸 책들인데,\n아마 도움이 될 거야.",
  ui_story_5037_50371101_89_dialog_content = "도와준 보답이라고 생각하고 하나 골라 봐.",
  ui_story_5037_50371101_90_dialog_content = "그거 내 책 아니야? 어디 갔나 했더니 사부가 옷 속에 숨겨 뒀던 거구나!\n어쩐지 찾아도 없더라!",
  ui_story_5037_50371101_91_dialog_content = "그치만 나한텐 이제 필요 없으니까, PlayerName 네 마음껏 골라 봐.",
  ui_story_5037_50371101_92_dialog_content = "고마워, 그럼 이걸로 할게!",
  ui_story_5037_50371101_93_option_content = "《한 권으로 끝내는 신인 아이돌 육성법》",
  ui_story_5037_50371101_94_option_content = "《프로페셔널한 프로듀서의 자기 관리법》",
  ui_story_5037_50371101_95_dialog_content = "좋아, 그럼 우린 가 볼게!",
  ui_story_5037_50371101_96_dialog_content = "가자, 허접 사부. 가서 계속 트레이닝해야지!",
  ui_story_5037_50371101_97_dialog_content = "뭐?! 또, 또 해야 돼?!",
  ui_story_5037_50371101_98_dialog_content = "당연하지, 이제부터 아까 PlayerName하고 얘기하는 데 쓴 시간을\n만회해야 하니까.",
  ui_story_5037_50371101_99_dialog_content = "좀 살려줘어어어어...",
  ui_story_5037_50371201_1_dialog_content = "심사 콘서트를 준비하는 중요한 기간인데, 나보고 여기서 기다리라고 하질 않나...",
  ui_story_5037_50371201_2_dialog_content = "게다가 피아한테는 비밀로 하고 혼자서 몰래 오라니!",
  ui_story_5037_50371201_3_dialog_content = "대체 비크 씨는 무슨 꿍꿍이지?",
  ui_story_5037_50371201_4_dialog_content = "아~ 역시 PlayerName 넌 시간을 잘 지키는 사람이라니까!",
  ui_story_5037_50371201_5_dialog_content = "비크 씨, 왜 날 불러낸 거야? 뭘 꾸미고 있는 건데?",
  ui_story_5037_50371201_6_dialog_content = "딱히 급한 일이 있는 건 아니고...",
  ui_story_5037_50371201_7_dialog_content = "딱 하루만 날 여기 숨겨 줘!",
  ui_story_5037_50371201_8_dialog_content = "하아...?!",
  ui_story_5037_50371201_9_dialog_content = "이제 곧 심사 콘서트 날인데, 트레이닝 안 하고 여기 숨어서 뭐 하려고 하는데?",
  ui_story_5037_50371201_10_dialog_content = "그 트레이닝이 바로 문제야. 일단 내 하루 스케줄부터 들어 봐...",
  ui_story_5037_50371201_11_dialog_content = "매일 아침 해가 뜨기도 전부터 피아가 트레이닝을 해야 한다고 깨워.",
  ui_story_5037_50371201_12_dialog_content = "허접 사부! 트레이닝해야 하니까 빨리 일어나!",
  ui_story_5037_50371201_13_dialog_content = "우선 숲 전체를 10바퀴 돌아! 체력을 길러야 하니까!",
  ui_story_5037_50371201_14_dialog_content = "졸려... 잠이 쏟아져... 하아암...",
  ui_story_5037_50371201_15_dialog_content = "조금만 더 자면 안 될까...",
  ui_story_5037_50371201_16_dialog_content = "안 일어나시겠다? 그러시든가. 키아로! 물어!",
  ui_story_5037_50371201_17_dialog_content = "루──!",
  ui_story_5037_50371201_18_dialog_content = "으아아악!",
  ui_story_5037_50371201_19_dialog_content = "무, 물지 마! 지금 당장 일어날게!",
  ui_story_5037_50371201_20_dialog_content = "달리기하고 나면 세수하고 아침 식사 시간이야.",
  ui_story_5037_50371201_21_dialog_content = "오늘의 아침 식사 메뉴는 톱밥 빵이랑 우유, 그리고 물에 데친 당근이야!",
  ui_story_5037_50371201_22_dialog_content = "3일 내내 물에 데친 당근만 먹었는데, 다른 걸로 좀 바꿔 주면 안 될까...",
  ui_story_5037_50371201_23_dialog_content = "매운 소스를 발라 구워서 기름이 자르르한 샌드버그 꼬치구이 같은 거 있잖아.",
  ui_story_5037_50371201_24_dialog_content = "사부는 지금 아이돌이야. 아이돌이라면 몸매를 관리해야 하는 거구!\n점심이랑 저녁 식사도 물에 데친 당근이니까 그렇게 알아!",
  ui_story_5037_50371201_25_dialog_content = "으흑!",
  ui_story_5037_50371201_26_dialog_content = "그리고...",
  ui_story_5037_50371201_27_dialog_content = "비크 씨가 얼마나 끔찍한 상황인지 충분히 상상이 가...",
  ui_story_5037_50371201_28_dialog_content = "그러니까 내 안전을 위해서라도 내가 좀 쉴 수 있게 하루만 여기 숨겨 줘, PlayerName!",
  ui_story_5037_50371201_29_dialog_content = "딱 하루만 숨겨 주면 돼. 지금 같은 생활은 오로리안이 할 게 아냐!",
  ui_story_5037_50371201_30_dialog_content = "이대로 가다간 세상은 위대한 환상동물 마스터 한 명을 잃게 될 거야!",
  ui_story_5037_50371201_31_dialog_content = "비크 씨... 휴...",
  ui_story_5037_50371201_32_dialog_content = "피아가 비크 씨를 심사에 통과하게 만들어 주려고 굉장히 노력하고 있단 건 알겠는데, 트레이닝 방법이 좀 너무 엄격하긴 하네.",
  ui_story_5037_50371201_33_dialog_content = "여기서 쉴 수 있게 해 줄게. 대신 조건 두 개 있어...",
  ui_story_5037_50371201_34_dialog_content = "하나는 다 쉬고 나면 피아가 걱정하지 않게 바로 돌아가는 거.",
  ui_story_5037_50371201_35_dialog_content = "그리고 피아한테 트레이닝에서 견디기 힘든 점들을 제대로 얘기해 주는 거.",
  ui_story_5037_50371201_36_dialog_content = "그럴게! 내가 하루만 게으름... 아니, 쉴 수 있게 해 주면 그 어떤 조건이라도\n다 받아들일게!",
  ui_story_5037_50371201_37_dialog_content = "그럼 푹 쉬어. 난 이따 골디의 오늘 스케줄을 봐 주러 가야 하니까,\n비크 씨한텐 신경 못 쓸 거야.",
  ui_story_5037_50371201_38_dialog_content = "알겠어. 가서 볼일 봐. 나 혼자서도 문제없어!",
  ui_story_5037_50371201_39_dialog_content = "이 소파가 놓겠네. 잠자기 딱 좋겠어.",
  ui_story_5037_50371201_40_dialog_content = "타래야~ 잠깐 껴안고 자고 싶으니까 좀 크게 변해 줘~",
  ui_story_5037_50371201_41_dialog_content = "뀨우!",
  ui_story_5037_50371201_42_dialog_content = "Zzz... Zzz...",
  ui_story_5037_50371201_43_dialog_content = "(벌써 잠들어 버렸네. 역시 비크 씨야...)",
  ui_story_5037_50371201_44_dialog_content = "(그럼 나도 이제 마저 할 일을 해야지.)",
  ui_story_5037_50371201_45_dialog_content = "<color=#828282>얼마 후</color>",
  ui_story_5037_50371201_46_dialog_content = "(스케줄은 거의 다 짰네. 이 일에도 점점 능숙해지고 있는걸!)",
  ui_story_5037_50371201_47_dialog_content = "<color=#828282>똑똑똑!</color>",
  ui_story_5037_50371201_48_dialog_content = "(어? 노크 소리인가?)",
  ui_story_5037_50371201_49_dialog_content = "누구세요?",
  ui_story_5037_50371201_50_dialog_content = "PlayerName, 나야, 피아!",
  ui_story_5037_50371201_51_dialog_content = "(피아?!)",
  ui_story_5037_50371201_52_dialog_content = "(잠깐만! 비크 씨가 아직 여기 있는데?!)",
  ui_story_5037_50371201_53_dialog_content = "<color=#828282>똑똑똑!</color>",
  ui_story_5037_50371201_54_dialog_content = "PlayerName?",
  ui_story_5037_50371201_55_dialog_content = "금방 열어 줄게! 잠깐만 기다려!",
  ui_story_5037_50371201_56_dialog_content = "비크 씨! 빨리 일어나!",
  ui_story_5037_50371201_57_dialog_content = "하...암, 타래야, 하하, 장난 그만해...",
  ui_story_5037_50371201_58_dialog_content = "나보다 더 깊게 자는 사람이 여기 있었네?!",
  ui_story_5037_50371201_59_dialog_content = "(어쩔 수 없지. 일단 숨겨 두는 수밖에.)",
  ui_story_5037_50371201_60_dialog_content = "(어디 보자... 여기 잡지 더미 쪽이 좋겠어. 여기다 숨기자!)",
  ui_story_5037_50371201_61_dialog_content = "지금 갈게, 피아! 잠깐만!",
  ui_story_5037_50371201_62_dialog_content = "왜 이렇게 늦었어?",
  ui_story_5037_50371201_63_dialog_content = "미안, 미안. 그게 아까... 방을 치우고 있었거든!",
  ui_story_5037_50371201_64_dialog_content = "잡지도 산더미처럼 쌓여 있고 완전 난장판이네. 확실히 제대로 치우긴 해야겠어.",
  ui_story_5037_50371201_65_dialog_content = "아하하... 근데 피아, 무슨 일로 온 거야?",
  ui_story_5037_50371201_66_dialog_content = "우리 사부 못 봤어?",
  ui_story_5037_50371201_67_dialog_content = "아... 어? 모, 못 봤어.",
  ui_story_5037_50371201_68_dialog_content = "흐응?",
  ui_story_5037_50371201_69_dialog_content = "계속 여기서 물건 치우고, 골디 스케줄 짜느라 바빠서 비크 씨는 못 봤어.",
  ui_story_5037_50371201_70_dialog_content = "아, 그래. 사부라면 널 찾아올 줄 알았는데 아니었구나. 이상하네~",
  ui_story_5037_50371201_71_dialog_content = "허접 사부가 대체 어디로 도망쳐 버린 거야...",
  ui_story_5037_50371201_72_dialog_content = "그냥 잠깐 농땡이 부리고 있는 걸지도 몰라. 조금 있으면 돌아오겠지.",
  ui_story_5037_50371201_73_dialog_content = "심사 콘서트도 며칠 안 남았는데, 어떻게 아직도 농땡이 부릴 여유가 있는 거지?",
  ui_story_5037_50371201_74_dialog_content = "이따 돌아오면 제대로 트레이닝시켜 줘야겠어.",
  ui_story_5037_50371201_75_dialog_content = "트레이닝이 너무 힘들어서 없어져 버린 걸 수도 있지 않을까?",
  ui_story_5037_50371201_76_dialog_content = "피아의 트레이닝은 언제나 엄격하잖아? 그게 나쁘다는 건 아니지만,\n일이랑 휴식의 균형도 잘 고려해 줘야 해.",
  ui_story_5037_50371201_77_dialog_content = "그래?",
  ui_story_5037_50371201_78_dialog_content = "어차피 오늘은 하루 푹 쉬라고 휴가를 주려고 했었는데...",
  ui_story_5037_50371201_79_dialog_content = "어디로 없어져 버리더니, 움브라톤을 다 돌아도 어디 있는지 보이지도 않아.",
  ui_story_5037_50371201_80_dialog_content = "(피아가 비크 씨한테 휴가를 주려고 했었네? 역시 피아도 다 잘 생각해서 트레이닝 계획을 세우는 거였구나.)",
  ui_story_5037_50371201_81_dialog_content = "너무 걱정하지 마, 다른 사람들한테도 비크 씨를 찾아봐 달라고 부탁해 둘게.",
  ui_story_5037_50371201_82_dialog_content = "응, 그럼 난 계속 사부를 찾으러 가 볼게.",
  ui_story_5037_50371201_83_dialog_content = "잠깐만, 이건...",
  ui_story_5037_50371201_84_dialog_content = "(망했다! 피아가 비크 씨를 숨겨 놓은 책더미를 유심히 보고 있어!)",
  ui_story_5037_50371201_85_dialog_content = "아! 그, 그건 내가 보던 잡지들인데 아직 시간이 없어서 다 못 치웠어. 내가 금방...",
  ui_story_5037_50371201_86_dialog_content = "안에 뭐라도 들어 있는 거처럼 잡지 더미가 불룩한데?",
  ui_story_5037_50371201_87_dialog_content = "만지면 안 돼...!",
  ui_story_5037_50371201_88_dialog_content = "허접 사부?!",
  ui_story_5037_50371201_89_dialog_content = "Zzz... Zzz...",
  ui_story_5037_50371201_90_dialog_content = "허접 사부가 왜 여기서 자고 있어?",
  ui_story_5037_50371201_91_dialog_content = "PlayerName, 너 방금 나한테 거짓말한 거야?",
  ui_story_5037_50371201_92_dialog_content = "난... 그게...",
  ui_story_5037_50371201_93_option_content = "(솔직하게 말한다)",
  ui_story_5037_50371201_94_dialog_content = "맞아. 그냥 솔직하게 말할게. 아깐 내가 거짓말한 거야.",
  ui_story_5037_50371201_95_dialog_content = "미안해...",
  ui_story_5037_50371201_96_dialog_content = "괜찮아. PlayerName 네가 일부러 날 속인 게 아니란 거 피아는 다 아니까.",
  ui_story_5037_50371201_97_option_content = "(변명한다)",
  ui_story_5037_50371201_98_dialog_content = "내가 오기 전부터 여기 있었나 봐. 아마 그런 것 같아...",
  ui_story_5037_50371201_99_dialog_content = "딱 봐도 거짓말하는 사람 얼굴이야, PlayerName.",
  ui_story_5037_50371201_100_dialog_content = "근데 피아도 대충 무슨 상황인진 알겠어.",
  ui_story_5037_50371201_101_dialog_content = "뻔해. 허접 사부가 가라고 해도 안 가고 멋대로 여기 눌어붙어 있었던 거지?",
  ui_story_5037_50371201_102_dialog_content = "사실은 말이지...",
  ui_story_5037_50371201_103_dialog_content = "비크 씨가 아침에 날 찾아와서 잠깐 쉬고 싶으니까 여기에 좀 숨겨 주면\n안 되겠냐고 했었어.",
  ui_story_5037_50371201_104_dialog_content = "엄격한 아이돌 트레이닝 때문에 엄청 피곤했던 모양인지, 여기 온 지 얼마 되지도 않아서 곯아떨어져 버리더라고.",
  ui_story_5037_50371201_105_dialog_content = "허접 사부는 차라리 날 속이고 여기로 도망쳐 오는 게, 나한테 힘들다고 설명하는 것보다 나았던 거야...?",
  ui_story_5037_50371201_106_dialog_content = "피아가 쉬는 시간도 따로 준비해 줬는데!",
  ui_story_5037_50371201_107_dialog_content = "비크 씨가 일어나면 다시 천천히 얘기해 보면 어떨까?",
  ui_story_5037_50371201_108_dialog_content = "으... 지금 당장 깨우는 건 그만둘게. 일단은 여기서 계속 쉬게 해 주지 뭐.",
  ui_story_5037_50371201_109_dialog_content = "허접 사부가 일어나면 바로 나한테 와서 계속 트레이닝해야 한다고 알려 줘.",
  ui_story_5037_50371201_110_dialog_content = "허접 사부를 돌봐 줘서 고마우니까, PlayerName한텐 나중에 내가 정리한\n아이돌 트레이닝 팁을 줄게.",
  ui_story_5037_50371201_111_dialog_content = "응, 걱정 마!",
  ui_story_5037_50371201_112_dialog_content = "참! 그리고 하나 더! 허접 사부한텐 내가 여기 왔었다는 거 말하지 마!",
  ui_story_5037_50371201_113_dialog_content = "왜?",
  ui_story_5037_50371201_114_dialog_content = "그건...",
  ui_story_5037_50371201_115_dialog_content = "<size=45>허접 사부는 전혀 믿을 만한 구석이 없으니까!</size>",
  ui_story_5037_50371201_116_dialog_content = "에엥?!",
  ui_story_5037_50371201_117_dialog_content = "이번에 내가 그냥 넘어가 줬단 걸 알게 되면, 앞으로 갈수록 더 이럴 거라구!",
  ui_story_5037_50371201_118_dialog_content = "그렇게 되면 지금까지 자리 잡아 뒀던 생활 습관들도 완전히 망가지고, 트레이닝할 때도 틈만 나면 얼렁뚱땅 넘어가려고 할 거야.",
  ui_story_5037_50371201_119_dialog_content = "이런 사람을 다루는 방법은 인정사정없이 엄격하게 하는 것 딱 하나뿐이야!",
  ui_story_5037_50371201_120_dialog_content = "아, 알겠어!",
  ui_story_5037_50371201_121_dialog_content = "비크 씨가 잠에서 깨면 계속 트레이닝 받으라고 돌려보낼게!",
  ui_story_5037_50371301_1_dialog_content = "하필 이럴 때 이런 문제가 생길 줄은 몰랐네.",
  ui_story_5037_50371301_2_dialog_content = "난 이래도 뭐 괜찮다고 생각해~",
  ui_story_5037_50371301_3_dialog_content = "이 상황이 괜찮다고 생각하는 건 허접 사부 하나밖에 없거든!",
  ui_story_5037_50371301_4_dialog_content = "PlayerName 씨, 상황이 진짜 그렇게 심각해진 거야?",
  ui_story_5037_50371301_5_dialog_content = "그렇다고 볼 수 있어...",
  ui_story_5037_50371301_6_dialog_content = "우린 지금 엄청난 위기와 마주한 거야!",
  ui_story_5037_50371301_7_dialog_content = "아무리 노력해도 골디랑 비크 씨의 능력이 갈수록 더디게 향상되고 있어!",
  ui_story_5037_50371301_8_dialog_content = "그러니까... 「슬럼프」가 찾아온 거야!",
  ui_story_5037_50371301_9_dialog_content = "이 문제를 해결하고, 최고의 컨디션으로 「졸업 콘서트」를 진행할 수 있도록 나랑 피아가 방법을 하나 생각해 봤어!",
  ui_story_5037_50371301_10_dialog_content = "그건 바로... 서로의 프로듀서를 바꿔 보는 거야!",
  ui_story_5037_50371301_11_dialog_content = "뭐어어어?!",
  ui_story_5037_50371301_12_dialog_content = "맞아, PlayerName 네가 허접 사부의 트레이닝을 맡고,\n나랑 골디 언니가 파트너가 되는 거지!",
  ui_story_5037_50371301_13_dialog_content = "그리고 하루 동안 프로듀서를 바꿔서 트레이닝을 진행하는 거야!",
  ui_story_5037_50371301_14_dialog_content = "새로운 트레이닝 방식이랑 파트너라면 새로운 영감을 떠올리기도 좋을 거고, 그럼 슬럼프를 빠르게 이겨낼 수 있을 거야!",
  ui_story_5037_50371301_15_dialog_content = "그러니까 그 얘긴... 내가 비크 씨를 트레이닝시켜야 한다는 거네?",
  ui_story_5037_50371301_16_dialog_content = "어? 그거 나쁘지 않겠는데~ 그럼 나도 한숨 돌리면서 해도 되겠...",
  ui_story_5037_50371301_17_dialog_content = "아프잖아! 피아, 발 좀 그만 밟아!",
  ui_story_5037_50371301_18_dialog_content = "사부가 게으름 피우지 못하게 키아로도 같이 맡길게, PlayerName.",
  ui_story_5037_50371301_19_dialog_content = "루!",
  ui_story_5037_50371301_20_dialog_content = "사부가 게으름을 피우려고 하면 키아로가 제대로 하라고 사부의 다리를 물어 버릴 거야. 그러니까 넌 안심해도 돼.",
  ui_story_5037_50371301_21_dialog_content = "피아는 역시 다 생각이 있구나...",
  ui_story_5037_50371301_22_dialog_content = "그럼, 즐거운 마음으로 한번 해 보자.",
  ui_story_5037_50371301_23_dialog_content = "PlayerName 씨, 평소에 나한테 해 줬던 거처럼 비크 씨도 잘 트레이닝시켜 줘!",
  ui_story_5037_50371301_24_dialog_content = "당신이라면 해낼 수 있을 거라고 믿어!",
  ui_story_5037_50371301_25_dialog_content = "응, 나한테 맡겨.",
  ui_story_5037_50371301_26_dialog_content = "그럼 나랑 골디 언니는 먼저 가 볼게. 바이바이~",
  ui_story_5037_50371301_27_dialog_content = "그럼 우리도 돌아가서 쉬...",
  ui_story_5037_50371301_28_dialog_content = "으아아악!",
  ui_story_5037_50371301_29_dialog_content = "키아로! 이거 놔! 내 다린 먹는 게 아니야!",
  ui_story_5037_50371301_30_dialog_content = "루!",
  ui_story_5037_50371301_31_dialog_content = "비크 씨가 게으름 피우려는 것 같으니까 키아로가 열심히 막은 거겠지.",
  ui_story_5037_50371301_32_dialog_content = "휴... 키아로, 이젠 네 곁에 피아가 있으니까 난 잊은 거니...?",
  ui_story_5037_50371301_33_dialog_content = "이 사부가 널 어렸을 때부터 기르고, 너한테 생존 기술도 알려줬는데...",
  ui_story_5037_50371301_34_dialog_content = "콰득──!",
  ui_story_5037_50371301_35_dialog_content = "그러다 또 키아로한테 물리겠어. 그냥 빨리 트레이닝을 시작하자.",
  ui_story_5037_50371301_36_dialog_content = "흑흑, 왜 다치는 건 맨날 나야...",
  ui_story_5037_50371301_37_dialog_content = "내 트레이닝 방법은 연습이랑 휴식이 적절히 섞여 있으니까 그렇게 힘들진 않을 거야.",
  ui_story_5037_50371301_38_dialog_content = "오늘 할 첫 번째 트레이닝은 보컬 트레이닝이야.",
  ui_story_5037_50371301_39_dialog_content = "<color=#828282>얼마 후</color>",
  ui_story_5037_50371301_40_dialog_content = "♪또다시 찾아온 만물이 소생하는 봄♪",
  ui_story_5037_50371301_41_dialog_content = "♪동물들은 바삐 자신들의 터전을 떠나지♪",
  ui_story_5037_50371301_42_dialog_content = "♪숲이든 저 멀리 있는 황야든♪",
  ui_story_5037_50371301_43_dialog_content = "좋아, 이번 곡까지만 부르고 잠깐 쉬자.",
  ui_story_5037_50371301_44_dialog_content = "좋았어! 드디어 쉴 수 있어!",
  ui_story_5037_50371301_45_dialog_content = "루...",
  ui_story_5037_50371301_46_dialog_content = "이건 게으름 피우는 거 아니야, 키아로. 이건 진짜 쉬는 시간이라고!",
  ui_story_5037_50371301_47_dialog_content = "근데 계속 궁금했었어. 비크 씨는 왜 아이돌이 되려고 하는 거야?",
  ui_story_5037_50371301_48_dialog_content = "음? 그 질문은 처음부터 잘못됐어~",
  ui_story_5037_50371301_49_dialog_content = "엥?",
  ui_story_5037_50371301_50_dialog_content = "왜냐하면 난 환상동물 마스터지 아이돌이 아니거든~",
  ui_story_5037_50371301_51_dialog_content = "그럼 대회엔 왜 참가한 거야?",
  ui_story_5037_50371301_52_dialog_content = "다 나이티움 때문이지!",
  ui_story_5037_50371301_53_dialog_content = "설마 진짜 상금 때문일 줄이야...",
  ui_story_5037_50371301_54_dialog_content = "비크 씨가 계속 넉넉하지 못하게 지내는 것도 알고, 샤엘 씨가 이번에 높은 상금을 건 것도 알겠는데...",
  ui_story_5037_50371301_55_dialog_content = "근데 왜 피아까지 같이 참가한 거야?",
  ui_story_5037_50371301_56_dialog_content = "포스터를 보고 날 잡아다 참가시킨 당사자가 바로 피아거든.",
  ui_story_5037_50371301_57_dialog_content = "환상동물 보호에 들어가는 경비가 부족해져서 말이야...",
  ui_story_5037_50371301_58_dialog_content = "얼마나 부족한데?",
  ui_story_5037_50371301_59_dialog_content = "비카랑 드라코리온의 저번 달 간식 비용도 아직 못 갚았어!",
  ui_story_5037_50371301_60_dialog_content = "상황이 그렇게 안 좋단 말이야?!",
  ui_story_5037_50371301_61_dialog_content = "근데 경제적으로 힘들면 간식을 좀 줄이면 되잖아!",
  ui_story_5037_50371301_62_dialog_content = "어림없는 소리!",
  ui_story_5037_50371301_63_dialog_content = "환상동물은 내 동료들이야. 그러니까 고생시키고 싶진 않은걸~",
  ui_story_5037_50371301_64_dialog_content = "평소엔 피아랑 시라가 연구도 하고 아르바이트도 하면서 돈을 벌어서\n빚질 정도까진 아니었어.",
  ui_story_5037_50371301_65_dialog_content = "근데 저번에 내가 피아한테 어떤 환상동물을 조사하라고 보냈는데, 시간을 엄청 투자했는데도 아무런 성과가 없었거든.",
  ui_story_5037_50371301_66_dialog_content = "결국 수입이 지출을 감당할 수가 없어져서 빚을 엄청 지게 됐지 뭐야!",
  ui_story_5037_50371301_67_dialog_content = "그럼 그 지경이 될 때까지 비크 씨는 뭐 했어?",
  ui_story_5037_50371301_68_dialog_content = "나? 난 당연히 환상동물을 돌보고 잘 쉬었지.",
  ui_story_5037_50371301_69_dialog_content = "그럼 전혀 도움이 안 됐단 거잖아!",
  ui_story_5037_50371301_70_dialog_content = "갑자기 평소에 피아랑 시라가 얼마나 힘들지 알 것 같아...",
  ui_story_5037_50371301_71_dialog_content = "나도 두 제자를 도와서 돈 벌려고 이러고 있는 거거든?\n게다가 무대에 올라가서 공연도 했잖아!",
  ui_story_5037_50371301_72_dialog_content = "심지어 지금까지 고분고분 열심히 노력했는데!",
  ui_story_5037_50371301_73_dialog_content = "그러네. 의외긴 해. 난 비크 씨가 중단에 포기하고 도망쳐 버릴 줄 알았거든.",
  ui_story_5037_50371301_74_dialog_content = "환상동물들의 식비랑 관련된 중요한 일인데 도망칠 리가 없잖아!",
  ui_story_5037_50371301_75_dialog_content = "환상동물을 위해서라면 난 그 어떤 어려움도 두렵지 않아.",
  ui_story_5037_50371301_76_dialog_content = "PlayerName 네가 보수만 충분히 준다면 내가 피아랑 시라도 데리고\n심부름도 해 줄 수 있어!",
  ui_story_5037_50371301_77_dialog_content = "아니 그건 아니지! 피아랑 시라한테 민폐니까 그런 거 하지 마!",
  ui_story_5037_50371301_78_dialog_content = "진짜 영문을 모르겠어. 가끔 보면 비크 씨는 피아랑 시라한테 타레한테 쓰는 신경의\n반의반도 안 쓰는 것 같아.",
  ui_story_5037_50371301_79_dialog_content = "그건 진짜 크나큰 오해야! 그 둘은 내 가장 자랑스러운 제자들인걸!",
  ui_story_5037_50371301_80_dialog_content = "내가 가지고 있는 환상동물 지식을 모두 이어받았고, 자기 앞가림들도 다 잘해.",
  ui_story_5037_50371301_81_dialog_content = "게다가 아주 강해서 암귀랑 마주쳐도 전혀 무서울 게 없잖아~",
  ui_story_5037_50371301_82_dialog_content = "얼마 뒤면 아스트라 대륙 전체의 환상동물 연구 과제를 피아랑 시라한테\n맡길 수 있을지도 모르지.",
  ui_story_5037_50371301_83_dialog_content = "두 사람한테 맡기고 다면 비크 씨는 뭐 할 건데? 자리를 잡고 늘어지게 잘 거야?",
  ui_story_5037_50371301_84_dialog_content = "나쁘지 않은 아이디어야! 참고할게!",
  ui_story_5037_50371301_85_dialog_content = "근데 그 전에 나한텐 아직 해야 할 일들이 남아 있어.",
  ui_story_5037_50371301_86_dialog_content = "이 세상에는 아스트라 대륙 말고도 다른 대륙이 분명히 존재할 거야.",
  ui_story_5037_50371301_87_dialog_content = "난 거기로 가서 더 많은 환상동물을 찾아 녀석들의 특징을 기록으로 남기고,\n연구하고 싶어.",
  ui_story_5037_50371301_88_dialog_content = "생각보다 원대한 이상을 가지고 있었구나...",
  ui_story_5037_50371301_89_dialog_content = "그야 당연하지. 왜냐하면 난...",
  ui_story_5037_50371301_90_dialog_content = "으아아악!",
  ui_story_5037_50371301_91_dialog_content = "키아로, 왜 또 깨무는 거야?!",
  ui_story_5037_50371301_92_dialog_content = "시간을 보니까 휴식 시간이 벌써 지나 버렸어. 그러니까 키아로가 다시 트레이닝을 시작하라고 알려 주는 것 같아!",
  ui_story_5037_50371301_93_dialog_content = "키아로, 너 피아한테 못된 것만 배웠구나! 어떻게 피아보다 더 엄하게 변한 거야?!",
  ui_story_5037_50371301_94_dialog_content = "근데 오늘 내 트레이닝을 담당할 프로듀서는 PlayerName 너니까, 쉬는 시간을 조금만 더 늘려 주면 안 될까?",
  ui_story_5037_50371301_95_dialog_content = "음...",
  ui_story_5037_50371301_96_dialog_content = "하루 동안 타래를 빌려줄 테니까, 마음껏 쓰다듬어도 돼!",
  ui_story_5037_50371301_97_dialog_content = "그렇게까지 말한다면 오늘 트레이닝은...",
  ui_story_5037_50371301_98_option_content = "2배로 갈게!",
  ui_story_5037_50371301_99_option_content = "풀파워로 늘릴게!",
  ui_story_5037_50371301_100_dialog_content = "원래 난 골디가 슬럼프를 이겨낼 수 있는 트레이닝을 준비해 뒀었거든.",
  ui_story_5037_50371301_101_dialog_content = "근데 트레이닝 강도가 너무 높다 보니까 계속 시도를 못 해 봤는데,\n효과가 어떤지 비크 씨한테 테스트해 보면 되겠어!",
  ui_story_5037_50371301_102_dialog_content = "뭐라고오오오?!",
  ui_story_5037_50371301_103_dialog_content = "걱정하지 마. 나중에 골디의 트레이닝 강도를 조절할 때 참고하게 효과만\n확인해 보려는 거니까.",
  ui_story_5037_50371301_104_dialog_content = "물론, 비크 씨의 실력 향상에도 도움이 될 거야.",
  ui_story_5037_50371301_105_dialog_content = "지금까지 피아가 고생해 온 게 헛되지 않게, 최선을 다해 열심히 트레이닝을 받아 줘!",
  ui_story_5037_50371301_106_dialog_content = "싫어어어어어어어!",
  ui_story_5037_50371401_1_dialog_content = "PlayerName 팀의 긴급회의. 3, 2, 1. 액션!",
  ui_story_5037_50371401_2_dialog_content = "이런 것도 찍어야 해?",
  ui_story_5037_50371401_3_dialog_content = "당연하지! 훌륭한 감독은 귀중한 장면을 단 하나도 놓쳐선 안 된다구!",
  ui_story_5037_50371401_4_dialog_content = "알겠어...",
  ui_story_5037_50371401_5_dialog_content = "그럼 제1회 「프로듀서 속성 연구회」 회의를 시작할게.",
  ui_story_5037_50371401_6_dialog_content = "......",
  ui_story_5037_50371401_7_dialog_content = "(사무소의 이쪽 구석은 벌써 책으로 가득 차 버렸네...)",
  ui_story_5037_50371401_8_dialog_content = "(이건 바이스랑 카렌이 가지고 온 책들인가?)",
  ui_story_5037_50371401_9_dialog_content = "(둘 다 표정이 너무 심각한 게 영 불안한데...)",
  ui_story_5037_50371401_10_dialog_content = "둘 다 왜 그렇게 심각해...?",
  ui_story_5037_50371401_11_dialog_content = "이건 PlayerName 네가 성공적으로 프로듀서가 될 수 있는지 없는지가 달린 일이니까,\n진지하게 해야지!",
  ui_story_5037_50371401_12_dialog_content = "맞아. 이것만큼은 결코 소홀히 할 수 없어.",
  ui_story_5037_50371401_13_dialog_content = "사실은 내가 열심히 해야 하는 부분인데, 두 사람이 신경 쓰게 만들어 버렸네...",
  ui_story_5037_50371401_14_dialog_content = "그게 무슨 소리야. 우린 PlayerName의 둘도 없는 단짝이니까, 언제나 네가 하는 일을 응원하고 지지해 줄 거야!",
  ui_story_5037_50371401_15_dialog_content = "네가 최대한 빠르게 「프로듀서」가 해야 하는 일에 대해 이해할 수 있도록, 나와 바이스가 연구를 조금 해 봤어.",
  ui_story_5037_50371401_16_dialog_content = "맞아. 「아이돌」부터 「프로듀서」까지, 모든 관련 자료들은 다 여기 있어!",
  ui_story_5037_50371401_17_dialog_content = "그럼 오늘부턴 바로 여기에서 「프로듀서 속성반」을 진행할 거야!",
  ui_story_5037_50371401_18_dialog_content = "이건... 다 노트랑 스크랩들이네?!",
  ui_story_5037_50371401_19_dialog_content = "응! 카렌이 도서관에 가서 가수랑 댄서 육성에 관련된 책들은 다 뒤져서\n노트로 정리해 왔대.",
  ui_story_5037_50371401_20_dialog_content = "그리고 난 최근 몇 년간 움브라톤에서 발행된 신문을 사서, 거기에 실린 아이돌이랑 프로듀서 기사들을 전부 다 모아 왔어!",
  ui_story_5037_50371401_21_dialog_content = "엄청난데...?!",
  ui_story_5037_50371401_22_dialog_content = "정말 고생했어... 모든 책을 읽어 보고 노트에 정리해 오려면 시간이\n어마어마하게 들었을 텐데...",
  ui_story_5037_50371401_23_dialog_content = "노트 정리할 때, 크로이와 키팅도 지나가다가 보고 와서 도와줬어.",
  ui_story_5037_50371401_24_dialog_content = "다 나보다는 음악 쪽에 대해 더 잘 아니까, 노트를 정리할 때도 많은 도움을 받았지.",
  ui_story_5037_50371401_25_dialog_content = "나도 브랜디 씨한테 도와 달라고 부탁했어.",
  ui_story_5037_50371401_26_dialog_content = "브랜디 씨는 프로 기자니까 여러 뉴스에 대해서 나보다 훨씬 잘 알고 있더라!",
  ui_story_5037_50371401_27_dialog_content = "맞아. 그러니까 지금 이 결과물은 우리 모두가 PlayerName 널 위해 함께 노력했기 때문에 만들어질 수 있었던 거야.",
  ui_story_5037_50371401_28_dialog_content = "그렇구나...",
  ui_story_5037_50371401_29_dialog_content = "반드시, 꼭! 모두의 노력에 보답할게!",
  ui_story_5037_50371401_30_dialog_content = "그럼 이제 본격적으로 회의를 시작해 보자.",
  ui_story_5037_50371401_31_dialog_content = "이번 회의에서 논의해야 할 두 번째 사안은 바로 PlayerName 널 위한\n육성 계획을 정하는 거야!",
  ui_story_5037_50371401_32_dialog_content = "육성 계획?",
  ui_story_5037_50371401_33_dialog_content = "응. 우리가 널 위해서 두 가지 다른 육성 계획을 준비했어. 네가 너한테 잘 맞는 걸로 직접 선택해 줬으면 좋겠어.",
  ui_story_5037_50371401_34_dialog_content = "첫 번째는 「한 방에 끝내는 프로듀서 되기」야.",
  ui_story_5037_50371401_35_dialog_content = "뭐가 그렇게 두꺼워?!",
  ui_story_5037_50371401_36_dialog_content = "여긴 기획과 관련된 기초적인 지식부터 전문적인 팁까지 전부 다 담겨 있어. 그렇지만 내용이 복잡한 편이니까 익히려면 시간이 조금 걸릴 거야.",
  ui_story_5037_50371401_37_dialog_content = "그럼 다른 건?",
  ui_story_5037_50371401_38_dialog_content = "이 계획은 「프로페셔널한 프로듀서의 고급 스킬」이야. 역대 유명 학자들의 시간 관리 팁을 정리해 뒀어.",
  ui_story_5037_50371401_39_dialog_content = "하지만 이 계획은 어느 정도 기초 지식을 가지고 있어야 편하게 이해할 수 있을 거야.",
  ui_story_5037_50371401_40_dialog_content = "PlayerName, 자신의 상황을 고려해서 너한테 잘 맞을 것 같은 계획을 하나 선택해 줘!",
  ui_story_5037_50371401_41_dialog_content = "나한테 맞는 계획이라...",
  ui_story_5037_50371401_42_dialog_content = "아무래도 난 아직 초보 프로듀서니까, 이걸로 할게!",
  ui_story_5037_50371401_43_option_content = "「한 방에 끝내는 프로듀서 되기」",
  ui_story_5037_50371401_44_dialog_content = "기초부터 차근차근 배우려면 이 선택이 가장 안정적일 것 같아!",
  ui_story_5037_50371401_45_dialog_content = "나도 그 관점에 동의해.",
  ui_story_5037_50371401_46_dialog_content = "그럼 지금부터 이 계획으로 어떻게 하면 프로듀서가 될 수 있는지 배워 보자!",
  ui_story_5037_50371401_47_dialog_content = "응! 열심히 할게!",
  ui_story_5037_50371401_48_dialog_content = "<color=#828282>얼마 후</color>",
  ui_story_5037_50371401_49_dialog_content = "프로듀서의 주요 업무... 진척 상황... 기획...",
  ui_story_5037_50371401_50_dialog_content = "그리고 또 뭐가 있더라? 왜 또 잊어버렸지...?",
  ui_story_5037_50371401_51_dialog_content = "좀 쉬어, PlayerName.",
  ui_story_5037_50371401_52_dialog_content = "이미 많은 걸 머릿속에 담아 뒀으니까. 이제부턴 이 지식들을 실전에서 활용하면 돼.",
  ui_story_5037_50371401_53_option_content = "「프로페셔널한 프로듀서의 고급 스킬」",
  ui_story_5037_50371401_54_dialog_content = "이왕 도전하는 거라면 어려운 것부터 시작할래!",
  ui_story_5037_50371401_55_dialog_content = "바로 어려운 것부터 시작하겠다고?!",
  ui_story_5037_50371401_56_dialog_content = "네가 내린 결정이니까, 최선을 다해 도와줄게.",
  ui_story_5037_50371401_57_dialog_content = "아, 아마 괜찮을 거야!",
  ui_story_5037_50371401_58_dialog_content = "<color=#828282>얼마 후</color>",
  ui_story_5037_50371401_59_dialog_content = "어려워어어어!",
  ui_story_5037_50371401_60_dialog_content = "이 계획은 PlayerName 너한텐 확실히 좀 많이 어려웠나 보네...",
  ui_story_5037_50371401_61_dialog_content = "나도 정리하면서 느꼈지만 여러 내용이 복잡하게 얽혀 있기도 하고,\n서로 영향을 주는 부분들도 있었어.",
  ui_story_5037_50371401_62_dialog_content = "아무래도 천천히 하나씩 배워야 할 것 같아.",
  ui_story_5037_50371401_63_dialog_content = "오늘은 시간이 늦었으니까 일단 여기까지 하자.",
  ui_story_5037_50371401_64_dialog_content = "고생했어, PlayerName!",
  ui_story_5037_50371401_65_dialog_content = "고생 많았어.",
  ui_story_5037_50371401_66_dialog_content = "나보단 두 사람이 더 고생했는걸. 이렇게 많은 자료를 준비하는 것도\n정말 쉽지 않았을 텐데.",
  ui_story_5037_50371401_67_dialog_content = "우리 셋이 어떤 사인데~ 그런 말은 안 해도 돼.",
  ui_story_5037_50371401_68_dialog_content = "그럼 얼른 가서 쉬어!",
  ui_story_5037_50371401_69_dialog_content = "응, 바이스랑 카렌도 푹 쉬어!",
  ui_story_5037_50371401_70_dialog_content = "우리 둘은 아직 할 일이 조금 남아서, 잠깐 한 번 나갔다 와야 해.",
  ui_story_5037_50371401_71_dialog_content = "어? 나갔다 와야 한다고? 어디?",
  ui_story_5037_50371401_72_dialog_content = "노래를 잘 부르는 걸로 유명한 오로리안 몇 명한테 인터뷰를 하러 가기로 했거든. 그럼 노래 부를 때 어떻게 해야 하는지 팁도 얻을 수 있잖아.",
  ui_story_5037_50371401_73_dialog_content = "사람마다 상황은 다 다르지만, 보컬 기술은 서로 통하는 게 많기도 하고.",
  ui_story_5037_50371401_74_dialog_content = "이 기술들이 골디 씨한테 뭔가 새로운 걸 발견할 수 있게 해 준다면,\n두 사람한테도 도움이 될 것 같아서.",
  ui_story_5037_50371401_75_dialog_content = "근데 육성 계획을 준비하는 것만으로도 여기저기 많이 다녔을 것 같은데, 아니야?",
  ui_story_5037_50371401_76_dialog_content = "진짜 휴식이 필요한 건 바이스랑 카렌 같네...",
  ui_story_5037_50371401_77_dialog_content = "걱정하지 마! 난 완전 풀파워 상태거든!",
  ui_story_5037_50371401_78_dialog_content = "인터뷰를 진행하는 건 신선한 경험이라 나도, 바이스도 무척 기대 중이야.",
  ui_story_5037_50371401_79_dialog_content = "그래서인지 아무리 바빠도 피곤하다고 느껴지진 않아.",
  ui_story_5037_50371401_80_dialog_content = "PlayerName 너도 이런 느낌이야?",
  ui_story_5037_50371401_81_dialog_content = "그렇긴 해...",
  ui_story_5037_50371401_82_dialog_content = "프로듀서 일을 시작하고 나서부터 지금까지, 매일매일 아침부터 밤까지\n거의 눈코 뜰 새 없이 바빴는데.",
  ui_story_5037_50371401_83_dialog_content = "그래도 매일 여러 가지 새로운 일들을 겪으니까 피곤하단 생각은 전혀 안 들더라고!",
  ui_story_5037_50371401_84_dialog_content = "꼭 지하에서 처음 나와서 모두를 만났던 그때 같은 기분이야.",
  ui_story_5037_50371401_85_dialog_content = "암귀한테 줄곧 쫓겨 다니고 있었지만, 전혀 괴롭거나 힘들지 않았어.",
  ui_story_5037_50371401_86_dialog_content = "그게 바로 새로운 여정이 주는 신선함이라고 생각해!",
  ui_story_5037_50371401_87_dialog_content = "응!",
  ui_story_5037_50371401_88_dialog_content = "그렇다고 해도 두 사람만 바쁘게 일하게 두진 않을 거야!",
  ui_story_5037_50371401_89_dialog_content = "뭐?",
  ui_story_5037_50371401_90_dialog_content = "어째서?",
  ui_story_5037_50371401_91_dialog_content = "우린 항상 같이 움직였잖아.",
  ui_story_5037_50371401_92_dialog_content = "여행이든 모험이든 우리 셋은 언제나 동료였어.",
  ui_story_5037_50371401_93_dialog_content = "그러니까 나도 함께할래!",
  ui_story_5037_50371401_94_dialog_content = "하지만...",
  ui_story_5037_50371401_95_dialog_content = "내 걱정은 하지 마! 항상 그래왔던 것처럼 우리 함께 힘내자.",
  ui_story_5037_50371401_96_dialog_content = "...응, 그래. 지금까지 그래 왔던 것처럼!",
  ui_story_5037_50371501_1_dialog_content = "PlayerName 팀의 임시 회의. 3, 2, 1. 액션!",
  ui_story_5037_50371501_2_dialog_content = "늦어서 미안해!",
  ui_story_5037_50371501_3_dialog_content = "괜찮아! 왔으면 됐어!",
  ui_story_5037_50371501_4_dialog_content = "어라? 골디는?",
  ui_story_5037_50371501_5_dialog_content = "샤엘 씨랑 앞으로의 계획을 상의하러 갔어. 잠시도 빠져나올 시간이 없을 거야.",
  ui_story_5037_50371501_6_dialog_content = "흐응, 아쉽게 됐네...",
  ui_story_5037_50371501_7_dialog_content = "아쉽다고?",
  ui_story_5037_50371501_8_dialog_content = "골디와 함께 데뷔 콘서트를 무사히 치른 걸 축하해.",
  ui_story_5037_50371501_9_dialog_content = "두 사람이 돌아오면 같이 즐기려고 간식과 차를 준비했거든.",
  ui_story_5037_50371501_10_dialog_content = "고마워! 골디 몫은 나중에 따로 챙겨두면 될 거야.",
  ui_story_5037_50371501_11_dialog_content = "골디가 없어서 정말 아쉬운걸.",
  ui_story_5037_50371501_12_dialog_content = "다 같이 먹으려고 오랫동안 쿠키를 잔뜩 구웠거든.",
  ui_story_5037_50371501_13_dialog_content = "여러 번 태운 끝에 간신히 성공한 건데...",
  ui_story_5037_50371501_14_dialog_content = "고생이 많았구나...",
  ui_story_5037_50371501_15_dialog_content = "(바이스가 열심히 구운 거니까 분명히 괜찮겠지?)",
  ui_story_5037_50371501_16_dialog_content = "시간이 정말 빠른 것 같아, 데뷔 콘서트가 벌써 끝날 줄은 몰랐어.",
  ui_story_5037_50371501_17_dialog_content = "그러게, 「프로듀서 속성 과정」도 개설한 지 벌써 시간이 꽤 됐잖아.",
  ui_story_5037_50371501_18_dialog_content = "처음 PlayerName 네가 프로듀서가 될 수 있도록 도와줄 땐\n다들 정신이 하나도 없었는데.",
  ui_story_5037_50371501_19_dialog_content = "이제 넌 골디랑 같이 데뷔 콘서트를 멋지게 치렀어.",
  ui_story_5037_50371501_20_dialog_content = "이걸로 PlayerName 넌 믿을 수 있는 프로듀서가 된 거야.",
  ui_story_5037_50371501_21_dialog_content = "맞아, PlayerName의 실력이 눈에 띄게 성장했어!",
  ui_story_5037_50371501_22_dialog_content = "후후, 고마워! 그렇게 말하니 조금 부끄럽네.",
  ui_story_5037_50371501_23_dialog_content = "축하해!",
  ui_story_5037_50371501_24_dialog_content = "축하해, PlayerName.",
  ui_story_5037_50371501_25_dialog_content = "고마워.",
  ui_story_5037_50371501_26_dialog_content = "그럼 축하 파티를 시작해 볼까!",
  ui_story_5037_50371501_27_dialog_content = "더 늦으면 차가 다 식어 버릴 거야!",
  ui_story_5037_50371501_28_dialog_content = "<color=#828282>부스럭부스럭...</color>",
  ui_story_5037_50371501_29_dialog_content = "방금 이상한 소리 못 들었어?",
  ui_story_5037_50371501_30_dialog_content = "으응? 이상한 소리?",
  ui_story_5037_50371501_31_dialog_content = "<color=#828282>부스럭부스럭...</color>",
  ui_story_5037_50371501_32_dialog_content = "앗, 또 들려. 저기 악기를 놔둔 구석에서 들리는 것 같아.",
  ui_story_5037_50371501_33_dialog_content = "바람 소리인가?",
  ui_story_5037_50371501_34_dialog_content = "<color=#828282>부스럭부스럭...</color>",
  ui_story_5037_50371501_35_dialog_content = "......",
  ui_story_5037_50371501_36_dialog_content = "드럼 뒤에 뭐가 숨어 있나?",
  ui_story_5037_50371501_37_dialog_content = "설마... 암귀?",
  ui_story_5037_50371501_38_dialog_content = "알아보면 되겠지.",
  ui_story_5037_50371501_39_dialog_content = "빙화여──",
  ui_story_5037_50371501_40_dialog_content = "루! 루우우!",
  ui_story_5037_50371501_41_dialog_content = "에엣? 키아로?!",
  ui_story_5037_50371501_42_dialog_content = "피아 곁에서 떠날 줄 모르던 녀석이 왜 여기 온 거지?",
  ui_story_5037_50371501_43_dialog_content = "루우우...\n(피아가 PlayerName 팀의 정보를 알아내라고 해서 오긴 왔는데루우...)",
  ui_story_5037_50371501_44_dialog_content = "루우우!\n(사람이 이렇게 많이 있을 거라곤 말 안 했잖아루우!)",
  ui_story_5037_50371501_45_dialog_content = "루, 루우우.\n(들켰으니 기회를 봐서 도망쳐야겠어루우.)",
  ui_story_5037_50371501_46_dialog_content = "설마 정보를 알아내려고 온 건 아니겠지?",
  ui_story_5037_50371501_47_dialog_content = "루, 루우!",
  ui_story_5037_50371501_48_dialog_content = "아니라는 것 같은데.",
  ui_story_5037_50371501_49_dialog_content = "하긴, 카이로의 평소 모습으로 봐선, 그냥 먹을 걸 찾다가 길을 잃고\n여기까지 온 거겠지.",
  ui_story_5037_50371501_50_dialog_content = "피아가 비크한테 짜준 강도 높은 트레이닝 계획을 못 견디고 키아로가 몰래\n도망쳐 나온 건 아닐까?",
  ui_story_5037_50371501_51_dialog_content = "루!",
  ui_story_5037_50371501_52_dialog_content = "키아로가 그렇다는 것 같은데.",
  ui_story_5037_50371501_53_dialog_content = "불쌍한 녀석, 날마다 비크의 트레이닝을 감시하느라 분명히 힘들었을 거야...",
  ui_story_5037_50371501_54_dialog_content = "루우우...",
  ui_story_5037_50371501_55_dialog_content = "여기서 쉬게 해 주자. 준비한 쿠키랑 차가 많으니까 키아로한테도 나눠줄 수 있어.",
  ui_story_5037_50371501_56_dialog_content = "응, 그러자! 그러고 나서 피아한테 돌려보내자.",
  ui_story_5037_50371501_57_dialog_content = "루~ 루우~\n(잘 됐다루우, 정보를 캐러 왔다는 걸 눈치 못 챈 것 같네루우.)",
  ui_story_5037_50371501_58_dialog_content = "루우!\n(게다가 맛있는 간식까지, 과연 뭘까루우?)",
  ui_story_5037_50371501_59_dialog_content = "키아로는 동물 쿠키 먹는 걸 무척 좋아한다고 피아가 말한 적 있었어.",
  ui_story_5037_50371501_60_dialog_content = "내가 구운 쿠키를 키아로가 좋아할지 모르겠네...",
  ui_story_5037_50371501_61_dialog_content = "(으엑, 이 느낌...!)",
  ui_story_5037_50371501_62_dialog_content = "(그때 「그거」 같잖아!)",
  ui_story_5037_50371501_63_dialog_content = "루우!\n(이, 이거! 왠지 위험한 느낌이다루우!)",
  ui_story_5037_50371501_64_dialog_content = "키아로, 내가 구운 쿠키 좀 먹어 봐!",
  ui_story_5037_50371501_65_dialog_content = "백야성의 디저트 가게에서 파는 것처럼 예쁘진 않지만, 그래도 레시피는 똑같아!",
  ui_story_5037_50371501_66_dialog_content = "루, 루우!\n(오, 오지 마루우!)",
  ui_story_5037_50371501_67_dialog_content = "자, 입 벌려 봐~",
  ui_story_5037_50371501_68_dialog_content = "루우우!",
  ui_story_5037_50371501_69_dialog_content = "키아로가 갑자기 달아나는데?!",
  ui_story_5037_50371501_70_dialog_content = "어엇, 저긴 책을 쌓아둔 곳이잖아!",
  ui_story_5037_50371501_71_dialog_content = "얼른 키아로를 잡아! 녀석의 끈적거리는 몸 때문에 책이 젖어버릴 거야!",
  ui_story_5037_50371501_72_dialog_content = "키아로, 거기 서!",
  ui_story_5037_50371501_73_dialog_content = "루우우!",
  ui_story_5037_50371501_74_dialog_content = "(큰일이야, 키아로가 책더미 쪽으로 곧장 뛰어들었어!)",
  ui_story_5037_50371501_75_option_content = "(전문 서적을 지킨다)",
  ui_story_5037_50371501_76_option_content = "(잡지를 지킨다)",
  ui_story_5037_50371501_77_dialog_content = "<color=#828282>쿠웅!</color>",
  ui_story_5037_50371501_78_dialog_content = "으아앗──!",
  ui_story_5037_50371501_79_dialog_content = "<size=45>아파!!</size>",
  ui_story_5037_50371501_80_dialog_content = "PlayerName?!",
  ui_story_5037_50371501_81_dialog_content = "괜찮아... 그냥 좀 아파서...",
  ui_story_5037_50371501_82_dialog_content = "루...",
  ui_story_5037_50371501_83_dialog_content = "루우우!",
  ui_story_5037_50371501_84_dialog_content = "이 녀석, 엄청 빠르잖아!",
  ui_story_5037_50371501_85_dialog_content = "책은 어때? 무사한 거야?",
  ui_story_5037_50371501_86_dialog_content = "푸웁, 콜록콜록... 적어도 일부는 지켰어.",
  ui_story_5037_50371501_87_dialog_content = "나도 메모랑 스크랩은 건졌어.",
  ui_story_5037_50371501_88_dialog_content = "하지만 나머지 책이 전부 젖어버렸어.",
  ui_story_5037_50371501_89_dialog_content = "이렇게 축 처져 있어 봤자 소용없어. 일단 젖은 책부터 골라내자.",
  ui_story_5037_50371501_90_dialog_content = "한 권, 두 권...",
  ui_story_5037_50371501_91_dialog_content = "이쪽에 있는 건 잘 말리기만 하면 읽는 데는 지장 없을 것 같아.",
  ui_story_5037_50371501_92_dialog_content = "근데 이 몇 권은 전부 젖어서 글자가 다 번져 버렸어. 읽을 수가 없겠어.",
  ui_story_5037_50371501_93_dialog_content = "이 중엔 다른 곳에서 빌린 책도 있는 것 같아!",
  ui_story_5037_50371501_94_dialog_content = "어쩔 수 없지. 일단 빌린 책부터 정리해서 책 주인한테 사과하고 물어줘야지.",
  ui_story_5037_50371501_95_dialog_content = "그래야겠네.",
  ui_story_5037_50371501_96_dialog_content = "모아둔 나이티움으로 물어줄 수 있을지 모르겠는데...",
  ui_story_5037_50371501_97_dialog_content = "나도 좀 낼게.",
  ui_story_5037_50371501_98_dialog_content = "응, 나도 키아로를 막지 못했으니까 돈을 보탤게.",
  ui_story_5037_50371501_99_dialog_content = "걱정하지 마, PlayerName. 우리가 도와줄 테니까.",
  ui_story_5037_50371501_100_dialog_content = "고마워. 바이스, 카렌...",
  ui_story_5037_50371501_101_dialog_content = "근데 가장 중요한 문제가 하나 남았어...",
  ui_story_5037_50371501_102_dialog_content = "피아를 만나서 동료를 제대로 가르치라고 말해야 해!",
  ui_story_5037_50371601_1_dialog_content = "PlayerName 팀의 최종 회의. 3, 2, 1. 액션!",
  ui_story_5037_50371601_2_dialog_content = "「최종 회의」인 거야? 벌써 시간이 이렇게 돼버렸네.",
  ui_story_5037_50371601_3_dialog_content = "그러게, 며칠 뒤면 「졸업 콘서트」잖아.",
  ui_story_5037_50371601_4_dialog_content = "시간이 정말 빠른 것 같아.\n책을 가져와서 「프로듀스 속성반」 수업을 시작한 게 엊그제 같은데.",
  ui_story_5037_50371601_5_dialog_content = "우리 오늘 뭐 해야 해?",
  ui_story_5037_50371601_6_dialog_content = "오늘의 주요 임무는 딱 하나, 바로 정리 정돈이야!",
  ui_story_5037_50371601_7_dialog_content = "PlayerName 넌 계획했던 모든 프로젝트를 완성하고 훌륭한 프로듀서가 됐어!",
  ui_story_5037_50371601_8_dialog_content = "그러니까 「프로듀서 속성반」의 정식 결과인 셈이지!",
  ui_story_5037_50371601_9_dialog_content = "맞아, 오늘 할 일은 책을 가지런히 정리하는 거야.",
  ui_story_5037_50371601_10_dialog_content = "이렇게 하면 빌린 책을 주인한테 빨리 돌려주기도 편할 거야.",
  ui_story_5037_50371601_11_dialog_content = "그렇구나, 그럼 힘내볼까!",
  ui_story_5037_50371601_12_dialog_content = "같이 책을 빠르게 정리해 보자.",
  ui_story_5037_50371601_13_dialog_content = "응!",
  ui_story_5037_50371601_14_dialog_content = "<color=#828282>얼마 후</color>",
  ui_story_5037_50371601_15_dialog_content = "《좋은 습관 만들기: 첫걸음부터 배우는 계획 세우기》는 어디 놔야 돼?",
  ui_story_5037_50371601_16_dialog_content = "나한테 줘.",
  ui_story_5037_50371601_17_dialog_content = "이건 비비안 님한테 빌린 거야. 특별히 추천해 주신 책이야!",
  ui_story_5037_50371601_18_dialog_content = "비비안 님도 이 책을 보고 시간 분배 방법을 조금씩 배우기 시작했다고 하셨거든.",
  ui_story_5037_50371601_19_dialog_content = "여기 있는 지식은 확실히 쓸모 있더라. 큰 도움을 받았어!",
  ui_story_5037_50371601_20_dialog_content = "PlayerName, 네가 들고 있는 그 《300가지 합주 스킬》 좀 이리 줄래?",
  ui_story_5037_50371601_21_dialog_content = "응. 자, 여기!",
  ui_story_5037_50371601_22_dialog_content = "이건 키팅 애들한테 빌린 책 같은데?",
  ui_story_5037_50371601_23_dialog_content = "어떻게 알았어?",
  ui_story_5037_50371601_24_dialog_content = "겉은 깨끗하지만, 안쪽 페이지 번호마다 낙서가 가득하거든.",
  ui_story_5037_50371601_25_dialog_content = "그것보다 너무한 건 낙서로 날 그려놓고 다크 서클을 유난히 강조했다는 거야!",
  ui_story_5037_50371601_26_dialog_content = "...풉!",
  ui_story_5037_50371601_27_dialog_content = "확실히 녀석들다운 행동이야.",
  ui_story_5037_50371601_28_dialog_content = "신경 쓰인다면 녀석들한테 낙서를 지우라고 할게.",
  ui_story_5037_50371601_29_dialog_content = "그럴 필요 없어...",
  ui_story_5037_50371601_30_dialog_content = "그렇게 시키면 더 심한 노래를 지어서 날 놀려댈 게 뻔하니까.",
  ui_story_5037_50371601_31_dialog_content = "그러니까 그냥 내버려 둬.",
  ui_story_5037_50371601_32_dialog_content = "확실히 골치 아픈 녀석들이라니까.",
  ui_story_5037_50371601_33_dialog_content = "자, 이제 책은 거의 다 정리된 거지?",
  ui_story_5037_50371601_34_dialog_content = "전부 다 분류했어!",
  ui_story_5037_50371601_35_dialog_content = "책 말고도 아직 메모가 잔뜩 남았어.",
  ui_story_5037_50371601_36_dialog_content = "이건 처음부터 지금까지 줄곧 모아둔 거야.",
  ui_story_5037_50371601_37_dialog_content = "맞아, 거기 적힌 글자 하나하나가 우리의 노력과 땀을 증명하고 있어!",
  ui_story_5037_50371601_38_dialog_content = "엄청 두툼하네!",
  ui_story_5037_50371601_39_dialog_content = "필기할 땐 별생각 없이 그냥 적당히 한 장 쓱 꺼내서 배운 걸 적었을 뿐인데.",
  ui_story_5037_50371601_40_dialog_content = "근데 이렇게 많이 쌓일 줄은 몰랐어!",
  ui_story_5037_50371601_41_dialog_content = "그게 바로 그동안 쌓아온 성과야.",
  ui_story_5037_50371601_42_dialog_content = "근데 이렇게 잔뜩 필기한 게 무척 오랜만이라서 꼭 학창 시절로 돌아간 기분이야!",
  ui_story_5037_50371601_43_dialog_content = "카렌이랑 같이 수업도 듣고, 필기도 하고, 밥도 같이 먹고...\n하루하루가 정말 느긋했는데 말이야!",
  ui_story_5037_50371601_44_dialog_content = "당연하잖아, 시험 보기 며칠 전만 빼면.",
  ui_story_5037_50371601_45_dialog_content = "학창 시절? 상상하기 어려운걸...",
  ui_story_5037_50371601_46_dialog_content = "어쨌든 난 학교생활은 전혀 겪어보지 못했으니까.",
  ui_story_5037_50371601_47_dialog_content = "줄곧 스카이워커호가 PlayerName의 선생님이었지?",
  ui_story_5037_50371601_48_dialog_content = "그럼 다른 사람과 함께 공부하고, 생활하는 경험을 상상하긴 확실히 어렵겠네.",
  ui_story_5037_50371601_49_dialog_content = "그건 마치 함께 여행 가는 거랑 비슷한 기분이야.\n유일한 차이라면 암귀를 상대할 필요가 없다는 걸까나?",
  ui_story_5037_50371601_50_dialog_content = "앞으로 기회가 된다면 다 같이 여명 아카데미에 참관하러 가자.",
  ui_story_5037_50371601_51_dialog_content = "지금 프로듀서를 경험하는 것처럼 학교생활도 체험해 보는 거야.",
  ui_story_5037_50371601_52_dialog_content = "좋아! 근데 시험은 없으면 안 되는 거야?",
  ui_story_5037_50371601_53_dialog_content = "오랫동안 바쁘게 지냈더니 너무 피곤해서...",
  ui_story_5037_50371601_54_dialog_content = "가장 하고 싶은 건 역시 시험이나 심사 따윈 신경 쓰지 않고 푹 쉬는 거야!",
  ui_story_5037_50371601_55_option_content = "하지만 긴장을 늦춰선 안 돼.",
  ui_story_5037_50371601_56_dialog_content = "마지막 콘서트를 준비하려면 아직 해야 할 일이 잔뜩이니까.",
  ui_story_5037_50371601_57_dialog_content = "지금 긴장을 풀면 그동안 힘들게 쌓은 성과가 사라지고 말 거야!",
  ui_story_5037_50371601_58_dialog_content = "PlayerName 넌 새로운 일에 항상 열정적이네!",
  ui_story_5037_50371601_59_dialog_content = "그동안 지하에서 17년 동안 살았으니까...",
  ui_story_5037_50371601_60_dialog_content = "그래서 항상 새로운 일에 도전해 보고 싶은 거야?",
  ui_story_5037_50371601_61_dialog_content = "맞아!",
  ui_story_5037_50371601_62_option_content = "지금 당장 눕고 싶어.",
  ui_story_5037_50371601_63_dialog_content = "처음 프로듀서를 할 때만 해도 신선하게 느껴지던 게 이제는 점점 익숙하게 느껴져.",
  ui_story_5037_50371601_64_dialog_content = "매일 똑같은 일을 하고 있잖아. 보람이 없는 건 아니지만 지루한 건 어쩔 수 없네...",
  ui_story_5037_50371601_65_dialog_content = "그 기분, 나도 알아...",
  ui_story_5037_50371601_66_dialog_content = "아무리 재미있는 일이라도 매일 반복되면 재미가 없어지는 법이니까.",
  ui_story_5037_50371601_67_dialog_content = "그래서 우린 끊임없이 새로운 도전을 해야 돼.",
  ui_story_5037_50371601_68_dialog_content = "그래도 어쨌든 프로듀서로서의 경험은 나한테 무척 소중해!",
  ui_story_5037_50371601_69_dialog_content = "골디한테 콘서트를 열어주고, 너희와 함께 공부도 할 수 있으니까!",
  ui_story_5037_50371601_70_dialog_content = "이런 경험을 할 수 있어서 정말 기뻐!",
  ui_story_5037_50371601_71_dialog_content = "지금의 PlayerName 넌 계속 프로듀서로 일해도 분명 큰 성과를 낼 수 있을 거야!",
  ui_story_5037_50371601_72_dialog_content = "PlayerName, 프로듀서와 세상을 여행하는 삶 중에서 어느 쪽이 더 좋아?",
  ui_story_5037_50371601_73_dialog_content = "그 문제의 답은... 물론 이미 정해져 있어!",
  ui_story_5037_50371601_74_dialog_content = "!",
  ui_story_5037_50371601_75_dialog_content = "당연히 모두와 함께 여행할 때가 가장 즐겁지!",
  ui_story_5037_50371701_1_dialog_content = "플로리나? 네가 올 줄은 몰랐어, 어서 와!",
  ui_story_5037_50371701_2_dialog_content = "근데 골디의 콘서트를 보러 왔다면 며칠 더 기다려야 할 거야. 아직 연습 중이거든.",
  ui_story_5037_50371701_3_dialog_content = "그거 때문에 온 거 아냐.",
  ui_story_5037_50371701_4_dialog_content = "어?",
  ui_story_5037_50371701_5_dialog_content = "난 도와주러 온 거야.",
  ui_story_5037_50371701_6_dialog_content = "당신이 프로듀서라는 새로운 직업에 도전하고 있다는 이야기를 들었어.",
  ui_story_5037_50371701_7_dialog_content = "친구로서 당신한테 묻고 싶은 게 있어.",
  ui_story_5037_50371701_8_dialog_content = "아이테르, 내가 도와줄 수 있는 게 있을까?",
  ui_story_5037_50371701_9_dialog_content = "사실 특별히 도와줄 일은 없어...",
  ui_story_5037_50371701_10_dialog_content = "그렇구나...",
  ui_story_5037_50371701_11_dialog_content = "(앗, 플로리나가 실망한 것 같은데?)",
  ui_story_5037_50371701_12_dialog_content = "(설마 도움이 안 돼서 괴로운 건가...)",
  ui_story_5037_50371701_13_dialog_content = "아니! 있어, 사실 하나 있어!",
  ui_story_5037_50371701_14_dialog_content = "그게 뭔데?",
  ui_story_5037_50371701_15_dialog_content = "(무슨 말을 해야 하지...)",
  ui_story_5037_50371701_16_dialog_content = "(플로리나가 실망하는 건 싫지만, 그렇다고 너무 힘들게 하고 싶지도 않아...)",
  ui_story_5037_50371701_17_dialog_content = "(맞아, 플로리나는 예전에 학생회장이었다고 했던 것 같으니까, 그럼...)",
  ui_story_5037_50371701_18_option_content = "편곡에 대해 가르쳐 줘.",
  ui_story_5037_50371701_19_dialog_content = "골디가 최근에 곡을 새로 썼는데, 반주를 어떻게 할지 아직 생각을 못 했거든.\n플로리나 넌 무슨 좋은 제안 있어?",
  ui_story_5037_50371701_20_dialog_content = "음악의 반주 말이지... 그건 나도 잘 모르는 분야야.",
  ui_story_5037_50371701_21_dialog_content = "하지만 난 오페라를 자주 듣는 편이고, 이 분야에 대해 나름의 지식이 있어.\n내가 최선을 다해서 도와줄게!",
  ui_story_5037_50371701_22_dialog_content = "고마워!",
  ui_story_5037_50371701_23_option_content = "학습법에 대해 가르쳐 줘.",
  ui_story_5037_50371701_24_dialog_content = "골디가 콘서트에 도움이 될 만한 건설적인 의견을 들려 달라고 하는데,\n어떻게 해야 할지 모르겠어.",
  ui_story_5037_50371701_25_dialog_content = "어떻게 하면 성악 지식을 좀 더 빨리 배워서 골디한테 도움이 될 만한\n얘기를 해줄 수 있을까?",
  ui_story_5037_50371701_26_dialog_content = "제대로 찾아왔네. 난 「체계적인 자기주도 학습」 쪽에는 노하우가 있거든.\n내가 전부 가르쳐 줄게!",
  ui_story_5037_50371701_27_dialog_content = "그럼 부탁할게!",
  ui_story_5037_50371701_28_dialog_content = "<color=#828282>얼마 후</color>",
  ui_story_5037_50371701_29_dialog_content = "내가 알고 있는 건 이제 전부 가르쳐 줬어.",
  ui_story_5037_50371701_30_dialog_content = "잠깐만, 아직도 잘 모르는 게 하나 있어.",
  ui_story_5037_50371701_31_dialog_content = "방금 적은 것 좀 확인할게...",
  ui_story_5037_50371701_32_dialog_content = "필기가 무척 꼼꼼하네. 좋은 습관이야.",
  ui_story_5037_50371701_33_dialog_content = "평소에 워낙 잘 까먹는 편이라 공부할 때면 본 것들을 전부 적고 있거든.",
  ui_story_5037_50371701_34_dialog_content = "일기를 쓰는 것도 같은 이유야. 살면서 겪은 일들을 잊고 싶지 않으니까.",
  ui_story_5037_50371701_35_dialog_content = "「아무리 기억력이 좋아도 대충 쓴 글씨보다 못하다」고나 할까?",
  ui_story_5037_50371701_36_dialog_content = "그럼 열심히 공부하자, 아이테르.",
  ui_story_5037_50371701_37_dialog_content = "네 노력은 성장에 필요한 동력이 될 거야.",
  ui_story_5037_50371701_38_dialog_content = "격려해 줘서 고마워, 플로리나!",
  ui_story_5037_50371701_39_dialog_content = "이건 격려가 아냐.",
  ui_story_5037_50371701_40_dialog_content = "격려가 아니라고?",
  ui_story_5037_50371701_41_dialog_content = "이건 학창 시절 내가 겪었던 경험이야.",
  ui_story_5037_50371701_42_dialog_content = "「노력」은 평범한 사람이 평범하지 않은 업적을 쌓을 수 있도록 도와줘.\n그러니까 「노력」을 중요하게 여겨야 해.",
  ui_story_5037_50371701_43_dialog_content = "그렇구나. 그렇게 할게!",
  ui_story_5037_50371701_44_dialog_content = "그러고 보니까 플로리나 넌 여전히 그 구시대의 교복을 입고 있구나.",
  ui_story_5037_50371701_45_dialog_content = "응, 입었을 때 무척 가벼운 데다가, 학창 시절을 떠올리게 해 주거든.",
  ui_story_5037_50371701_46_dialog_content = "이걸 입고 있으면 내 자신에게 항상 깨달음을 주곤 해...",
  ui_story_5037_50371701_47_dialog_content = "학생 때처럼 겸손함과 정직함을 지키고, 항상 열심히 노력하면,\n중요한 일을 감당할 사람이 될 수 있을 거라고 말이야.",
  ui_story_5037_50371701_48_dialog_content = "PlayerName 너도 한번 입어 봐. 분명히 자신을 채찍질하는 효과가 있을 거야.",
  ui_story_5037_50371701_49_dialog_content = "나, 난 됐어!",
  ui_story_5037_50371701_50_dialog_content = "내 스타일로 입는 게 역시 제일 편해!",
  ui_story_5037_50371701_51_dialog_content = "그래? 그럼 당신 스타일대로 해.",
  ui_story_5037_50371701_52_dialog_content = "항상 최선을 다하고 긴장을 풀지 않으면 문제없을 거야.",
  ui_story_5037_50371701_53_dialog_content = "플로리나는 자신한테 정말 엄격하구나...",
  ui_story_5037_50371701_54_dialog_content = "이게 엄격한 거야? 난 아닌 것 같은데.",
  ui_story_5037_50371701_55_dialog_content = "난 헤이디 선배처럼 모두를 도울 수 있는 사람을 동경해.",
  ui_story_5037_50371701_56_dialog_content = "선배처럼 믿음직한 사람이 될 수 있다면, 과정이 아무리 힘들어도\n난 열심히 도전할 거야.",
  ui_story_5037_50371701_57_dialog_content = "지금의 난 여전히 부족하거든.",
  ui_story_5037_50371701_58_dialog_content = "난 플로리나가 충분히 대단하다고 생각해!",
  ui_story_5037_50371701_59_dialog_content = "게으름 피우지 않고 꾸준히 노력하는 것만으로도 대단한 일이잖아!",
  ui_story_5037_50371701_60_dialog_content = "나도 플로리나처럼 되면 좋을 텐데.",
  ui_story_5037_50371701_61_dialog_content = "그럼 자신이 동경하는 대상을 향해 우리 같이 최선을 다하자.",
  ui_story_5037_50371701_62_dialog_content = "좋아!",
  ui_story_5037_50371701_63_dialog_content = "참, 그리고 골디한테 물 많이 마시고 컨디션 조심하라고 해.",
  ui_story_5037_50371701_64_dialog_content = "노래를 부를 때는 목을 오랫동안 쓰잖아.\n물을 많이 마셔 둬야 건조해지는 걸 막을 수 있어.",
  ui_story_5037_50371701_65_dialog_content = "댄스도 고강도 운동이기 때문에 틈틈이 수분을 보충해 줘야 해.",
  ui_story_5037_50371701_66_dialog_content = "알았어. 꼭 전해 줄게!",
  ui_story_5037_50371701_67_dialog_content = "그리고 당신도, 아이테르.",
  ui_story_5037_50371701_68_dialog_content = "아무리 바빠도 건강은 챙겨.",
  ui_story_5037_50371701_69_dialog_content = "응...",
  ui_story_5037_50371701_70_dialog_content = "빛의 신께서 당신을 보살펴 주시고, 당신의 일이 순조롭길 기원할게.",
  ui_story_5037_50371701_71_dialog_content = "응!",
  ui_story_5037_50371801_1_dialog_content = "이건 쉽게 건질 수 없는 셀카야!\n세로로! 나랑 골디, PlayerName 셋이 잘 나오게 찍어줘!",
  ui_story_5037_50371801_2_dialog_content = "3, 2, 1. 액션!",
  ui_story_5037_50371801_3_dialog_content = "안녕! 난 유명 감독 리리카라고 해!",
  ui_story_5037_50371801_4_dialog_content = "오늘은 멘토로서 유명 아이돌인 골디, 그리고 PlayerName 프로듀서와 함께...",
  ui_story_5037_50371801_5_dialog_content = "공연 특훈을 진행할 거야!",
  ui_story_5037_50371801_6_dialog_content = "골디, PlayerName! 이리 와서 모두와 인사해.",
  ui_story_5037_50371801_7_dialog_content = "귀여운 우리 팬들~ 모두 반가워!",
  ui_story_5037_50371801_8_dialog_content = "아, 안녕...",
  ui_story_5037_50371801_9_dialog_content = "(녹화된 모습을 사람들이 볼 거라고 생각하니까 좀 어색하네...)",
  ui_story_5037_50371801_10_dialog_content = "그럼 오늘의 특훈을 위해 내가 특별한 게임을 하나 준비했어!",
  ui_story_5037_50371801_11_dialog_content = "게임? 좋아, 난 게임이 제일 좋거든!",
  ui_story_5037_50371801_12_dialog_content = "어떤 게임인데?",
  ui_story_5037_50371801_13_dialog_content = "그건 바로... 「몸으로 말해요」!",
  ui_story_5037_50371801_14_dialog_content = "연기에서 의상, 메이크업, 대사나 표정은 연기의 최종 효과에 영향을 주게 돼.",
  ui_story_5037_50371801_15_dialog_content = "그래서 배우는 캐릭터를 최대한 이해하고 캐릭터에 어울리는 대사와 표정을\n지을 줄 알아야 해!",
  ui_story_5037_50371801_16_dialog_content = "맞는 말이야!",
  ui_story_5037_50371801_17_dialog_content = "난 PlayerName 주변의 친구들을 관찰하면서 그들의 특징을 파악한 뒤에,\n어울리는 대사를 써 봤어.",
  ui_story_5037_50371801_18_dialog_content = "이제부터 하려는 게임은 골디가 한 명을 고른 뒤에 그 사람의 말이나 행동을\n흉내 내는 거야.",
  ui_story_5037_50371801_19_dialog_content = "그런 뒤에 골디가 연기한 사람을 PlayerName 네가 맞히는 거지!",
  ui_story_5037_50371801_20_dialog_content = "PlayerName 네가 알아낸다면 골디의 연기가 성공적이라는 뜻이야!",
  ui_story_5037_50371801_21_dialog_content = "재미있을 것 같네!",
  ui_story_5037_50371801_22_dialog_content = "그런 거였구나!",
  ui_story_5037_50371801_23_dialog_content = "골디는 아직 연기 쪽은 신인이니까, PlayerName한테도 정답이 들어있는\n보기를 줄게.",
  ui_story_5037_50371801_24_dialog_content = "별로 어렵지 않을 테니까 부담 갖지 말고 즐겨봐!",
  ui_story_5037_50371801_25_dialog_content = "좋아!",
  ui_story_5037_50371801_26_dialog_content = "내 멋진 연기를 기대해 줘!",
  ui_story_5037_50371801_27_dialog_content = "골디, 그럼 여기서 하나를 뽑은 뒤에 연기해 봐.",
  ui_story_5037_50371801_28_dialog_content = "응... 이걸로 할게!",
  ui_story_5037_50371801_29_dialog_content = "PlayerName 씨, 나 그럼 시작할게~",
  ui_story_5037_50371801_30_dialog_content = "「어이, 애송이!」",
  ui_story_5037_50371801_31_dialog_content = "(익숙한 느낌이야!)",
  ui_story_5037_50371801_32_dialog_content = "「나랑 같이 한탕 하러 갈 준비됐나?」",
  ui_story_5037_50371801_33_dialog_content = "PlayerName, 골디가 누굴 연기하는지 맞혀봐!",
  ui_story_5037_50371801_34_option_content = "바튼 씨?",
  ui_story_5037_50371801_35_dialog_content = "땡, 비슷하지만 틀렸어!",
  ui_story_5037_50371801_36_dialog_content = "정답은 사메야마 씨야!",
  ui_story_5037_50371801_37_dialog_content = "이걸 틀렸네...",
  ui_story_5037_50371801_38_dialog_content = "내 연기가 별로였나? 다음에는 잘할게!",
  ui_story_5037_50371801_39_option_content = "사메야마?",
  ui_story_5037_50371801_40_dialog_content = "딩동댕!",
  ui_story_5037_50371801_41_dialog_content = "골디의 연기가 아주 좋았던 것 같네!",
  ui_story_5037_50371801_42_dialog_content = "멋진 연기였어. 사메야마 그 자체였어!",
  ui_story_5037_50371801_43_dialog_content = "등 뒤에서 빨간 렌치를 꺼내는 줄 알았다니까...",
  ui_story_5037_50371801_44_dialog_content = "칭찬인 거지?",
  ui_story_5037_50371801_45_option_content = "클레이튼?",
  ui_story_5037_50371801_46_dialog_content = "완전 땡!",
  ui_story_5037_50371801_47_dialog_content = "정답은 사메야마 씨야!",
  ui_story_5037_50371801_48_dialog_content = "PlayerName, 골디의 연기에 집중해!",
  ui_story_5037_50371801_49_dialog_content = "미, 미안...",
  ui_story_5037_50371801_50_dialog_content = "나도 열심히 할게!",
  ui_story_5037_50371801_51_dialog_content = "이제부터는 난이도를 높여야겠어!",
  ui_story_5037_50371801_52_dialog_content = "골디, 이 사람을 연기해 봐!",
  ui_story_5037_50371801_53_dialog_content = "이 사람? 나랑 너무 다른데... 한번 해볼게!",
  ui_story_5037_50371801_54_dialog_content = "「젊은 친구, 뭐 하고 있었어?」",
  ui_story_5037_50371801_55_dialog_content = "(이 사람은...?)",
  ui_story_5037_50371801_56_dialog_content = "「시간 있으면 내 방에서 애프터눈티 좀 갖다줘. 가지러 가기 너무 귀찮거든.」",
  ui_story_5037_50371801_57_dialog_content = "PlayerName, 이제 맞혀봐!",
  ui_story_5037_50371801_58_option_content = "미자드 씨?",
  ui_story_5037_50371801_59_dialog_content = "정답!",
  ui_story_5037_50371801_60_dialog_content = "문제가 꽤 어렵네...",
  ui_story_5037_50371801_61_dialog_content = "나도 어려웠어. 미자드 씨의 분위기나 표정은 워낙 특이해서 연기가 쉽지 않더라구.",
  ui_story_5037_50371801_62_dialog_content = "그래도 내가 맞혔다는 건 골디의 연기가 성공적이라는 뜻이야!",
  ui_story_5037_50371801_63_option_content = "성주님?",
  ui_story_5037_50371801_64_dialog_content = "나이로 보면 젊은 친구라고 불러도 이상할 게 없긴 하겠지...",
  ui_story_5037_50371801_65_dialog_content = "하지만 정답은 미자드 씨야!",
  ui_story_5037_50371801_66_dialog_content = "아무래도 내가 더 노력해야 할 것 같네...",
  ui_story_5037_50371801_67_dialog_content = "아냐, 이건 내가 생각이 짧았던 탓이야...",
  ui_story_5037_50371801_68_option_content = "트위티?",
  ui_story_5037_50371801_69_dialog_content = "땡! 트위티가 널 「젊은 친구」라고 부를 리 없잖아!",
  ui_story_5037_50371801_70_dialog_content = "정답은 미자드 씨라구!",
  ui_story_5037_50371801_71_dialog_content = "미자드 씨는 무척 예쁜 언니지만, 평소엔 항상 아저씨처럼 말하는 것 같아...",
  ui_story_5037_50371801_72_dialog_content = "그, 그렇지...",
  ui_story_5037_50371801_73_dialog_content = "마주칠 때마다 항상 뭔가 감시당하는 느낌이 든다니까!",
  ui_story_5037_50371801_74_dialog_content = "PlayerName 씨, 다음 문제는 우리 좀 더 힘내보자!",
  ui_story_5037_50371801_75_dialog_content = "이제 마지막 문제야!",
  ui_story_5037_50371801_76_dialog_content = "골디, 이 사람을 연기해 줘!",
  ui_story_5037_50371801_77_dialog_content = "어?! 이, 이래도 되는 거야?",
  ui_story_5037_50371801_78_dialog_content = "응, 최선을 다해서 연기해 봐!",
  ui_story_5037_50371801_79_dialog_content = "그, 그럼 시작할게!",
  ui_story_5037_50371801_80_dialog_content = "「PlayerName 씨...」",
  ui_story_5037_50371801_81_dialog_content = "(벌써 시작한 건가?!)",
  ui_story_5037_50371801_82_dialog_content = "「오늘도 우리 같이 힘내자!」",
  ui_story_5037_50371801_83_dialog_content = "PlayerName, 이제 맞혀봐!",
  ui_story_5037_50371801_84_option_content = "리리카?",
  ui_story_5037_50371801_85_dialog_content = "리리카랑 비슷하긴 해! 근데 리리카는 아니야...",
  ui_story_5037_50371801_86_dialog_content = "뭐?! 아니라고...?",
  ui_story_5037_50371801_87_dialog_content = "PlayerName, 정답은 바로 네 앞에 있어!",
  ui_story_5037_50371801_88_dialog_content = "설마... 골디가 방금 연기한 게 골디 자신인 거야?!",
  ui_story_5037_50371801_89_dialog_content = "정답이야!",
  ui_story_5037_50371801_90_option_content = "골디?",
  ui_story_5037_50371801_91_dialog_content = "딩동댕!",
  ui_story_5037_50371801_92_dialog_content = "PlayerName 씨가 정말 맞힐 줄은 몰랐어!",
  ui_story_5037_50371801_93_dialog_content = "평소의 골디도 이렇잖아, 언제나 에너지가 넘치니까!",
  ui_story_5037_50371801_94_dialog_content = "근데 이런 문제를 낸 의도를 잘 모르겠어.",
  ui_story_5037_50371801_95_dialog_content = "연기에 대한 프로듀서의 감각도 아이돌의 연기 트레이닝에 영향을 줄 수 있거든.",
  ui_story_5037_50371801_96_dialog_content = "훌륭한 프로듀서는 아이돌이 연기하는 캐릭터를 이해하는 것 외에도\n한 가지 중요한 스킬을 지녀야 해...",
  ui_story_5037_50371801_97_dialog_content = "그건 바로 아이돌 자신의 매력과 실력을 알아보는 거지!",
  ui_story_5037_50371801_98_dialog_content = "그래야만 아이돌을 상대로 효과적인 트레이닝을 진행할 수 있거든.",
  ui_story_5037_50371801_99_dialog_content = "그래서 PlayerName 네 자신의 능력을 시험해 보는 문제를 마지막으로 냈던 거야!",
  ui_story_5037_50371801_100_dialog_content = "그렇구나, 이제 알겠어!",
  ui_story_5037_50371801_101_dialog_content = "나도 많은 걸 깨달았어!",
  ui_story_5037_50371801_102_dialog_content = "캐릭터마다 이렇게 큰 차이가 있었다니, 더 많이 노력해야겠네!",
  ui_story_5037_50371801_103_dialog_content = "오늘의 트레이닝은 일단 여기까지. 두 사람 모두 힘내!",
  ui_story_5037_50371801_104_dialog_content = "돌아가서 오늘의 경험을 직접 실전으로 활용하는 거 잊지 말고!",
  ui_story_5037_50371801_105_dialog_content = "알았어!",
  ui_story_5037_50371801_106_dialog_content = "네, 리리카 감독님!",
  ui_story_5037_50371901_1_dialog_content = "운도의 무녀는... 대체 어떤 모습일까?",
  ui_story_5037_50371901_2_dialog_content = "무녀들은 춤과 노래 실력이 대단하고, 우아하면서도 신비한 존재라고 들었어.\n게다가 무척 강한 루미나틱스도 지녔고.",
  ui_story_5037_50371901_3_dialog_content = "궁금해서 생각을 멈출 수가 없어!",
  ui_story_5037_50371901_4_dialog_content = "이제 곧 만날 수 있을 거야!",
  ui_story_5037_50371901_5_dialog_content = "이번 만남을 위해서 난 간신히 시간을 내서 사무소에서 PlayerName 씨의\n콜로서스까지 달려왔어!",
  ui_story_5037_50371901_6_dialog_content = "진짜 무녀한테 춤을 배울 수 있다는 생각에 가슴이 막 두근두근해!",
  ui_story_5037_50371901_7_dialog_content = "<color=#828282>딸랑──</color>",
  ui_story_5037_50371901_8_dialog_content = "미안해요. 두 사람을 기다리게 했네요.",
  ui_story_5037_50371901_9_dialog_content = "괜찮아요. 제게 춤을 가르쳐 주시려고 멀리 운도에서 와 주신 것만으로도\n정말 고마운걸요!",
  ui_story_5037_50371901_10_dialog_content = "이분이 바로 골디 님이시겠군요.",
  ui_story_5037_50371901_11_dialog_content = "네! 안녕하세요, 린네 씨. 제 이름은 골디, 아이돌 가수예요.",
  ui_story_5037_50371901_12_dialog_content = "반갑습니다. 제 이름은 린네, 운도의 무녀입니다.",
  ui_story_5037_50371901_13_dialog_content = "아이돌 가수라는 것은 가수와 같은 것인지요.",
  ui_story_5037_50371901_14_dialog_content = "다른 점도 있어요. 아이돌은 노래 외에도 춤과 연기 같은 분야를 배워야 해요!",
  ui_story_5037_50371901_15_dialog_content = "그렇군요. 그래서 신악을 배우고 싶으셨던 건가요?",
  ui_story_5037_50371901_16_dialog_content = "네. 린네 씨, 저한테 춤을 가르쳐 주실 수 있을까요?",
  ui_story_5037_50371901_17_dialog_content = "물론입니다. 그렇다면 여기서 잠시 시범을 보여 드리겠습니다.",
  ui_story_5037_50371901_18_dialog_content = "진짜요?! 무녀의 신악을 직접 보게 되다니 정말 운이 좋네요!",
  ui_story_5037_50371901_19_dialog_content = "후훗...",
  ui_story_5037_50371901_20_dialog_content = "<color=#828282>딸랑──</color>",
  ui_story_5037_50371901_21_dialog_content = "<color=#828282>띠리링──</color>",
  ui_story_5037_50371901_22_dialog_content = "아름다워요...",
  ui_story_5037_50371901_23_dialog_content = "방울 소리... 그리고 린네 씨의 춤추는 모습만 봐도 마음이 차분해져요...",
  ui_story_5037_50371901_24_dialog_content = "이건 신악의 기본 동작 중 일부랍니다. 골디 님도 한번 해 보시지요.",
  ui_story_5037_50371901_25_dialog_content = "해 볼게요!",
  ui_story_5037_50371901_26_dialog_content = "이렇게 하면 될까요?",
  ui_story_5037_50371901_27_dialog_content = "맞아! 골디 너 동작이 정말 정확하네!",
  ui_story_5037_50371901_28_dialog_content = "동작을 흉내 내는 거라면 자신 있거든!",
  ui_story_5037_50371901_29_dialog_content = "하지만 내가 추는 신악은 어딘가 부족한 느낌이야...",
  ui_story_5037_50371901_30_dialog_content = "확실히... 왠지 린네 씨 춤처럼 평온한 느낌은 없는 것 같아.",
  ui_story_5037_50371901_31_dialog_content = "린네 씨, 혹시 춤을 출 때 특별한 루미나틱스를 쓰시는 건가요?",
  ui_story_5037_50371901_32_dialog_content = "그 어떤 루미나틱스도 쓰지 않았습니다. 그저 단순한 춤일 뿐이지요.",
  ui_story_5037_50371901_33_dialog_content = "그럼 대체 어디가 다른 걸까요?",
  ui_story_5037_50371901_34_dialog_content = "실례지만 골디 님께서는 춤을 출 때 무엇을 생각하셨는지요.",
  ui_story_5037_50371901_35_dialog_content = "뭘 생각했냐고요...?",
  ui_story_5037_50371901_36_dialog_content = "이것저것 많이 생각한 것 같아요.\n예를 들면 이 동작이 맞는지, 다음 동작은 어땠는지 같은 거요...",
  ui_story_5037_50371901_37_dialog_content = "처음 추는 신악이니까 제대로 못 출까 봐 걱정이었거든요.",
  ui_story_5037_50371901_38_dialog_content = "어머, 어쩌면 그것이 문제였을지도 모르겠군요.",
  ui_story_5037_50371901_39_dialog_content = "신악은 신께 바치는 춤입니다. 신악을 출 때는 오로지 신만을 생각해야 하지요.",
  ui_story_5037_50371901_40_dialog_content = "그리해야만 춤을 통해 진심을 전할 수 있는 것입니다.",
  ui_story_5037_50371901_41_dialog_content = "아... 네! 이제 알겠어요!",
  ui_story_5037_50371901_42_dialog_content = "벌써?!",
  ui_story_5037_50371901_43_dialog_content = "내가 평소에 콘서트를 할 때랑 비슷한 것 같아!",
  ui_story_5037_50371901_44_dialog_content = "나도 노래나 춤을 선보일 땐 팬들을 기쁘게 해주고 싶다는 생각 외엔\n아무 생각도 안 들어.",
  ui_story_5037_50371901_45_dialog_content = "그럴 때 나오는 노래와 춤 동작은 한결 자연스럽거든!",
  ui_story_5037_50371901_46_dialog_content = "비록 춤은 다르나, 공통점이 있군요.",
  ui_story_5037_50371901_47_dialog_content = "그러한 마음가짐으로 다시 한번 춰보시겠습니까?",
  ui_story_5037_50371901_48_dialog_content = "네!",
  ui_story_5037_50371901_49_dialog_content = "자, 오로지 팬들만 생각하면서...",
  ui_story_5037_50371901_50_dialog_content = "(대단해. 방금 전의 분위기와 전혀 달라!)",
  ui_story_5037_50371901_51_dialog_content = "(그런데 골디랑 린네의 춤은 확실히 조금 다른 것 같은데?)",
  ui_story_5037_50371901_52_dialog_content = "어때요? 린네 씨, PlayerName 씨?",
  ui_story_5037_50371901_53_option_content = "린네의 춤과 무척 비슷해!",
  ui_story_5037_50371901_54_dialog_content = "그래? 정말 다행이야!",
  ui_story_5037_50371901_55_dialog_content = "아니요. 여전히 차이점이 있었습니다.",
  ui_story_5037_50371901_56_dialog_content = "뭐?",
  ui_story_5037_50371901_57_option_content = "골디만의 개성이 느껴져!",
  ui_story_5037_50371901_58_dialog_content = "뭐?",
  ui_story_5037_50371901_59_dialog_content = "골디의 춤이 좀 더 활기차고 경쾌한 것 같았어.",
  ui_story_5037_50371901_60_dialog_content = "이는 춤을 바치는 대상이 다르기 때문이겠지요.",
  ui_story_5037_50371901_61_dialog_content = "골디 님의 춤은 사람들을 위한 춤입니다. 저들을 향한 따뜻한 호의가 담겨 있지요.",
  ui_story_5037_50371901_62_dialog_content = "따라서 같은 동작이라 해도 전해지는 감정은 춤을 추는 자에 따라 천차만별인 것입니다.",
  ui_story_5037_50371901_63_dialog_content = "이것은 잘못된 것이 아니라 지극히 정상적인 것이니, 염려치 않으셔도 됩니다.",
  ui_story_5037_50371901_64_dialog_content = "골디 님의 춤과 마음은 유일무이한 것이니까요.",
  ui_story_5037_50371901_65_dialog_content = "네!",
  ui_story_5037_50371901_66_dialog_content = "가르쳐 주셔서 고마워요!",
  ui_story_5037_50372001_1_dialog_content = "오늘은 다른 곳에 와 봤어요. 그럼 촬영을 시작할 테니까 모두 집중해 주세요.",
  ui_story_5037_50372001_2_dialog_content = "3, 2, 1. 액션!",
  ui_story_5037_50372001_3_dialog_content = "벌써 찍는 거야? 크흠...",
  ui_story_5037_50372001_4_dialog_content = "지금부터 보컬 수업을 시작할게.",
  ui_story_5037_50372001_5_dialog_content = "니나 선생님, 안녕하세요!",
  ui_story_5037_50372001_6_dialog_content = "근데 역시 잘 모르겠어...",
  ui_story_5037_50372001_7_dialog_content = "보컬 연습을 한다고 들었는데, 보컬 연습실이 언제 극장으로 바뀐 거야?",
  ui_story_5037_50372001_8_dialog_content = "좋은 질문이야, PlayerName 학생.",
  ui_story_5037_50372001_9_dialog_content = "이번 수업은 연습이 아니라 듣기 위주거든.",
  ui_story_5037_50372001_10_dialog_content = "듣기?",
  ui_story_5037_50372001_11_dialog_content = "다른 사람의 노래를 듣는 것도 아이돌 트레이닝에서 중요한 부분이야!",
  ui_story_5037_50372001_12_dialog_content = "요새 팬들이 뭘 좋아하는지 알아야 인기 있는 곡을 만들 수 있을 테니까!",
  ui_story_5037_50372001_13_dialog_content = "맞아! 유행을 파악하고 좇는 것을 넘어서, 선도할 줄 알아야 해.\n그게 바로 비즈니스의 핵심이야!",
  ui_story_5037_50372001_14_dialog_content = "예를 들면 오늘 우리가 감상할 연극의 제목은 《팬텀 오브 스테이지》야.",
  ui_story_5037_50372001_15_dialog_content = "영원히 살아가는 한 연극배우의 이야기를 담고 있지.",
  ui_story_5037_50372001_16_dialog_content = "극 중에서 배우들이 보여주는 퍼포먼스의 변화는 움브라톤의 시대별 모습을\n표현하고 있어.",
  ui_story_5037_50372001_17_dialog_content = "뭔가 대단한 것 같은데?!",
  ui_story_5037_50372001_18_dialog_content = "유행 문화는 당시의 상황을 반영하기 마련이니까!",
  ui_story_5037_50372001_19_dialog_content = "맞아. 골디 학생한테 10점 추가.",
  ui_story_5037_50372001_20_dialog_content = "미노스, 교재를 나눠 줘.",
  ui_story_5037_50372001_21_dialog_content = "네, 아가씨.",
  ui_story_5037_50372001_22_dialog_content = "이건...?",
  ui_story_5037_50372001_23_dialog_content = "이건 아가씨께서 정성껏 준비하신 교재입니다.\n지난 십여 년 간 움브라톤에서 유행했던 노래와 공연 대본이 들어 있지요.",
  ui_story_5037_50372001_24_dialog_content = "소중히 간직해 주십시오.",
  ui_story_5037_50372001_25_dialog_content = "그, 그래...",
  ui_story_5037_50372001_26_dialog_content = "너흰 내 수업 시간을 통해 여기 들어있는 곡을 전부 익히고,\n움브라톤의 유행 흐름을 파악하게 될 거야.",
  ui_story_5037_50372001_27_dialog_content = "그래야 취향을 높이고, 유행에 맞는 노래를 지을 수 있을 테니까.",
  ui_story_5037_50372001_28_dialog_content = "니나, 노력해 줘서 고맙긴 한데...",
  ui_story_5037_50372001_29_dialog_content = "이거 너무 많은 거 아냐?!",
  ui_story_5037_50372001_30_dialog_content = "오늘 안에 이걸 전부 읽어야 하는 거야?",
  ui_story_5037_50372001_31_dialog_content = "아니, 전부 읽으라는 건 당연히 아니야. 그러면 너희들한테 너무 힘들잖아.",
  ui_story_5037_50372001_32_dialog_content = "그 안의 노래는 전부 오늘 연극에서 나올 거야.",
  ui_story_5037_50372001_33_dialog_content = "내가 정리한 완벽한 자료를 참고해서 시대별 유행의 차이를 느껴보도록 해!",
  ui_story_5037_50372001_34_dialog_content = "고마워요!",
  ui_story_5037_50372001_35_dialog_content = "응, 열심히 공부할게!",
  ui_story_5037_50372001_36_dialog_content = "공연이 곧 시작될 거야. 얼른 자리에 앉아.",
  ui_story_5037_50372001_37_dialog_content = "여러분, 그럼 이쪽으로.",
  ui_story_5037_50372001_38_dialog_content = "아가씨께서 VIP석을 예약해 두셨습니다.",
  ui_story_5037_50372001_39_dialog_content = "무대에서 엄청 가까워... 여기라면 공연을 생생하게 감상할 수 있어!",
  ui_story_5037_50372001_40_dialog_content = "<color=#828282>......</color>",
  ui_story_5037_50372001_41_dialog_content = "「근사한 풍경과 흥겨운 노랫소리, 시간이 쏜살같이 흐른다.」",
  ui_story_5037_50372001_42_dialog_content = "「아름다운 아가씨, 저와 함께 춤추시겠습니까?」",
  ui_story_5037_50372001_43_dialog_content = "이건 움브라톤에서 최초로 공연했던 연극이야. 제목은 《클리오와 제시카》라고 해.",
  ui_story_5037_50372001_44_dialog_content = "이거 알아요. 어렸을 때 각색된 스토리를 들은 적 있어요!",
  ui_story_5037_50372001_45_dialog_content = "원수 가문이지만 서로에게 반한 오로리안의 비극적인 러브 스토리잖아요.",
  ui_story_5037_50372001_46_dialog_content = "맞아. 보는 대로 이 시기의 움브라톤 문화는 백야성에서 많은 영향을 받았어.",
  ui_story_5037_50372001_47_dialog_content = "연극 속에서 당시 백야성 귀족의 생활상을 많이 엿볼 수 있을 거야. 예를 들면...",
  ui_story_5037_50372001_48_dialog_content = "(니나와 골디, 꽤 즐거워 보이네.)",
  ui_story_5037_50372001_49_dialog_content = "(멋진 공연이긴 하지만 난 백야성과 움브라톤의 역사에 대해서 전혀 모르는걸...)",
  ui_story_5037_50372001_50_dialog_content = "(졸려... 역시 잘 모르는 공연을 보려니까 졸음이 쏟아지는걸...)",
  ui_story_5037_50372001_51_dialog_content = "(그래도 니나가 열심히 준비한 건데...)",
  ui_story_5037_50372001_52_option_content = "(졸음을 참아야 해...)",
  ui_story_5037_50372001_53_dialog_content = "(안 돼, 자면 안 돼. 하나도 빠짐없이 봐야 해!)",
  ui_story_5037_50372001_54_dialog_content = "(이건 소중한 참고 자료니까!)",
  ui_story_5037_50372001_55_dialog_content = "<color=#828282>졸음을 참고 공연을 전부 감상했다</color>",
  ui_story_5037_50372001_56_dialog_content = "원래 움브라톤의 문화는 이런 복잡한 과정을 통해 발전했었구나! 이제야 알았어!",
  ui_story_5037_50372001_57_dialog_content = "나도 많은 걸 배웠어!",
  ui_story_5037_50372001_58_dialog_content = "절반은 못 알아듣긴 했지만...",
  ui_story_5037_50372001_59_dialog_content = "걱정할 거 없어. 중요한 내용은 내가 교재에 표시해 놨으니까.",
  ui_story_5037_50372001_60_dialog_content = "언제든지 교재를 보고 복습하면 될 거야.",
  ui_story_5037_50372001_61_dialog_content = "정말 고생하셨어요. 니나 씨!",
  ui_story_5037_50372001_62_option_content = "(잠을 못 참겠어...)",
  ui_story_5037_50372001_63_dialog_content = "(참아야 해.. 참아야... 쿠울...)",
  ui_story_5037_50372001_64_dialog_content = "<color=#828282>긴 시간이 흐른 뒤</color>",
  ui_story_5037_50372001_65_dialog_content = "PlayerName 씨? PlayerName 씨!",
  ui_story_5037_50372001_66_dialog_content = "골디 씨, 제가 하겠습니다.",
  ui_story_5037_50372001_67_dialog_content = "PlayerName 님, 일어나십시오!",
  ui_story_5037_50372001_68_dialog_content = "으엑?!",
  ui_story_5037_50372001_69_dialog_content = "PlayerName 씨, 어쩌다 자버린 거야? 공연이 벌써 끝났어.",
  ui_story_5037_50372001_70_dialog_content = "뭐?! 끝났다고?!",
  ui_story_5037_50372001_71_dialog_content = "골디한테 설명하는 데 집중했더니 네가 잠든 줄은 몰랐네...",
  ui_story_5037_50372001_72_dialog_content = "아가씨의 호의를 저버리다니, 끔찍한 죄를 범하셨군요...",
  ui_story_5037_50372001_73_dialog_content = "미, 미안해!",
  ui_story_5037_50372001_74_dialog_content = "내가 실수로 그만...",
  ui_story_5037_50372001_75_dialog_content = "괜찮아.",
  ui_story_5037_50372001_76_dialog_content = "네가 공연을 감상하면서 지식을 습득하지 못한 건 아쉽긴 하지만.",
  ui_story_5037_50372001_77_dialog_content = "그래도 중요한 내용은 내가 교재에 표시해 놨으니까.",
  ui_story_5037_50372001_78_dialog_content = "돌아가서 교재를 열심히 읽으면 어느 정도 도움이 될 거야.",
  ui_story_5037_50372001_79_dialog_content = "절대 안 졸고 열심히 읽을게!",
  ui_story_5037_50372001_80_dialog_content = "이번 공연에서 많은 걸 배웠으면 해.",
  ui_story_5037_50372001_81_dialog_content = "유행의 핵심은 대중의 니즈를 파악하는 거니까, 항상 귀와 눈을 열어놔야 해.",
  ui_story_5037_50372001_82_dialog_content = "내가 도와줄 수 있는 건 여기까지야. 앞으로는 두 사람이 계속 노력해야 할 거야.",
  ui_story_5037_50372001_83_dialog_content = "고마워요, 니나 씨, 그리고 미노스 씨!",
  ui_story_5037_50372001_84_dialog_content = "응! 정말 고마워!",
  ui_story_5037_50372101_1_dialog_content = "나랑 골디를 도우러 와 줘서 정말 고마워, 플뢰르...",
  ui_story_5037_50372101_2_dialog_content = "쉿──!",
  ui_story_5037_50372101_3_dialog_content = "어라? 플뢰르 씨, 문 앞에 엎드려서 뭐 하세요?",
  ui_story_5037_50372101_4_dialog_content = "PlayerName, 골디 씨. 일단 조용히 좀...",
  ui_story_5037_50372101_5_dialog_content = "......",
  ui_story_5037_50372101_6_dialog_content = "......",
  ui_story_5037_50372101_7_dialog_content = "휴, 다들 가버린 것 같아.",
  ui_story_5037_50372101_8_dialog_content = "플뢰르, 설마 또 미행당하는 거야?",
  ui_story_5037_50372101_9_dialog_content = "맞아...",
  ui_story_5037_50372101_10_dialog_content = "오는 길에 예전에 도와줬던 사람과 잠깐 인사한 게 고작인데...",
  ui_story_5037_50372101_11_dialog_content = "안녕하세요.",
  ui_story_5037_50372101_12_dialog_content = "어? 플뢰르 아냐? 지난번엔 큰 신세를 졌어! 정말 고마워!",
  ui_story_5037_50372101_13_dialog_content = "그 사람이 내 이름을 부르는 바람에 사람들이 점점 모여들고 말았어...",
  ui_story_5037_50372101_14_dialog_content = "뭐? 플뢰르 형! 지난번엔 정말 고마웠어요!",
  ui_story_5037_50372101_15_dialog_content = "플뢰르 씨, 전 플뢰르 씨 팬이에요!",
  ui_story_5037_50372101_16_dialog_content = "빠져나오는 데도 한참 걸렸고, 일부러 길을 멀리 돌아서 아무도 안 따라오는 걸\n확인하고 나서 여기까지 온 건데...",
  ui_story_5037_50372101_17_dialog_content = "인기가 너무 많은 것도 가끔은 정말 피곤한 일이구나...",
  ui_story_5037_50372101_18_dialog_content = "정말 부러워요. 저도 플뢰르 씨처럼 인기 있는 사람이 되고 싶어요!",
  ui_story_5037_50372101_19_dialog_content = "하지만 이건 무척 힘든 일이야.",
  ui_story_5037_50372101_20_dialog_content = "힘든 건 무섭지 않아요!",
  ui_story_5037_50372101_21_dialog_content = "더 많은 사람들의 관심 속에서 제 춤과 노래를 선보일 수 있으면 정말 기쁠 것 같아요!",
  ui_story_5037_50372101_22_dialog_content = "그렇게 생각한다면 나도 어쩔 수 없지.",
  ui_story_5037_50372101_23_dialog_content = "하지만 사람들이 날 좋아하는 건 그저 내가 특수한 체질이라서 그런 것뿐이야.",
  ui_story_5037_50372101_24_dialog_content = "이런 체질은 가르쳐서 배울 수 있는 게 아니거든...",
  ui_story_5037_50372101_25_dialog_content = "네?",
  ui_story_5037_50372101_26_dialog_content = "게다가 어떻게 해야 사람들이 좋아해 주는 건지 사실 나도 잘 몰라.",
  ui_story_5037_50372101_27_dialog_content = "난 이 특수한 체질 때문에 지금까지 대부분 사람들의 관심을 덜 받는 방법이나,\n심지어 미움을 받는 방법만 연구해 왔거든.",
  ui_story_5037_50372101_28_dialog_content = "그런 건가요...",
  ui_story_5037_50372101_29_dialog_content = "그럼 곤란한데...",
  ui_story_5037_50372101_30_dialog_content = "아, 방법이 있어요!",
  ui_story_5037_50372101_31_dialog_content = "무슨 좋은 생각 있어?",
  ui_story_5037_50372101_32_dialog_content = "플뢰르 씨는 인기가 없어지는 방법을 연구했으니까 우린 반대로 하면 되지 않을까?",
  ui_story_5037_50372101_33_dialog_content = "그러니까 플뢰르 씨의 방법을 배운 다음에, 전부 거꾸로 해보겠다는 거야?",
  ui_story_5037_50372101_34_dialog_content = "그러면 인기를 끌지 않는 방법을 인기를 끄는 방법으로 바꿀 수 있다는 거지?",
  ui_story_5037_50372101_35_dialog_content = "맞아, 역시 내 프로듀서답게 이해가 빠르다니까!",
  ui_story_5037_50372101_36_dialog_content = "근데 그게 정말 될까?",
  ui_story_5037_50372101_37_dialog_content = "직접 해보면 알겠지. 플뢰르 씨, 부탁드려요!",
  ui_story_5037_50372101_38_dialog_content = "좋아... 사람들의 관심을 끌지 않는 방법과 미움을 받는 방법 중에서 뭘 배우고 싶어?",
  ui_story_5037_50372101_39_dialog_content = "PlayerName 씨, 어느 걸 배우는 게 좋을까?",
  ui_story_5037_50372101_40_dialog_content = "(거꾸로 쓸 생각이라면 사람들이 싫어하는 일일수록 거꾸로 했을 때\n효과가 더 크겠지?)",
  ui_story_5037_50372101_41_option_content = "사람들의 관심을 끌지 않는 방법을 배울래.",
  ui_story_5037_50372101_42_dialog_content = "사람들의 관심을 끌지 않는 방법은 간단해, 다른 사람들이랑 똑같아지는 거지.",
  ui_story_5037_50372101_43_dialog_content = "다른 사람들과 다르지 않게 행동하고, 자신의 개성을 숨기면 돼.",
  ui_story_5037_50372101_44_dialog_content = "왠지 무척 쉬울 것 같네요!",
  ui_story_5037_50372101_45_dialog_content = "사람들의 관심을 받고 싶지 않으면 평범한 옷을 입고, 고개를 숙인 채 걸으면 돼.",
  ui_story_5037_50372101_46_dialog_content = "가끔은 얼굴을 가리는 모자도 쓰고!",
  ui_story_5037_50372101_47_dialog_content = "그걸 딱 반대로 하면 고개를 치켜든 채 거리를 돌아다니고,\n제 춤과 노래를 보여주면 되겠네요?",
  ui_story_5037_50372101_48_dialog_content = "좀 이상하게 들리긴 하지만... 그래도 골디의 춤과 노래는 다 근사하니까...",
  ui_story_5037_50372101_49_dialog_content = "괜찮을 것 같아!",
  ui_story_5037_50372101_50_option_content = "미움을 받는 방법을 배울래.",
  ui_story_5037_50372101_51_dialog_content = "미움을 받는 방법은 조금 까다로워.",
  ui_story_5037_50372101_52_dialog_content = "전에 난 몇 가지 방법을 시도해 봤어. 이상하게 걸어 다니거나, 허름한 옷을 입은 채\n지저분한 모습으로 꾸며보기도 했고...",
  ui_story_5037_50372101_53_dialog_content = "효과는 괜찮았지만, 대신 몇 번이나 도둑으로 오해를 받았어...",
  ui_story_5037_50372101_54_dialog_content = "근데 내 체질 때문에 사람들이 날 알아채고 나면, 아무리 꾸며도 소용이 없어.",
  ui_story_5037_50372101_55_dialog_content = "대충 알 것 같아요.",
  ui_story_5037_50372101_56_dialog_content = "반대로 하면 단정한 태도, 깨끗한 옷차림과 당당한 몸가짐이면 된다는 거죠?",
  ui_story_5037_50372101_57_dialog_content = "그리고 항상 긍정적이고, 아이돌 가수다운 미소를 유지할 것!",
  ui_story_5037_50372101_58_dialog_content = "그러면 될 것 같아!",
  ui_story_5037_50372101_59_dialog_content = "어떤 방법을 쓰든 「몸가짐」이 중요해.",
  ui_story_5037_50372101_60_dialog_content = "골디 씨는 춤을 잘 추니까 비슷한 경험이 분명히 있을 거야.",
  ui_story_5037_50372101_61_dialog_content = "맞아요! 춤출 때는 「몸가짐」이 정말 중요해요.\n허리를 곧게 펼 때와 잔뜩 구부린 채 추는 춤은 전혀 다르거든요!",
  ui_story_5037_50372101_62_dialog_content = "아무튼 고마워요, 플뢰르 씨.",
  ui_story_5037_50372101_63_dialog_content = "천만에. 내 도움이 또 필요하면 언제든지 말해줘.",
  ui_story_5037_50372101_64_dialog_content = "사람들이 플뢰르를 좋아하는 건 다른 사람을 기꺼이 도우려는 배려심 때문도 있어.",
  ui_story_5037_50372101_65_dialog_content = "그, 그런가?",
  ui_story_5037_50372101_66_dialog_content = "하지만 도움이 필요한 사람을 모른 척할 순 없잖아...",
  ui_story_5037_50372101_67_dialog_content = "플뢰르는 지금 이대로의 모습이 좋아. 바꿀 필요 없어!",
  ui_story_5037_50372101_68_dialog_content = "그렇구나, 알겠어.",
  ui_story_5037_50372101_69_dialog_content = "고마워, PlayerName.",
  ui_story_5037_50372101_70_dialog_content = "다른 사람을 돕고, 정의를 실천한다면 사람들이 좋아하는 것도 당연하죠!",
  ui_story_5037_50372101_71_dialog_content = "PlayerName 씨, 우리도 새로 배운 노하우를 얼른 시도해 보자!",
  ui_story_5037_50372101_72_dialog_content = "지금?!",
  ui_story_5037_50372101_73_dialog_content = "쇠뿔도 단김에 빼야 한다잖아, 그러니까 지금 나가서...",
  ui_story_5037_50372101_74_dialog_content = "잠깐만, 골디 씨! 지금 문 열면 안 돼!",
  ui_story_5037_50372101_75_dialog_content = "네?",
  ui_story_5037_50372101_76_dialog_content = "<color=#828282>벌컥──</color>",
  ui_story_5037_50372101_77_dialog_content = "(문밖에 사람들이 왜 이리 많아?!)",
  ui_story_5037_50372101_78_dialog_content = "플뢰르 씨가 여기 있는 건가?",
  ui_story_5037_50372101_79_dialog_content = "방금 누가 플뢰르 형의 이름을 부르는 것 같았어!",
  ui_story_5037_50372101_80_dialog_content = "플뢰르 씨~ 왜 도망치는 거예요!",
  ui_story_5037_50372101_81_dialog_content = "여, 여러분! 일단 진정을...",
  ui_story_5037_50372101_82_dialog_content = "플뢰르 씨, 사랑해요!",
  ui_story_5037_50372101_83_dialog_content = "엄청난 매력이네!",
  ui_story_5037_50372101_84_dialog_content = "확실히 인기가 너무 많은 것도 조금 힘들 것 같긴 하네...",
  ui_story_5037_50372201_1_dialog_content = "「천재는 언제나 외로운 법!」",
  ui_story_5037_50372201_2_dialog_content = "「그들은 외로움을 먹고, 외로움 속에서 답을 구하며,\n외로움이라는 땅에서 예술의 꽃을 피운다.」",
  ui_story_5037_50372201_3_dialog_content = "「그래서 외로움은 적이 아니라 동료이자, 소중한 친구다!」",
  ui_story_5037_50372201_4_dialog_content = "정말 대단해요!",
  ui_story_5037_50372201_5_dialog_content = "그건 《그림자의 제왕》 속 대사죠?",
  ui_story_5037_50372201_6_dialog_content = "고맙군. 아름다운 레이디여.\n내 공연을 감상할 수 있다는 건, 남다른 예술적 소양을 지녔다는 뜻이지.",
  ui_story_5037_50372201_7_dialog_content = "잠깐만요, 카론 씨! 설명부터 좀 해 주세요!",
  ui_story_5037_50372201_8_dialog_content = "우리가 떠난 지 고작 10분밖에 안 됐는데 연습실에 왜\n헤븐즈 밸리 무대 배경이 세워진 거죠?!",
  ui_story_5037_50372201_9_dialog_content = "놀랄 거 없다. 일루미나의 공병들은 아스트라 최고의 기술자들이니까.",
  ui_story_5037_50372201_10_dialog_content = "공병들은 이런 일 하는 사람들이 아니지 않나요...",
  ui_story_5037_50372201_11_dialog_content = "무대 배경이 정말 근사해요. 들어오자마자 진짜 헤븐즈 밸리에 온 줄 알았어요!",
  ui_story_5037_50372201_12_dialog_content = "친구여, 날 믿어라. 이건 레이디의 연기 수업을 위해 준비한 거다.",
  ui_story_5037_50372201_13_dialog_content = "진짜요?",
  ui_story_5037_50372201_14_dialog_content = "실천에서 참된 지식을 얻는다는 말이 있지.\n직접 연기해 봐야만 연기에 대한 깨달음을 얻을 수 있는 법이다.",
  ui_story_5037_50372201_15_dialog_content = "난 두 사람이 연기의 매력을 느끼길 바라는 마음으로 이 무대 배경과 대본을\n직접 준비했다.",
  ui_story_5037_50372201_16_dialog_content = "진짜 잘됐네요! 아이돌 활동 중에도 가끔 연극에 참여해야 할 때가 있거든요.",
  ui_story_5037_50372201_17_dialog_content = "전문 배우한테 배우면 제 연기 실력도 크게 늘 거예요!",
  ui_story_5037_50372201_18_dialog_content = "그렇다면 어서 시작해 보도록 하지.",
  ui_story_5037_50372201_19_dialog_content = "자, 이건 내가 직접 준비한 대본이다.",
  ui_story_5037_50372201_20_dialog_content = "이건...",
  ui_story_5037_50372201_21_dialog_content = "대사가 좀 다른 것 같긴 한데... 이거 《아이다와 콜로서스》 아니에요?",
  ui_story_5037_50372201_22_dialog_content = "그렇다. 내가 특별히 그 동화의 줄거리를 각색해서 만든 대본이지.",
  ui_story_5037_50372201_23_dialog_content = "동화는 이야기가 단조로운 편이라 이해하기도 쉽지.\n연기 초보자에게도 그리 어렵진 않을 거다.",
  ui_story_5037_50372201_24_dialog_content = "역시 카론 씨는 정말 꼼꼼하다니까요!",
  ui_story_5037_50372201_25_dialog_content = "그야 당연하지. 나 역시 아무것도 모르는 연기 초보자에서부터\n지금과 같은 연기 천재로 성장했으니까.",
  ui_story_5037_50372201_26_dialog_content = "PlayerName, 우리 그럼 역할을 정해볼까?",
  ui_story_5037_50372201_27_dialog_content = "좋아. 콜로서스에 대해선 내가 잘 아니까, 내가 윈드러너호 역할을 할게.",
  ui_story_5037_50372201_28_dialog_content = "그럼 난 아이다 역할을 맡을게!",
  ui_story_5037_50372201_29_dialog_content = "아이다는 호기심도 강하고, 활기차서 정말 귀여운 캐릭터인 것 같아!",
  ui_story_5037_50372201_30_dialog_content = "그렇다면 내레이션과 나머지 역할은 내가 맡도록 하지.",
  ui_story_5037_50372201_31_dialog_content = "이제 역할 분담도 끝났으니 연기를 시작해 볼까.",
  ui_story_5037_50372201_32_dialog_content = "「고요한 헤븐즈 밸리에 「윈드러너호」라는 이름의 콜로서스가 정박해 있었다.」",
  ui_story_5037_50372201_33_dialog_content = "「윈드러너호는 하늘을 동경했지만, 조종사가 없는 탓에 지상에 묶여 있어야 했다.」",
  ui_story_5037_50372201_34_dialog_content = "「콜로서스는 하늘을 위해 태어난 거야!」",
  ui_story_5037_50372201_35_dialog_content = "「육지형도, 해양형도 있지만, 하늘만이 콜로서스의 고향인 거지!」",
  ui_story_5037_50372201_36_dialog_content = "「좋겠다... 조종사가 있다는 건 대체 어떤 기분일까...」",
  ui_story_5037_50372201_37_dialog_content = "「조종사가 있다는 건, 친구가 생긴 기분일 거야.」",
  ui_story_5037_50372201_38_dialog_content = "「깜짝이야! 누구야?! 어떻게 나랑 대화할 수 있는 거지...」",
  ui_story_5037_50372201_39_dialog_content = "「설마 유령이야?! 아이테르가 이런 낡아빠진 콜로서스한테 올 리가 없어.」",
  ui_story_5037_50372201_40_dialog_content = "「그치만 네 앞에 있는 건 아이테르인걸.」",
  ui_story_5037_50372201_41_dialog_content = "「아이다는 윈드러너호에 다가가 꽃처럼 생긴 그의 머리를 살피더니,\n손을 내밀어 쓰다듬었다.」",
  ui_story_5037_50372201_42_dialog_content = "(잠깐만, 머리를 쓰다듬어? 내 대본엔 그런 내용은 없는데...)",
  ui_story_5037_50372201_43_dialog_content = "(어떻게 하지? 계속 연기해야 하는 건가?)",
  ui_story_5037_50372201_44_option_content = "(계속 연기한다)",
  ui_story_5037_50372201_45_dialog_content = "「쓰다듬어 줄게.」",
  ui_story_5037_50372201_46_dialog_content = "「야야야, 아이테르면 남의 말을 몰래 엿듣고 초면부터 막 남의 머리를\n쓰다듬어도 되는 거야?」",
  ui_story_5037_50372201_47_dialog_content = "「내 아름다운 머리는 아무나 만져도 되는 게 아니라고.」",
  ui_story_5037_50372201_48_dialog_content = "「응, 정말 예뻐. 게다가 예쁜 꽃도 피어 있어.」",
  ui_story_5037_50372201_48X1_dialog_content = "컷!",
  ui_story_5037_50372201_49_dialog_content = "아주 잘했다, PlayerName!",
  ui_story_5037_50372201_50_dialog_content = "네?",
  ui_story_5037_50372201_51_option_content = "(질문한다)",
  ui_story_5037_50372201_52_dialog_content = "잠깐만요, 대본에는 그런 내용이 없는데요?",
  ui_story_5037_50372201_52X1_dialog_content = "컷!",
  ui_story_5037_50372201_53_dialog_content = "대본에는 확실히 그런 내용이 없지.",
  ui_story_5037_50372201_54_dialog_content = "내 대본에도 없어...",
  ui_story_5037_50372201_55_dialog_content = "대체 어떻게 된 거예요, 카론 씨?",
  ui_story_5037_50372201_56_dialog_content = "연기에는 대본이 있지만 연기하는 건 결국 사람이다.",
  ui_story_5037_50372201_57_dialog_content = "연기를 하다 보면 언제나 다양한 상황이 벌어지기 마련이지.\n항상 대본대로 연기할 수 있는 건 아니다.",
  ui_story_5037_50372201_58_dialog_content = "그래서 훌륭한 배우라면 임기응변 능력도 있어야 하는 법이다!",
  ui_story_5037_50372201_59_dialog_content = "그런 거였군요!",
  ui_story_5037_50372201_60_dialog_content = "맞아요! 예전에 본 공연에서도 대사와 대본이 다른 상황을 가끔 본 적 있었어요.",
  ui_story_5037_50372201_61_dialog_content = "근데 배우들 연기가 자연스러워서 전혀 이상하게 안 느껴졌거든요.",
  ui_story_5037_50372201_62_dialog_content = "임기응변도 연기의 일부다.",
  ui_story_5037_50372201_63_dialog_content = "네 캐릭터를 이해하고 거기에 몰입해야 자연스러운 연기도 가능한 것이지.",
  ui_story_5037_50372201_64_dialog_content = "네, 알겠어요!",
  ui_story_5037_50372201_65_dialog_content = "이 방식대로 계속 노력해서 연기 실력을 갈고닦을게요!",
  ui_story_5037_50379901_1_dialog_content = "이상하네...",
  ui_story_5037_50379901_2_dialog_content = "너무 이상해!",
  ui_story_5037_50379901_3_dialog_content = "며칠 전부터 바이스랑 카렌이 자꾸 일부러 날 피하고 있는 것 같은데...",
  ui_story_5037_50379901_4_dialog_content = "내가 뭔가 실수해서 둘 다 기분이 상했나?",
  ui_story_5037_50379901_5_dialog_content = "설마 저번에...",
  ui_story_5037_50379901_6_option_content = "함교에서 있었던 일 때문인가?",
  ui_story_5037_50379901_7_dialog_content = "음~ 이 옷은 오랜만에 입는데, 아직은 느낌이 괜찮네.",
  ui_story_5037_50379901_8_dialog_content = "PlayerName, 네가 볼 땐 어때?\n이거랑 내가 평소에 입는 일루미나 제복이랑 어떤 게 더 예뻐?",
  ui_story_5037_50379901_9_dialog_content = "어? 잘 모르겠는데.",
  ui_story_5037_50379901_10_dialog_content = "......",
  ui_story_5037_50379901_11_dialog_content = "그때 그냥 둘 다 예쁘다고 할걸!",
  ui_story_5037_50379901_12_option_content = "휴식실에서 있었던 일 때문인가?",
  ui_story_5037_50379901_13_dialog_content = "PlayerName?!",
  ui_story_5037_50379901_14_dialog_content = "빨리 뒤돌아! 네가 왜 여기 있는 거야?!",
  ui_story_5037_50379901_15_dialog_content = "가, 갑자기 목이 말라서 뭐 좀 마시려고 온 건데...",
  ui_story_5037_50379901_16_dialog_content = "방금... 뭘 봤어?",
  ui_story_5037_50379901_17_dialog_content = "응? 카렌이 잠옷 입고 기분 좋게 거울 앞에서 포즈 잡고 있던 거?",
  ui_story_5037_50379901_18_dialog_content = "잘못 본 거야!",
  ui_story_5037_50379901_19_dialog_content = "그때 그냥 아무것도 못 봤다고 할걸!",
  ui_story_5037_50379901_20_dialog_content = "하지만 이런 걸로 두 사람이 날 무시한단 말이야...?",
  ui_story_5037_50379901_21_dialog_content = "아아악! 대체 뭐 때문이지? 생각하면 할수록 머리만 복잡해지잖아!",
  ui_story_5037_50379901_22_dialog_content = "이제 곧 새해인데 이런 어색한 분위기로 새해를 맞이할 순 없어...",
  ui_story_5037_50379901_23_dialog_content = "차라리 그냥 두 사람한테 바로 물어보는 편이 나으려나?",
  ui_story_5037_50379901_24_dialog_content = "<color=#e8d9bb>똑똑똑!</color>",
  ui_story_5037_50379901_25_dialog_content = "바이스, 카렌, 안에 있어?",
  ui_story_5037_50379901_26_dialog_content = "<size=33>어? PlayerName?! 왜 하필 이 타이밍에 온 거야?</size>",
  ui_story_5037_50379901_27_dialog_content = "<size=33>...어서! 서둘러!</size>",
  ui_story_5037_50379901_28_dialog_content = "마침 잘 왔어, PlayerName.",
  ui_story_5037_50379901_29_dialog_content = "나랑 카렌이 널 찾으러 가려던 참이었거든. 들어와.",
  ui_story_5037_50379901_30_dialog_content = "며칠 전까지만 해도 둘 다 나랑 말도 안 하고 막 피해 다니더니, 갑자기 왜 그러는 거야?",
  ui_story_5037_50379901_31_dialog_content = "그건~ 일단 들어와 보면 알아~",
  ui_story_5037_50379901_32_dialog_content = "저... 방에 불은 왜 끈 거야? 캄캄해서 이상하고 무서워.",
  ui_story_5037_50379901_33_dialog_content = "불이 꺼져 있어야 효과가 더 좋거든.",
  ui_story_5037_50379901_34_dialog_content = "효과? 무슨 효과?!",
  ui_story_5037_50379901_35_dialog_content = "이제 곧 시작하니까, 앞을 잘 봐 봐.",
  ui_story_5037_50379901_36_dialog_content = "어?",
  ui_story_5037_50379901_38_dialog_content = "우와, 시간 참 빠르네~ 그렇지?",
  ui_story_5037_50379901_39_dialog_content = "어느샌가 또 한 해가 끝나려 하고 있어.",
  ui_story_5037_50379901_40_dialog_content = "시간이 빠르게 지나갔다고 느끼는 건 사실 무척 좋은 일이야.",
  ui_story_5037_50379901_41_dialog_content = "그만큼 우리가 올 한 해를 충실히 보냈다는 거니까.",
  ui_story_5037_50379901_42_dialog_content = "하하, 난 조종사랑 같이 모험을 시작하고 나서부터 매일매일 충실히 지내고 있어!",
  ui_story_5037_50379901_43_dialog_content = "그래? 그럼 한 번 테스트해 봐야겠는걸.",
  ui_story_5037_50379901_44_dialog_content = "우리가 올 한 해 동안 어떤 곳들에 갔었는지 기억나?",
  ui_story_5037_50379901_45_dialog_content = "후훗, 당연히 다 기억하고 있지!",
  ui_story_5037_50379901_46_dialog_content = "작년 이맘때엔 거센 바람을 뚫고 북방에 갔었어.",
  ui_story_5037_50379901_47_dialog_content = "그때 처음으로 진짜 오로라랑 수정처럼 투명한 윈터 팰리스를 봤어!",
  ui_story_5037_50379901_48_dialog_content = "그리고 북방에서 처음으로 완자 튀김에 딸기잼을 찍어 먹어 봤는데, 진짜 맛있더라!",
  ui_story_5037_50379901_49_dialog_content = "그때 조종사는 한참을 거울 호수 옆에서 있었어.\n여왕님의 과거를 봤다면서 말이야...",
  ui_story_5037_50379901_50_dialog_content = "여왕님의 과거는 대체 어떤 모습이었을까? 나도 직접 볼 수 있었으면 좋겠어.",
  ui_story_5037_50379901_51_dialog_content = "그리고 우리 모두 등불 나무를 화려하게 장식하고,\n그 아래에서 새해맞이 카운트다운도 했었어!",
  ui_story_5037_50379901_52_dialog_content = "정말 그립네~",
  ui_story_5037_50379901_53_dialog_content = "완자 튀김이 그리운 거지?",
  ui_story_5037_50379901_54_dialog_content = "에헤헤헤...",
  ui_story_5037_50379901_55_dialog_content = "북방에서 돌아오는 길에는 실수로 지하에 있는 「고대 도시」에 떨어졌었지.",
  ui_story_5037_50379901_56_dialog_content = "거기서 우린 로봇의 공격을 피하려고 고대의 의복으로 갈아입었고 말이야.",
  ui_story_5037_50379901_57_dialog_content = "하하, 치마를 입은 PlayerName 모습이 아직도 생각나!",
  ui_story_5037_50379901_58_dialog_content = "나중에는 우리처럼 고대 도시에 갇힌 친구들을 만났었지.",
  ui_story_5037_50379901_59_dialog_content = "처음에는 서로의 관점이 달라 다투기도 했지만.",
  ui_story_5037_50379901_60_dialog_content = "결국에는 모두 힘을 합쳐 고대 도시에 사는 두 소녀를 설득했고...",
  ui_story_5037_50379901_61_dialog_content = "지하성이 파괴돼 버리기 전에 함께 탈출할 수 있었어.",
  ui_story_5037_50379901_62_dialog_content = "조종사는 돌아온 뒤에도 그 도시에서 보낸 통신을 받았었잖아.",
  ui_story_5037_50379901_63_dialog_content = "어쩌면 우린 언젠가 그 도시에 다시 한번 갈 기회가 있을지도 몰라.",
  ui_story_5037_50379901_64_dialog_content = "음... 그리고 그 뒤에도... 우린 바쁘게 지냈어!",
  ui_story_5037_50379901_65_dialog_content = "붉은 꽃 꺾어 님에게 주니──",
  ui_story_5037_50379901_66_dialog_content = "꽃잎은 옥설 위에 떨어지네.",
  ui_story_5037_50379901_67_dialog_content = "그때 우린 의뢰를 받아서 강부성에 가게 됐고, 그 도시의 무녀를 만났잖아.",
  ui_story_5037_50379901_68_dialog_content = "마침 「춘일제」라서 온 도시의 벚꽃이 분홍색으로 물들었었고.",
  ui_story_5037_50379901_69_dialog_content = "그렇게나 평화로운 분위기였는데...",
  ui_story_5037_50379901_70_dialog_content = "그떈 그런 무서운 위기가 숨어 있을 줄은 정말 몰랐어.",
  ui_story_5037_50379901_71_dialog_content = "증오의 불길은 번성했던 과거를 모조리 잿더미로 만들었어.",
  ui_story_5037_50379901_72_dialog_content = "그 도시에 남겨진 건...",
  ui_story_5037_50379901_73_dialog_content = "또 어떤 가슴 아픈 이별들일까?",
  ui_story_5037_50379901_74_dialog_content = "그때 난 같이 못 갔으니까, 그 질문엔 답해줄 수 없을 것 같네.",
  ui_story_5037_50379901_75_dialog_content = "카렌은 그때 백야성으로 돌아갔었잖아...",
  ui_story_5037_50379901_76_dialog_content = "다음엔 절대 잊지 않고 부를게!",
  ui_story_5037_50379901_77_dialog_content = "어? 잠깐만, 근데 카렌 너 나중에 백야성에 조종사를 초대해서\n공연을 보여 줬을 때는 날 안 불렀었잖아?",
  ui_story_5037_50379901_78_dialog_content = "정확히 말하면 공연을 보여 주려고 부른 게 아니라, 그레텔을 찾기 위해서였어.",
  ui_story_5037_50379901_79_dialog_content = "어쨌든 그때 우린 단서들을 통해 「진실의 관」이란 걸 찾아냈고...",
  ui_story_5037_50379901_80_dialog_content = "그 안에 있던 건 꼭두각시처럼 이성이 없는 사람들이었어.",
  ui_story_5037_50379901_81_dialog_content = "내 말 믿어...",
  ui_story_5037_50379901_82_dialog_content = "바이스 넌 그 공연을 안 봐서 정말 다행이라고 생각할걸.",
  ui_story_5037_50379901_83_dialog_content = "헤에? 카렌이 그렇게 얘기하니까 오히려 더 궁금해지잖아!",
  ui_story_5037_50379901_84_dialog_content = "근데 우리 뭔가 빼먹지 않았어?",
  ui_story_5037_50379901_85_dialog_content = "조종사가 레디젤 사막에 갔을 때 얘기지? 그땐 너도 따라갔잖아?",
  ui_story_5037_50379901_86_dialog_content = "아! 맞네... 버닝 랠리!\n그때 난 진짜로 조종사가 사메야마한테 납치당한 줄 알았단 말이야.",
  ui_story_5037_50379901_87_dialog_content = "그리고 나도 랠리가 거의 끝날 때쯤에 거기 도착했구.",
  ui_story_5037_50379901_88_dialog_content = "조종사가 어쩌다 조수석에 앉아서 드라이브를 하게 됐는지...",
  ui_story_5037_50379901_89_dialog_content = "또 어쩌다 아주르 씨의 과거 얘길 듣게 된 건지는...",
  ui_story_5037_50379901_90_dialog_content = "나도 자세히는 몰라.",
  ui_story_5037_50379901_91_dialog_content = "내가 아는 건 그때부터 왠지 모르게 레디젤 바비큐가 맛있다고 느껴지기 시작했단 거야!",
  ui_story_5037_50379901_92_dialog_content = "그래? 그때 이후로 최고의 미식가에 한 걸음 더 가까워진 모양이구나.",
  ui_story_5037_50379901_93_dialog_content = "카렌, 너도 그렇게 생각한 거야?",
  ui_story_5037_50379901_94_dialog_content = "역시 난 요리에 천부적인 재능이 있다니까!",
  ui_story_5037_50379901_95_dialog_content = "조만간 PlayerName한테 또 새로운 요리를 만들어 줘야겠어~",
  ui_story_5037_50379901_96_dialog_content = "근데 우리가 없을 때 조종사가 집사를 고용했었다는 얘길 들었어.",
  ui_story_5037_50379901_97_dialog_content = "아마 그때...",
  ui_story_5037_50379901_98_dialog_content = "꽤 다양한 요리를 먹지 않았을까?",
  ui_story_5037_50379901_99_dialog_content = "사실 그땐 PlayerName 곁에 나도, 카렌도 없으니까 걱정이 많이 됐거든.",
  ui_story_5037_50379901_100_dialog_content = "근데 이제 보니까 PlayerName도 혼자서 충분히 잘할 수 있던 것 같아!",
  ui_story_5037_50379901_101_dialog_content = "이젠 헤븐즈 가든의 주인으로서 여러 손님을 초대하기도 하고...",
  ui_story_5037_50379901_102_dialog_content = "헤븐즈 가든도 엄청 잘 관리하고 있잖아!",
