  ui_story_5037_50379901_104_dialog_content = "하지만 내가 보기엔 아직도 조종사는 누군가가 곁에 있어야 할 것 같아.",
  ui_story_5037_50379901_105_dialog_content = "아니면 납치를 당해 놓고도 다른 사람을 도와 돈을 세 주고 있을 테니까.",
  ui_story_5037_50379901_106_dialog_content = "조종사가 만난 게 그냥 환상동물 트레이너들이라서 정말 다행이었어.",
  ui_story_5037_50379901_107_dialog_content = "도중에 어떤 일들이 있었는지는...",
  ui_story_5037_50379901_108_dialog_content = "우리도 《환상동물 탐사 대모험》이란 책을 보고 알아낼 수밖에 없었지만 말이야.",
