  ui_story_5037_50379901_110_dialog_content = "어라? 그랬어? 언제?",
  ui_story_5037_50379901_111_dialog_content = "우리 다 같이 하버 시티에 갔을 때, 피아와 만났었잖아?",
  ui_story_5037_50379901_112_dialog_content = "아~ 그때 말하는 거구나.",
  ui_story_5037_50379901_113_dialog_content = "에메랄드호의 카니발에도 참가해서 진짜 재미있게 놀았었잖아!",
  ui_story_5037_50379901_114_dialog_content = "그땐 우린 아무도 몰랐어...",
  ui_story_5037_50379901_115_dialog_content = "즐거운 카니발 뒤에는 엘비스 성주가 오랫동안 계획해 왔던 음모가 있었다는 걸 말이야.",
  ui_story_5037_50379901_116_dialog_content = "비록 나중에는 엘비스 영주의 고충을 이해할 순 있었지만...",
  ui_story_5037_50379901_117_dialog_content = "그래도 한 도시의 성주로서 그렇게 무모한 행동을 벌여선 안 되는 거였어.",
  ui_story_5037_50379901_118_dialog_content = "하지만 그 사람이 하버 시티의 시민들을 위해 자신을 희생해서 재앙을 막으려는 걸 보고...",
  ui_story_5037_50379901_119_dialog_content = "난 깨달았어. 사람을 선과 악이라는 이분법적인 방식으로 판단할 순 없다는걸.",
  ui_story_5037_50379901_120_dialog_content = "제노 씨가 엘비스 씨를 깨울 방법을 찾았는지 모르겠네.",
