  ui_story_5037_50379901_123_dialog_content = "하버 시티에서 돌아온 뒤에 조종사는 연쇄 살인 사건의 범인을 찾던\n와타리 씨를 만났다고 했었어.",
  ui_story_5037_50379901_124_dialog_content = "그리고 단서들을 따라 「낙원」이라 불리는 작은 도시, 유포리아에 가게 됐고 말이야.",
  ui_story_5037_50379901_125_dialog_content = "말로는 「낙원」이라고 하지만, 거긴 몇 년간 클랜들의 내부 항쟁으로 혼란에 빠진 곳이었어.",
